INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$5ebce8cb-6878-5b4a-8c69-89a05693d36f$ml$::uuid, $ml$robotics$ml$, 1, 1, $ml${"id": "robotics-d1-c1", "title": "Amazon's million robots", "lessonTitle": "Three kinds of robots", "slot": 1, "type": "apply", "brief": {"headline": "In July 2025, Amazon said it had deployed its 1 millionth robot. Its robot network spans more than 300 facilities worldwide.", "kicker": "Apply the three types: which kind of robot is Amazon running?", "fullText": "Amazon's robots work in fulfillment centers. Some move shelving to workers, some carry totes, some pick single items with suction cups, and some roam the floor among people.\n\nAmazon said a new AI model, DeepFleet, would cut the fleet's travel times by 10%. It also said its newest site in Shreveport, Louisiana, needs 30% more employees in reliability, maintenance and engineering roles.\n\nNone of these machines weld or paint on a car line. By the day 1 map, warehouse robots are service robots, not industrial ones.", "sources": [{"url": "https://www.therobotreport.com/amazon-launches-new-ai-foundation-model-deploys-1-millionth-robot/", "label": "The Robot Report, Amazon deploys its 1 millionth robot, Jul 2025"}, {"url": "https://ifr.org/ifr-press-releases/news/global-robot-demand-in-factories-doubles-over-10-years", "label": "IFR, World Robotics 2025 press release"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Amazon's robots move goods inside warehouses. Which type does the day 1 lesson put them in?", "options": ["Industrial robots", "Service robots", "Collaborative robots only"], "correctIndex": 1, "explanation": "Warehouse robots work beyond the factory line, so they count as service robots. Industrial robots are the factory arms that weld, paint and assemble."}, "numbers": {"kind": "numberSense", "prompt": "Amazon's Shreveport site needs how many percent more reliability, maintenance and engineering staff?", "min": 0, "max": 100, "value": 30, "unit": "%", "explanation": "Amazon said 30% more. More robots shifted the jobs toward keeping machines running."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a role on Amazon's robotics side. The interviewer asks what changes as robots spread.", "prompt": "Which answer shows you read the numbers?", "options": ["Fewer engineers needed per site", "The robots replace all floor staff", "More jobs keeping robots running"], "correctIndex": 2, "consequences": ["Amazon said the opposite: its newest site needs more of these roles.", "Amazon described robots working alongside people, not replacing every role.", "Shreveport needs 30% more reliability, maintenance and engineering staff."], "explanation": "Amazon tied its newest site to 30% more reliability, maintenance and engineering staff. Robots shift work toward keeping the fleet running."}, "proReasoning": "Strong candidates link robot growth to the roles it creates. Citing the 30% figure shows you know where hiring goes.", "commonMistake": "Assuming more robots always means fewer technical jobs.", "mentalModel": "Robots create maintenance work."}, "invest": {"call": {"kind": "theCall", "situation": "A friend says Amazon hitting 1 million robots proves factory robot demand is booming.", "prompt": "How do you read that claim?", "options": ["It mixes service robots with factory arms", "It confirms factory installs doubled", "Warehouse and factory robots are one count"], "correctIndex": 0, "consequences": ["Amazon's fleet is warehouse service robots, a separate count from factory arms.", "The IFR factory count is a different number, 542,000 installed in 2024.", "The IFR counts industrial robots in factories; warehouse fleets sit apart."], "explanation": "Amazon's robots are service robots. The IFR's 542,000 industrial installs in 2024 measure factory arms, a different market."}, "proReasoning": "Investors keep robot types apart before drawing conclusions. A warehouse fleet says little about factory arm demand.", "commonMistake": "Adding warehouse and factory robots into one demand story.", "mentalModel": "Know which robots you are counting.", "sources": [{"url": "https://ifr.org/ifr-press-releases/news/global-robot-demand-in-factories-doubles-over-10-years", "label": "IFR, World Robotics 2025 press release"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You build software for warehouses that run hundreds of mobile robots. You need a first problem to solve.", "prompt": "Which need does the Amazon data point to?", "options": ["Designing new welding cells", "Keeping big fleets reliable and serviced", "Replacing robots with human pickers"], "correctIndex": 1, "consequences": ["Welding cells belong to factories, not warehouses.", "Amazon needs 30% more reliability and maintenance staff at its newest site.", "Amazon is adding robots, not removing them."], "explanation": "Amazon's newest site needs more reliability and maintenance staff. Fleet upkeep is a real cost that tools can cut."}, "proReasoning": "Founders look for the cost that grows with the robots. Upkeep grows with every machine added.", "commonMistake": "Building for the robot sale instead of the years of running it.", "mentalModel": "Sell to the fleet, not the robot."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether a warehouse robot is the same kind of machine as a car factory welding arm.", "prompt": "What's the best answer?", "options": ["Yes, every robot is an industrial robot", "No, warehouse robots are all cobots", "No, warehouse robots are service robots"], "correctIndex": 2, "consequences": ["Industrial robots are factory arms; warehouses run a different kind.", "Some roam among people, but the type comes from where they work.", "Service robots work beyond the factory line, like the ones moving Amazon parcels."], "explanation": "Where a robot works defines its type. Warehouse robots are service robots; factory arms are industrial."}, "proReasoning": "Name the type from where the robot works and who it works next to. That one rule sorts most machines.", "commonMistake": "Calling every robot an industrial robot.", "mentalModel": "Where it works sets its type."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5cc5cbd0b9f6$ml$]::text[]),
($ml$6b13792c-0cc1-5384-b2dc-30a56e260ea7$ml$::uuid, $ml$robotics$ml$, 1, 2, $ml${"id": "robotics-d1-c2", "title": "Where each robot type sells", "lessonTitle": "Three kinds of robots", "slot": 2, "type": "connect", "brief": {"headline": "In 2024, 54% of new industrial robots went to China. In 2025, da Vinci surgical robots were used in about 3.15 million procedures worldwide.", "kicker": "Connect two day 1 ideas: robot types and who buys them.", "fullText": "Day 1 gave you three types: industrial arms, service robots and cobots. It also showed who buys them.\n\nIndustrial robots go mostly to factories, and China installed 295,000 of the 542,000 placed in 2024. Service robots go elsewhere: Intuitive reports about 3.15 million da Vinci procedures in hospitals in 2025.\n\nThe type tells you the buyer. A factory and a hospital make very different customers.", "sources": [{"url": "https://ifr.org/ifr-press-releases/news/global-robot-demand-in-factories-doubles-over-10-years", "label": "IFR, World Robotics 2025 press release"}, {"url": "https://investor.intuitivesurgical.com/news-releases/news-release-details/intuitive-announces-preliminary-fourth-quarter-and-full-year-5", "label": "Intuitive, preliminary 2025 results"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["China installed more than half of new industrial robots in 2024.", "Surgical robots are counted as industrial robots.", "Cobots can often work without safety cages."], "fakeIndex": 1, "explanation": "Surgical robots work in hospitals, so they are service robots. Industrial robots are factory arms."}, "numbers": {"kind": "numberSense", "prompt": "China installed 295,000 of the 542,000 industrial robots placed in 2024. What share is that?", "min": 0, "max": 100, "value": 54, "unit": "%", "explanation": "295,000 of 542,000 is about 54%. China is the biggest buyer of factory arms by far."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview at a surgical robot maker, you're asked how it differs from FANUC.", "prompt": "Which answer lands best?", "options": ["Different type, different buyer", "Same type, just a smaller arm", "Both sell mainly to Chinese factories"], "correctIndex": 0, "consequences": ["Surgical robots are service robots sold to hospitals, not factories.", "Type comes from where a robot works, not its size.", "Hospitals buy surgical robots; factories buy industrial arms."], "explanation": "A surgical robot is a service robot with hospital buyers. An industrial arm sells to factories, mostly in China."}, "proReasoning": "Naming the type and its buyer shows you understand the business, not only the machine.", "commonMistake": "Comparing robots by size instead of by type and buyer.", "mentalModel": "Type first, then buyer."}, "invest": {"call": {"kind": "theCall", "situation": "Two robot makers pitch you: one sells factory arms, one sells hospital robots.", "prompt": "What should you check first for the factory arm maker?", "options": ["Whether hospitals will buy it", "How much it depends on Chinese demand", "How many surgeries its robots support each year"], "correctIndex": 1, "consequences": ["Factories, not hospitals, buy industrial arms.", "China took 54% of 2024 installs, so its demand moves factory arm sales.", "Surgeries matter for hospital robots, not factory arms."], "explanation": "More than half of factory arms went to China in 2024. Exposure to that one market shapes the risk."}, "proReasoning": "Investors map each type to its main buyers. For factory arms, that means China first.", "commonMistake": "Applying a hospital robot test to a factory arm maker.", "mentalModel": "Find the main buyer.", "sources": [{"url": "https://ifr.org/ifr-press-releases/news/global-robot-demand-in-factories-doubles-over-10-years", "label": "IFR, World Robotics 2025 press release"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could build for factories or for hospitals. You have money for one first market.", "prompt": "What should decide your first buyer?", "options": ["Whichever market sounds bigger", "Whatever investors mention most", "Which type your robot really is"], "correctIndex": 2, "consequences": ["Size alone hides very different buyers and needs.", "Investor talk does not change who buys your robot.", "The type sets the buyer, the sales cycle and the rules you face."], "explanation": "A robot built to weld is industrial and sells to factories. A robot built for surgery sells to hospitals."}, "proReasoning": "Founders let the product type pick the first buyer. Trying to sell one robot to every buyer stalls.", "commonMistake": "Choosing a market before knowing what type of robot you build.", "mentalModel": "Your type picks your buyer."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks most robots end up in hospitals because surgical robots get so much news.", "prompt": "What's a fair reply?", "options": ["Factory arms dominate, mostly in China", "Yes, hospitals buy most robots made today", "Robots go mainly to homes now"], "correctIndex": 0, "consequences": ["542,000 industrial robots were installed in 2024, 54% of them in China.", "Surgical robots are a smaller group, used in about 3.15 million procedures.", "Neither lesson figure points to homes."], "explanation": "News favors surgical robots, but factory arms are the bulk: 542,000 installed in 2024."}, "proReasoning": "One big number corrects a skewed picture. Factory installs dwarf the surgical robot count.", "commonMistake": "Judging where robots go by what makes the news.", "mentalModel": "Count before you guess."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6a8a7ab291ce$ml$]::text[]),
($ml$67ad56f6-3722-5eb5-b199-0be36af49d0a$ml$::uuid, $ml$robotics$ml$, 1, 3, $ml${"id": "robotics-d1-c3", "title": "Cage or no cage", "lessonTitle": "Three kinds of robots", "slot": 3, "type": "decide", "brief": {"headline": "You run a small parts shop. A cobot could work beside your two machinists without a safety cage, while a classic industrial arm would need gates and scanners.", "kicker": "Decide: which robot type fits a shop where people work close by?", "fullText": "Day 1 split robots by where they work and who they work next to. Classic industrial robots run behind guards. Cobots are built to work right next to people, often with no cage at all.\n\nYour shop is small, and your machinists load parts by hand all day. Floor space is tight, and you cannot fence off a corner.\n\nThe question is which type of robot fits the way your shop works.", "sources": [{"url": "https://ifr.org/news/how-robots-work-alongside-humans/", "label": "IFR, how robots work alongside humans"}, {"url": "https://ifr.org/ifr-press-releases/news/global-robot-demand-in-factories-doubles-over-10-years", "label": "IFR, World Robotics 2025 press release"}]}, "evidence": {"kind": "faceOff", "prompt": "Which robot fits a tight shop where people stand close by?", "left": {"name": "Classic industrial arm", "note": "Needs gates, scanners or mats around it"}, "right": {"name": "Cobot", "note": "Built to work beside people, often uncaged"}, "correctIndex": 1, "explanation": "Cobots are designed to share space with people. A classic arm needs guarding that a tight shop cannot fit."}, "numbers": {"kind": "numberSense", "prompt": "The world ran about 4.66 million industrial robots in 2024. How many million is that?", "min": 0, "max": 8, "value": 4.7, "unit": "M", "explanation": "About 4.66 million, up 9% on the year. Most still run behind guards in factories."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a technician candidate. The shop owner asks what you'd check before running the cobot.", "prompt": "Which answer helps most?", "options": ["How heavy the base is", "How it limits contact with people", "How fast it can possibly move"], "correctIndex": 1, "consequences": ["Base weight says little about working beside machinists.", "A cobot earns its place by working safely beside people.", "Top speed matters less than safe contact near people."], "explanation": "A cobot shares space with people, so how it limits contact comes first."}, "proReasoning": "Good technicians start from who stands near the robot. That shapes every setting after.", "commonMistake": "Tuning for speed before checking how the robot treats people nearby.", "mentalModel": "People nearby set the rules."}, "invest": {"call": {"kind": "theCall", "situation": "A cobot maker pitches its arm for small shops like yours.", "prompt": "What makes its product worth paying for?", "options": ["It is bigger and heavier than a classic arm", "It only works inside a cage", "It can work near people without a cage"], "correctIndex": 2, "consequences": ["Cobots are usually not bigger; size is not the selling point.", "Working uncaged near people is the whole idea.", "Skipping the cage saves space and setup, which is the value."], "explanation": "Cobots are built to work beside people, often without cages. That design is what buyers pay for."}, "proReasoning": "Investors look for the feature a buyer cannot get elsewhere. For cobots, it is safe work near people.", "commonMistake": "Valuing a cobot on size or speed alone.", "mentalModel": "Pay for the missing cage.", "sources": [{"url": "https://ifr.org/news/how-robots-work-alongside-humans/", "label": "IFR, how robots work alongside humans"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You're designing a robot for small shops with no room for fences.", "prompt": "Which type should you build?", "options": ["A cobot built to work beside people", "A classic arm sold with a cage", "A large welding arm"], "correctIndex": 0, "consequences": ["Small shops can use it without walling off space.", "The cage eats the floor space your buyers do not have.", "Welding arms run behind guards in large plants."], "explanation": "Your buyer works close to the machine. A cobot fits that; a caged arm does not."}, "proReasoning": "Founders design for the buyer's floor, not the robot's specs. Space and people decide the type.", "commonMistake": "Building a fast caged arm for shops with no room for a cage.", "mentalModel": "Fit the floor you sell into."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why some robots sit behind fences while others work right next to people.", "prompt": "What's the best answer?", "options": ["Fences are only for show", "Cobots are built to work beside people", "Fenced robots are simply older models"], "correctIndex": 1, "consequences": ["Guards keep people away from classic arms.", "Cobots are designed to share space with people safely.", "Age is not the reason; the design and job are."], "explanation": "Classic industrial arms are kept apart from people. Cobots are designed to work beside them."}, "proReasoning": "Explain a robot by who it works next to. That is what separates a cobot from a classic arm.", "commonMistake": "Thinking the fence is optional for every robot.", "mentalModel": "Design decides the fence."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e5bab751f293$ml$]::text[]),
($ml$317d86bb-ae6b-5b55-9052-a46eb0791899$ml$::uuid, $ml$robotics$ml$, 2, 1, $ml${"id": "robotics-d2-c1", "title": "Intuitive's third quarter of 2026", "lessonTitle": "How robot companies make money", "slot": 1, "type": "apply", "brief": {"headline": "In the third quarter of 2026, Intuitive earned $3.05 billion. Instruments and accessories brought in $1.80 billion, systems $769 million and services $482 million.", "kicker": "Apply the razor and blades: where does Intuitive make its money now?", "fullText": "Intuitive makes the da Vinci surgical robot. In the quarter to September 30, 2026, worldwide da Vinci procedures grew about 14%, and revenue rose 22% to $3.05 billion.\n\nThe company placed 546 new systems, taking its installed base to 12,094. Each installed robot keeps using instruments with every procedure, and needs service.\n\nInstruments and services together made about $2.28 billion, roughly three quarters of the total. The robots themselves brought in $769 million.", "sources": [{"url": "https://www.biospace.com/press-releases/intuitive-announces-third-quarter-2026-earnings", "label": "Intuitive via BioSpace, third quarter 2026 earnings, Oct 2026"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each Intuitive revenue line recurring, or a one-off sale?", "buckets": ["Recurring", "One-off sale"], "items": [{"text": "Instruments used in each surgery", "bucket": 0}, {"text": "Accessories bought for procedures", "bucket": 0}, {"text": "Service contracts on installed robots", "bucket": 0}, {"text": "A new da Vinci 5 system", "bucket": 1}, {"text": "One of 546 systems placed", "bucket": 1}], "explanation": "Instruments and services come back with every procedure and every installed robot. A system sale happens once."}, "numbers": {"kind": "numberSense", "prompt": "Instruments and services made about $2.28 billion of $3.05 billion. What share is that?", "min": 0, "max": 100, "value": 75, "unit": "%", "explanation": "About 75%, the same share as in 2025. Most of the money comes after the robot is sold."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a sales role at Intuitive. You're asked what drives revenue.", "prompt": "Which answer shows you understand the model?", "options": ["Procedures on installed robots", "New robot sales each quarter", "One-time service fees"], "correctIndex": 0, "consequences": ["Instruments and services, tied to procedures, made about 75% of revenue.", "Systems brought in $769 million, about a quarter.", "Service is recurring, not one-time."], "explanation": "Each procedure uses instruments and every robot needs service. That recurring stream is about 75% of revenue."}, "proReasoning": "Strong candidates explain what makes the money recur. At Intuitive, it's procedures on 12,094 installed robots.", "commonMistake": "Assuming a robot company earns mostly from selling robots.", "mentalModel": "Count the procedures."}, "invest": {"call": {"kind": "theCall", "situation": "Procedures grew about 14% and revenue 22%. You want one number to track each quarter.", "prompt": "Which number best predicts future revenue?", "options": ["Share price movement", "Procedure growth on the installed base", "New systems placed in the latest quarter"], "correctIndex": 1, "consequences": ["Share price reflects expectations, not the business itself.", "Procedures drive instruments and services, about 75% of revenue.", "New systems matter but bring a quarter of revenue."], "explanation": "Instruments and services follow procedures. Procedure growth is the engine of the recurring revenue."}, "proReasoning": "Investors track the driver of recurring revenue. Here that is procedures, not unit sales.", "commonMistake": "Judging a recurring business by its one-off sales.", "mentalModel": "Follow the recurring driver."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a robot for clinics. You want Intuitive's kind of model.", "prompt": "What should you design for from day one?", "options": ["The lowest possible robot price", "A robot that never needs service", "A consumable used in every procedure"], "correctIndex": 2, "consequences": ["A cheap robot alone gives one sale and no follow-on.", "Service is part of the recurring stream, not a flaw.", "A part used each time turns every procedure into revenue."], "explanation": "At Intuitive, the robot is the razor and instruments are the blades. Design the blade early."}, "proReasoning": "Founders who want recurring revenue design the consumable with the robot. Retrofitting it later is hard.", "commonMistake": "Pricing the robot to win the deal and planning nothing after.", "mentalModel": "Design the second sale."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks Intuitive must make most of its money selling surgical robots.", "prompt": "What's a fair reply?", "options": ["Most comes from instruments and service", "Yes, almost all is robot sales", "Most comes from training surgeons"], "correctIndex": 0, "consequences": ["Instruments and services made about 75% of third-quarter revenue.", "Systems brought in $769 million of $3.05 billion.", "The release splits revenue into instruments, systems and services."], "explanation": "The robot is about a quarter of the money. What each surgery uses brings in the rest."}, "proReasoning": "One split corrects a common belief: the robot is the smaller part of the business.", "commonMistake": "Assuming the machine is the main product.", "mentalModel": "The money follows each surgery."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2275eb43e16f$ml$]::text[]),
($ml$64745381-7fd3-556a-88c4-ee40e3760fea$ml$::uuid, $ml$robotics$ml$, 2, 2, $ml${"id": "robotics-d2-c2", "title": "Recurring revenue in China", "lessonTitle": "How robot companies make money", "slot": 2, "type": "connect", "brief": {"headline": "Chinese makers now supply 57% of China's industrial robot market. Intuitive earns about 75% of its revenue after the robot is sold.", "kicker": "Connect day 2 and day 1: the money after the sale, and who buys.", "fullText": "Day 1 showed that factory arms go mostly to China, where 295,000 were installed in 2024 and local makers hold 57% of the market. Day 2 showed that a robot maker can earn most of its money after the sale.\n\nPut them together and a pattern appears. An arm sold once to a price-focused factory buyer earns once. A robot that needs parts and service for each use keeps earning, even when rivals undercut the robot price.\n\nIntuitive's recurring share, about 75% in 2025, came from instruments and services.", "sources": [{"url": "https://ifr.org/ifr-press-releases/news/global-robot-demand-in-factories-doubles-over-10-years", "label": "IFR, World Robotics 2025 press release"}, {"url": "https://www.nasdaq.com/press-release/intuitive-announces-fourth-quarter-earnings-2026-01-22", "label": "Intuitive, Q4 2025 earnings"}]}, "evidence": {"kind": "faceOff", "prompt": "Which business is better protected when cheaper rivals arrive?", "left": {"name": "Sells arms once, no follow-on", "note": "Each sale earns once"}, "right": {"name": "Sells robots plus parts and service", "note": "Earns with every use"}, "correctIndex": 1, "explanation": "Recurring revenue keeps coming from installed robots, even if a rival cuts the price of new ones."}, "numbers": {"kind": "numberSense", "prompt": "Chinese makers' share of China's industrial robot market rose from about 28% to what percent?", "min": 0, "max": 100, "value": 57, "unit": "%", "explanation": "About 57%. Foreign arm makers face rising local competition in their biggest market."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A European arm maker asks how it should respond to cheaper Chinese rivals.", "prompt": "Which idea shows you connected the lessons?", "options": ["Leave China entirely tomorrow", "Grow service and parts on installed arms", "Cut the arm price below every rival"], "correctIndex": 1, "consequences": ["China installs over half of all arms; leaving gives up the market.", "Recurring revenue holds up when new robot prices fall.", "A price war with local makers erodes margins."], "explanation": "Local makers hold 57% of China. Earning on the installed base protects a maker that cannot win on price."}, "proReasoning": "Candidates who connect market shifts to business models stand out. Recurring revenue is a defense.", "commonMistake": "Answering a price threat with price alone.", "mentalModel": "Defend with recurring revenue."}, "invest": {"call": {"kind": "theCall", "situation": "You compare a pure arm seller with a company earning 75% after the sale.", "prompt": "Which risk weighs more on the pure arm seller?", "options": ["Surgeons switching hospitals", "Too much service revenue", "Price cuts by local Chinese makers"], "correctIndex": 2, "consequences": ["Surgeons matter for surgical robots, not factory arms.", "Service revenue steadies a business; it is not the risk.", "Chinese makers grew to 57% of their home market."], "explanation": "An arm seller earns once per sale, so cheaper local rivals hit it directly."}, "proReasoning": "Investors ask how a company earns when competition arrives. One-off sellers feel it first.", "commonMistake": "Treating all robot makers as equally exposed.", "mentalModel": "One-off sales feel price wars first.", "sources": [{"url": "https://ifr.org/ifr-press-releases/news/global-robot-demand-in-factories-doubles-over-10-years", "label": "IFR, World Robotics 2025 press release"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells robot arms to Chinese factories. Local rivals are cheaper.", "prompt": "What protects your revenue best?", "options": ["Software and service each robot keeps using", "A one-time discount on every arm you sell", "A bigger logo on the robot"], "correctIndex": 0, "consequences": ["Recurring revenue grows with each installed robot.", "Discounts shrink margins and rivals can match them.", "Branding does not change how you earn."], "explanation": "Day 2 showed most money can come after the sale. Build that stream before the price war arrives."}, "proReasoning": "Founders facing cheaper rivals compete on what follows the sale. That is harder to copy than a price.", "commonMistake": "Fighting local makers on price alone.", "mentalModel": "Earn after the sale."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders how Western robot makers can survive if Chinese arms are cheaper.", "prompt": "What's a good answer?", "options": ["Only by cutting their prices further each year", "Earning on parts and service after a sale", "They cannot survive at all"], "correctIndex": 1, "consequences": ["A price race alone erodes every maker.", "Recurring revenue keeps flowing from robots already installed.", "Some makers earn most of their money after the sale."], "explanation": "Robot makers can earn on what each robot keeps using. Intuitive made about 75% that way in 2025."}, "proReasoning": "Connect two ideas to answer a hard question: competition on price, and money after the sale.", "commonMistake": "Thinking the robot price is the only lever.", "mentalModel": "The installed base pays."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ef80dd410aaf$ml$]::text[]),
($ml$7453678f-f7bc-5864-885f-2afba1584f9a$ml$::uuid, $ml$robotics$ml$, 2, 3, $ml${"id": "robotics-d2-c3", "title": "Price the robot or the procedure", "lessonTitle": "How robot companies make money", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup with a hospital robot. One plan sells it at a high price; the other sells it cheaper and charges for parts used in every procedure.", "kicker": "Decide: where should your money come from?", "fullText": "Day 2 showed how Intuitive earns. Instruments and accessories brought in $6.02 billion in 2025, services $1.57 billion, and robot systems $2.47 billion.\n\nThat made instruments and services about 75% of revenue. They grow with every procedure on every installed robot.\n\nYour hospital buyers have tight capital budgets. You must pick a pricing plan before your first sale.", "sources": [{"url": "https://www.nasdaq.com/press-release/intuitive-announces-fourth-quarter-earnings-2026-01-22", "label": "Intuitive, Q4 2025 earnings"}, {"url": "https://investor.intuitivesurgical.com/news-releases/news-release-details/intuitive-announces-preliminary-fourth-quarter-and-full-year-5", "label": "Intuitive, preliminary 2025 results"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the money flow of a razor and blades robot in order.", "steps": ["A hospital buys or installs the robot", "Surgeons perform procedures on it", "Each procedure uses instruments", "The hospital reorders instruments and service", "Recurring revenue grows with procedures"], "explanation": "The robot opens the door. Procedures and the parts they use bring the repeat money."}, "numbers": {"kind": "numberSense", "prompt": "Intuitive placed 1,721 da Vinci systems in 2025. How many thousand is that?", "min": 0, "max": 5, "value": 1.7, "unit": "K", "explanation": "About 1,700 systems. Each one adds to the base that drives recurring revenue for years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As a product manager, you must explain the pricing plan to your sales team.", "prompt": "Which message sets them up well?", "options": ["Maximize the price you get for every robot", "Ignore usage after the sale", "Win placements; procedures pay over time"], "correctIndex": 2, "consequences": ["A high price can slow placements and the stream behind them.", "Usage is where most of the money comes from.", "Each placed robot feeds instrument and service revenue for years."], "explanation": "At Intuitive, most revenue follows the sale. Placements matter because procedures follow them."}, "proReasoning": "Good product managers explain how today’s deal becomes tomorrow’s revenue. Placements feed procedures.", "commonMistake": "Rewarding sales only for the robot price.", "mentalModel": "Placements feed procedures."}, "invest": {"call": {"kind": "theCall", "situation": "Two startups pitch you hospital robots: one on a high upfront price, one on per-procedure parts.", "prompt": "Which model looks steadier, all else equal?", "options": ["Per-procedure parts revenue", "High upfront robot price", "Free robots with no parts"], "correctIndex": 0, "consequences": ["Revenue tied to each use grows with the installed base.", "Upfront sales swing with hospital budgets.", "With no follow-on revenue, a free robot earns nothing."], "explanation": "Revenue that grows with each use is steadier than one-off sales. At Intuitive it was about 75%."}, "proReasoning": "Investors prefer revenue that repeats. Usage-based revenue compounds with every installed robot.", "commonMistake": "Rewarding the biggest upfront sale.", "mentalModel": "Steady beats lumpy.", "sources": [{"url": "https://www.nasdaq.com/press-release/intuitive-announces-fourth-quarter-earnings-2026-01-22", "label": "Intuitive, Q4 2025 earnings"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Hospitals tell you their capital budgets are tight this year.", "prompt": "Which plan fits your buyers?", "options": ["No parts revenue at all", "A lower robot price, paid back through parts", "The highest robot price the market will bear"], "correctIndex": 1, "consequences": ["You would give up the larger, recurring stream.", "A lower upfront cost eases the budget and starts the parts stream.", "A high price fights the tight budget head on."], "explanation": "Tight capital budgets favor a lower upfront price. Parts used in each procedure then build the revenue."}, "proReasoning": "Founders match pricing to the buyer’s budget. A lower entry price can open more doors.", "commonMistake": "Pricing the robot as if it were the whole business.", "mentalModel": "Lower the door, earn inside."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company would ever sell a robot for less than it could charge.", "prompt": "What's the best answer?", "options": ["Robots are always sold at a loss", "Prices never matter to hospitals", "Each robot keeps earning through parts"], "correctIndex": 2, "consequences": ["The robot still brought in $2.47 billion in 2025.", "Hospital budgets shape every purchase.", "Instruments and services made about 75% of Intuitive’s revenue."], "explanation": "A robot that is used every day keeps buying parts. That stream can outweigh the robot price."}, "proReasoning": "Explain a pricing choice with the money that follows it. The razor and blades idea makes it simple.", "commonMistake": "Thinking the sticker price is the whole deal.", "mentalModel": "The blades pay for the razor."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a83d2b4fa694$ml$]::text[]),
($ml$fef19f6a-d0f7-5bb1-ab8d-0caea49cbfb3$ml$::uuid, $ml$robotics$ml$, 3, 1, $ml${"id": "robotics-d3-c1", "title": "China sells more robots than it buys", "lessonTitle": "Who holds the power in robotics", "slot": 1, "type": "apply", "brief": {"headline": "In 2025, China's industrial robot exports rose 48.7% and passed its imports for the first time. Chinese suppliers already held 57% of their home market.", "kicker": "Apply power in robotics: who gains when a country makes its own robots?", "fullText": "China's customs data show industrial robot exports up 48.7% in 2025, making China a net exporter of these machines for the first time.\n\nAt home, Chinese suppliers hold 57% of the market. They still hold only a small share of the mid to high end six-axis segment, about 200,000 units a year.\n\nSome makers are moving abroad. Estun won approval for a Hong Kong listing, and STEP sells more than 1,200 robots a year overseas.", "sources": [{"url": "https://en.jiemian.com/article/14086758.html", "label": "Jiemian, China becomes a net exporter of industrial robots"}, {"url": "https://ifr.org/ifr-press-releases/news/global-robot-demand-in-factories-doubles-over-10-years", "label": "IFR, World Robotics 2025 press release"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did China become in 2025 for industrial robots?", "options": ["A closed market", "A net importer", "A net exporter"], "correctIndex": 2, "explanation": "Exports passed imports for the first time. China now sells more industrial robots abroad than it buys."}, "numbers": {"kind": "numberSense", "prompt": "By how many percent did China's industrial robot exports rise in 2025?", "min": 0, "max": 80, "value": 48.7, "unit": "%", "explanation": "Up 48.7%. Chinese makers are no longer only serving their home market."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a Japanese robot maker. They ask where competition is heading.", "prompt": "Which answer shows you track the market?", "options": ["Competition is fading worldwide", "Chinese makers are now exporting at scale", "China still imports most of its robots"], "correctIndex": 1, "consequences": ["New exporters mean more competition, not less.", "Exports rose 48.7% and passed imports in 2025.", "China became a net exporter in 2025."], "explanation": "Chinese suppliers hold 57% at home and now export more than they import. Foreign makers face them abroad too."}, "proReasoning": "Candidates who cite a recent data point show they follow the field, not just its history.", "commonMistake": "Describing China only as a buyer of foreign robots.", "mentalModel": "China now sells abroad."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a foreign arm maker with big China sales.", "prompt": "Which signal matters most?", "options": ["China buying more imported robots each year", "High-end arms becoming irrelevant", "Local makers now compete at home and abroad"], "correctIndex": 2, "consequences": ["The trend runs the other way: exports passed imports.", "Chinese brands still hold little of the high-end six-axis segment.", "57% local share at home plus 48.7% export growth."], "explanation": "Local makers took over the home market and are pushing exports. Pressure spreads beyond China."}, "proReasoning": "Investors watch where a rival can win next. Chinese makers are moving from home share to exports.", "commonMistake": "Assuming China will keep buying foreign robots.", "mentalModel": "Watch the new exporters."}, "build_startup": {"call": {"kind": "theCall", "situation": "You make robot components and want a durable spot in the supply chain.", "prompt": "Where is room still open, by this data?", "options": ["High-end six-axis arms", "Basic arms for Chinese buyers", "Imports into China"], "correctIndex": 0, "consequences": ["Chinese brands hold only a small share of that segment.", "Local makers already hold 57% of the home market.", "Exports now exceed imports, so imports are shrinking in relative terms."], "explanation": "Chinese makers lead at home but trail in high-end six-axis arms. That gap is where others still compete."}, "proReasoning": "Founders look for the segment the strongest rivals have not taken yet.", "commonMistake": "Competing where the local makers are strongest.", "mentalModel": "Find the gap they have not filled."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks China mostly buys robots from Japan and Germany.", "prompt": "What's a fair update?", "options": ["China stopped using robots", "China now exports more than it imports", "Yes, nearly all come from abroad"], "correctIndex": 1, "consequences": ["China installs more industrial robots than anyone.", "Exports rose 48.7% and passed imports in 2025.", "Chinese suppliers already hold 57% of their home market."], "explanation": "China makes most of its own robots now, and sells more abroad than it buys."}, "proReasoning": "Update an old picture with one recent number. The 2025 export data does that.", "commonMistake": "Holding on to an outdated view of who builds robots.", "mentalModel": "The builder became a seller."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:dc86ceb69af1$ml$]::text[]),
($ml$02942a51-908f-5092-b568-d2f2ce847d4c$ml$::uuid, $ml$robotics$ml$, 3, 2, $ml${"id": "robotics-d3-c2", "title": "Cheap arms, scarce gears", "lessonTitle": "Who holds the power in robotics", "slot": 2, "type": "connect", "brief": {"headline": "Chinese makers hold 57% of their home robot market. Yet every arm, cheap or not, needs precision reducers from a few specialists.", "kicker": "Connect day 3 and day 2: where the money is, and who holds the parts.", "fullText": "Day 2 showed that robot makers earn much of their money after the sale. Day 3 adds a second question: who controls the parts every robot needs.\n\nRobot joints need precision gears called reducers, made by a few specialists. When robot demand surges, those parts run short and robot makers wait.\n\nA maker can win share with cheaper arms and still depend on a reducer supplier it cannot replace quickly.", "sources": [{"url": "https://www.therobotreport.com/global-robot-growth-causing-shortages-critical-components/", "label": "The Robot Report, component shortages"}, {"url": "https://ifr.org/ifr-press-releases/news/global-robot-demand-in-factories-doubles-over-10-years", "label": "IFR, World Robotics 2025 press release"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each part give its maker strong bargaining power?", "buckets": ["Strong power", "Weak power"], "items": [{"text": "Precision reducers from a few specialists", "bucket": 0}, {"text": "Parts every robot joint needs", "bucket": 0}, {"text": "Paint sold by many suppliers", "bucket": 1}, {"text": "Standard bolts", "bucket": 1}, {"text": "Generic cables", "bucket": 1}], "explanation": "Power sits with parts nobody can skip and few can make. Common parts have many sellers."}, "numbers": {"kind": "numberSense", "prompt": "China installed how many thousand industrial robots in 2024?", "min": 0, "max": 500, "value": 295, "unit": "K", "explanation": "About 295,000, a record. Every one needed reducers in its joints."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A robot maker asks you, as a supply chain hire, what to watch.", "prompt": "Which answer helps most?", "options": ["Prices of paint, bolts and cables", "The color of the robot", "Reducer supply from a few specialists"], "correctIndex": 2, "consequences": ["Common parts have many suppliers.", "Looks do not decide whether robots ship.", "Reducers are the parts that stall production when short."], "explanation": "A few specialists make reducers, so shortages there stop production."}, "proReasoning": "Supply chain candidates show value by naming the bottleneck. In robots, it is precision reducers.", "commonMistake": "Treating every part as equally important.", "mentalModel": "Watch the scarce part."}, "invest": {"call": {"kind": "theCall", "situation": "A robot maker's arms sell well, but it buys all its reducers from one supplier.", "prompt": "What risk do you flag?", "options": ["A reducer shortage can halt its output", "It has too many reducer suppliers to manage", "Paint costs rising"], "correctIndex": 0, "consequences": ["Robot makers wait when reducers run short.", "One supplier is the opposite of too many.", "Common inputs are easy to replace."], "explanation": "Strong sales do not help if the joints cannot be built. One supplier is a single point of failure."}, "proReasoning": "Investors look past demand to the parts that cap supply.", "commonMistake": "Assuming strong demand means strong output.", "mentalModel": "Demand needs parts.", "sources": [{"url": "https://www.therobotreport.com/global-robot-growth-causing-shortages-critical-components/", "label": "The Robot Report, component shortages"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds cheaper robot arms for Chinese factories.", "prompt": "What should you secure before scaling?", "options": ["More paint colors", "A second reducer supplier", "A bigger marketing budget"], "correctIndex": 1, "consequences": ["Colors do not decide if arms ship.", "A second source protects output when demand surges.", "Marketing does not fix a parts shortage."], "explanation": "Cheaper arms win orders, but reducers decide whether you can deliver them."}, "proReasoning": "Founders secure the parts nobody can skip before chasing volume.", "commonMistake": "Scaling sales before securing scarce parts.", "mentalModel": "Secure the joints first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a cheap robot maker could still get stuck waiting.", "prompt": "What's the best answer?", "options": ["Cheap robots never win any big orders", "Factories stopped buying robots", "Its joints need scarce precision gears"], "correctIndex": 2, "consequences": ["Cheaper makers hold 57% of the Chinese market.", "China installed a record 295,000 robots in 2024.", "A few specialists make reducers, which run short in booms."], "explanation": "Every robot joint needs reducers from a few specialists. When demand surges, everyone waits for them."}, "proReasoning": "A small part can hold up a whole industry. That is the power in a bottleneck.", "commonMistake": "Thinking a low price solves every problem.", "mentalModel": "Small parts, big power."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5f5fb9f8a4f4$ml$]::text[]),
($ml$45fe35ac-380f-5691-bcf1-44c34c3077a3$ml$::uuid, $ml$robotics$ml$, 3, 3, $ml${"id": "robotics-d3-c3", "title": "One reducer supplier, one big order", "lessonTitle": "Who holds the power in robotics", "slot": 3, "type": "decide", "brief": {"headline": "You run a robot maker that just won a large order. All your reducers come from one specialist, and robot demand is surging.", "kicker": "Decide: what protects your production?", "fullText": "Day 3 showed that power in robotics sits with whoever makes the parts nobody can skip. Robot joints need precision reducers from a few specialists, and robot growth has caused shortages.\n\nYour new order doubles your output plan. Your sole reducer supplier is also selling to every other robot maker in the boom.\n\nYou can push for faster delivery, take the risk, or line up another source.", "sources": [{"url": "https://www.therobotreport.com/global-robot-growth-causing-shortages-critical-components/", "label": "The Robot Report, component shortages"}]}, "evidence": {"kind": "faceOff", "prompt": "Who has more bargaining power when robot demand surges?", "left": {"name": "A precision reducer maker", "note": "Few can make it; every joint needs it"}, "right": {"name": "A robot arm assembler", "note": "Many rivals, waiting on parts"}, "correctIndex": 0, "explanation": "The reducer maker supplies a part nobody can skip. In a boom, buyers wait in line."}, "numbers": {"kind": "numberSense", "prompt": "US industrial robot installations fell 9% in 2024 to how many thousand?", "min": 0, "max": 100, "value": 34.2, "unit": "K", "explanation": "About 34,200. While the US slipped, demand elsewhere kept reducers tight."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As the maker's operations lead, you brief the CEO on the order.", "prompt": "What do you recommend first?", "options": ["Qualify a second reducer supplier", "Promise the customer early delivery", "Cut the order in half"], "correctIndex": 0, "consequences": ["A second source protects delivery if the first runs short.", "Early promises fail if reducers do not arrive.", "Halving the order gives up revenue you could protect."], "explanation": "One supplier in a boom is a single point of failure. A second source keeps the order on track."}, "proReasoning": "Operations leads protect the bottleneck before committing dates. Customers remember missed deliveries.", "commonMistake": "Committing dates that depend on one stretched supplier.", "mentalModel": "Protect the bottleneck first."}, "invest": {"call": {"kind": "theCall", "situation": "The maker asks you for funding to fill the big order.", "prompt": "What would you want to see first?", "options": ["A new logo", "A plan for a second reducer source", "A bigger sales team to win more orders"], "correctIndex": 1, "consequences": ["Branding does not fix a parts constraint.", "It shows the company can actually build what it sold.", "More sales do not help if output is capped."], "explanation": "A big order is only revenue if the robots get built. Reducer supply decides that."}, "proReasoning": "Investors fund execution, not just orders. Parts supply is where execution breaks.", "commonMistake": "Funding growth without checking the bottleneck.", "mentalModel": "Orders need parts.", "sources": [{"url": "https://www.therobotreport.com/global-robot-growth-causing-shortages-critical-components/", "label": "The Robot Report, component shortages"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your supplier offers priority delivery if you sign a long exclusive deal.", "prompt": "What's the sensible move?", "options": ["Sign exclusive and drop all others", "Ignore the offer and wait", "Keep a second source alongside it"], "correctIndex": 2, "consequences": ["Exclusivity deepens dependence on one supplier.", "Waiting in a boom risks the order.", "Priority helps, but a backup still protects you."], "explanation": "Priority today does not remove the risk of relying on one supplier tomorrow."}, "proReasoning": "Founders take help from a key supplier without giving up their backup.", "commonMistake": "Trading flexibility for a short-term priority slot.", "mentalModel": "Keep a backup."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company with a huge order could still be in trouble.", "prompt": "What's the best answer?", "options": ["It relies on one supplier for scarce parts", "Big orders always lose money for robot makers", "Factories never pay"], "correctIndex": 0, "consequences": ["If that supplier falls short, robots cannot be built.", "Orders become revenue once delivered.", "Payment is not the issue in this case."], "explanation": "An order is only as safe as the parts behind it. One reducer supplier is a weak link."}, "proReasoning": "Spot the weak link in a success story. Here it is the scarce part.", "commonMistake": "Equating a big order with guaranteed success.", "mentalModel": "Success needs supply."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2793568e3243$ml$]::text[]),
($ml$2ae5892c-35ab-5e88-8cae-4b698d1970a6$ml$::uuid, $ml$robotics$ml$, 4, 1, $ml${"id": "robotics-d4-c1", "title": "Korea passes 1,200", "lessonTitle": "The numbers that measure automation", "slot": 1, "type": "apply", "brief": {"headline": "The IFR reported 1,220 industrial robots per 10,000 factory employees in South Korea, the highest anywhere. The global average was 132.", "kicker": "Apply robot density: what does 1,220 tell you that a raw count does not?", "fullText": "In April 2026, the International Federation of Robotics published its latest density figures. South Korea led with 1,220 robots per 10,000 employees, then Singapore at 818, Germany at 449 and Japan at 446.\n\nThe United States ranked eighth at 307. The global average was 132, and the European Union averaged 231.\n\nDensity divides robots by factory workers, so small and large countries can be compared fairly. It shows how far automation has gone, not how many robots a country buys.", "sources": [{"url": "https://www.businesswire.com/news/home/20260408531951/en/", "label": "IFR via Business Wire, robot density surges in Europe, Asia and Americas, Apr 2026"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["South Korea had the highest robot density.", "The US had a higher density than Germany.", "Density counts robots per 10,000 employees."], "fakeIndex": 1, "explanation": "The US had 307 against Germany’s 449. Germany ranks above it."}, "numbers": {"kind": "numberSense", "prompt": "South Korea had 1,220 robots per 10,000 employees. About how many robots per 100 workers is that?", "min": 0, "max": 30, "value": 12.2, "unit": "robots", "explanation": "About 12 robots for every 100 factory workers, more than one for every ten."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview at a robot maker, you’re asked which country is most automated.", "prompt": "Which answer lands best?", "options": ["China, because it buys the most", "The US, because it is largest", "South Korea, at 1,220 per 10,000"], "correctIndex": 2, "consequences": ["Buying the most is a count, not density.", "The US ranked eighth at 307.", "Density measures how far automation has gone, and Korea leads."], "explanation": "Most automated means highest density. Korea runs 1,220 robots per 10,000 employees."}, "proReasoning": "Precise metrics beat vague claims. Naming density and the number shows you know the field.", "commonMistake": "Confusing the biggest buyer with the most automated country.", "mentalModel": "Density, not volume."}, "invest": {"call": {"kind": "theCall", "situation": "A fund says US automation is nearly maxed out.", "prompt": "What does the density data suggest?", "options": ["US density trails leaders by far", "The US leads the world", "Density cannot be compared"], "correctIndex": 0, "consequences": ["307 against Korea’s 1,220 and Germany’s 449.", "The US ranked eighth, not first.", "Density exists precisely to compare countries."], "explanation": "At 307, the US sits well below Korea, Singapore, Germany and Japan. That gap can mean room to grow."}, "proReasoning": "Investors use density to spot where automation can still spread.", "commonMistake": "Calling a market saturated without checking density.", "mentalModel": "Gaps can be demand."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell automation services and must pick a first country to target.", "prompt": "What does density help you judge?", "options": ["Which flag is most popular", "How much automation is left to do", "How many robots it bought last year"], "correctIndex": 1, "consequences": ["Not a business measure.", "Low density relative to peers hints at room to grow.", "Yearly purchases are a count, not saturation."], "explanation": "Density shows how automated factories already are. Lower density can mean more work left to win."}, "proReasoning": "Founders use density to size how much automation a market still needs.", "commonMistake": "Picking a market by buying volume alone.", "mentalModel": "Measure what is left."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is surprised a small country like Singapore ranks second for factory robots.", "prompt": "What's the best answer?", "options": ["Singapore buys the most robots of any country", "The ranking is by land area", "Density compares per worker, not totals"], "correctIndex": 2, "consequences": ["Density is not a total count.", "Area has nothing to do with it.", "818 per 10,000 employees puts it second."], "explanation": "Density divides robots by factory workers, so small countries can rank high."}, "proReasoning": "Explain a surprising rank with how it is measured. Per-worker metrics level the field.", "commonMistake": "Expecting the biggest countries to lead every ranking.", "mentalModel": "Per worker levels the field."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f40caf89acf3$ml$]::text[]),
($ml$99a04ad8-f766-5d97-8037-016c23b63eba$ml$::uuid, $ml$robotics$ml$, 4, 2, $ml${"id": "robotics-d4-c2", "title": "Density versus volume", "lessonTitle": "The numbers that measure automation", "slot": 2, "type": "connect", "brief": {"headline": "China installed 295,000 industrial robots in 2024, more than half the world total. Yet in 2023, South Korea ran 1,012 robots per 10,000 workers to China’s 470.", "kicker": "Connect day 4 and day 3: who buys the most, and who is most automated.", "fullText": "Day 3 showed China as the biggest buyer and builder of industrial robots, with a record 295,000 installed in 2024.\n\nDay 4 measured something else. In 2023, South Korea ran 1,012 robots per 10,000 manufacturing employees, Singapore 770, and China 470, which had just passed Germany's 429 and Japan's 419.\n\nChina buys the most because it has so many factory workers. Korea is the most automated because it runs the most robots per worker.", "sources": [{"url": "https://businesswire.com/news/home/20241120789594/en/China-Overtakes-Germany-and-Japan-in-Robot-Density-%e2%80%93-IFR-reports", "label": "IFR, robot density (World Robotics 2024)"}, {"url": "https://ifr.org/ifr-press-releases/news/global-robot-demand-in-factories-doubles-over-10-years", "label": "IFR, World Robotics 2025 press release"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which measure shows how far automation has gone in a country?", "options": ["Robot makers headquartered there", "Robots installed per year", "Robots per 10,000 employees"], "correctIndex": 2, "explanation": "Density divides robots by factory workers. Yearly installs show demand, not saturation."}, "numbers": {"kind": "numberSense", "prompt": "China's robot density jumped from 402 to what in one year?", "min": 0, "max": 800, "value": 470, "unit": "robots", "explanation": "From 402 to 470, passing Germany and Japan. Volume and density both rose fast."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks whether China is the most automated country.", "prompt": "Which answer is most precise?", "options": ["Biggest buyer, but Korea is denser", "Yes, it buys the most robots", "No, China barely uses robots"], "correctIndex": 0, "consequences": ["China installs most robots; Korea runs the most per worker.", "Buying the most is a volume measure.", "China runs over 2 million industrial robots."], "explanation": "China leads on volume; Korea leads on density. Saying both shows you know the difference."}, "proReasoning": "Strong candidates separate volume from density. Each answers a different question.", "commonMistake": "Using one number to answer two different questions.", "mentalModel": "Volume and density differ."}, "invest": {"call": {"kind": "theCall", "situation": "You compare demand potential in China and South Korea.", "prompt": "Which reading is sound?", "options": ["Both are fully saturated", "China has room to rise; Korea is near saturation", "Korea has more room to automate than China does"], "correctIndex": 1, "consequences": ["China’s density was still rising fast.", "470 per 10,000 in China against 1,012 in Korea.", "Korea already runs over one robot per ten workers."], "explanation": "China’s density of 470 sits well below Korea’s 1,012, with a huge workforce behind it."}, "proReasoning": "Investors combine volume and density. High volume with lower density signals room to grow.", "commonMistake": "Assuming the biggest buyer is also the most saturated.", "mentalModel": "Big and not yet dense.", "sources": [{"url": "https://businesswire.com/news/home/20241120789594/en/China-Overtakes-Germany-and-Japan-in-Robot-Density-%e2%80%93-IFR-reports", "label": "IFR, robot density (World Robotics 2024)"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You must choose between selling into China or Korea first.", "prompt": "What does the pair of numbers tell you?", "options": ["Korea has the most robots in total", "Neither market buys robots", "China has volume and room to automate"], "correctIndex": 2, "consequences": ["Korea is densest, but China installs far more robots.", "Both buy robots in large numbers.", "Huge installs and density still rising."], "explanation": "China pairs record volume with density still well below Korea. That is scale with headroom."}, "proReasoning": "Founders read volume for market size and density for headroom.", "commonMistake": "Picking a market from one statistic.", "mentalModel": "Size plus headroom."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how Korea can be most automated if China buys far more robots.", "prompt": "What's the clearest answer?", "options": ["Korea has far more robots per worker", "China counts robots differently", "Korea buys more robots in total"], "correctIndex": 0, "consequences": ["1,012 per 10,000 employees against China’s 470.", "Both use the same IFR density measure.", "China installs far more in total."], "explanation": "Density divides by workers. China has many more workers, so its density is lower."}, "proReasoning": "Use two numbers to answer a puzzle: totals and per-worker figures.", "commonMistake": "Mixing up the total with the rate.", "mentalModel": "Divide by the workers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5685afac12ea$ml$]::text[]),
($ml$656e743d-7ebe-5192-9eb0-c0398f5a6934$ml$::uuid, $ml$robotics$ml$, 4, 3, $ml${"id": "robotics-d4-c3", "title": "Where to open the next office", "lessonTitle": "The numbers that measure automation", "slot": 3, "type": "decide", "brief": {"headline": "You run a robot integrator choosing a new market. In 2023, the US had 295 robots per 10,000 factory workers; Germany had 429.", "kicker": "Decide: where does density point you?", "fullText": "Day 4 introduced robot density, the number of industrial robots per 10,000 manufacturing employees. South Korea led at 1,012 in 2023, and the US sat at 295.\n\nGermany had 429 and Japan 419. The world average was far lower, at 162.\n\nYou install and program robots for factories. You can open one new office this year.", "sources": [{"url": "https://businesswire.com/news/home/20241120789594/en/China-Overtakes-Germany-and-Japan-in-Robot-Density-%e2%80%93-IFR-reports", "label": "IFR, robot density (World Robotics 2024)"}]}, "evidence": {"kind": "faceOff", "prompt": "Which market has more automation left to do, by density?", "left": {"name": "United States", "note": "295 robots per 10,000 workers"}, "right": {"name": "Germany", "note": "429 robots per 10,000 workers"}, "correctIndex": 0, "explanation": "Lower density means a smaller share of factory work is automated today, leaving more to install."}, "numbers": {"kind": "numberSense", "prompt": "What was US robot density in 2023, in robots per 10,000 factory workers?", "min": 0, "max": 1000, "value": 295, "unit": "robots", "explanation": "About 295, well below Germany and Japan. That gap is the opportunity."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're joining the integrator as a field engineer. You're asked where demand will grow.", "prompt": "Which answer uses the data?", "options": ["Nowhere, demand is flat", "The US, with lower density", "Germany, because it leads Europe"], "correctIndex": 1, "consequences": ["Density gaps point to growth.", "295 against Germany’s 429 suggests more to automate.", "Higher density can mean less left to install."], "explanation": "The US trails Germany and Japan on density. More factory work there is still done by hand."}, "proReasoning": "Engineers who read market data can say where their skills will be needed.", "commonMistake": "Assuming the most advanced market grows fastest.", "mentalModel": "Grow where gaps are."}, "invest": {"call": {"kind": "theCall", "situation": "Two integrators pitch you: one US-focused, one Germany-focused.", "prompt": "Which has more headroom, all else equal?", "options": ["The Germany-focused integrator", "They are identical", "The US-focused integrator"], "correctIndex": 2, "consequences": ["Germany is further along, at 429.", "Density differs by a wide margin.", "Lower density means more factories still to automate."], "explanation": "At 295 against 429, US factories have more automation left to buy."}, "proReasoning": "Investors look for headroom. Density shows how much is left.", "commonMistake": "Backing the market that is already furthest along.", "mentalModel": "Headroom beats hype.", "sources": [{"url": "https://businesswire.com/news/home/20241120789594/en/China-Overtakes-Germany-and-Japan-in-Robot-Density-%e2%80%93-IFR-reports", "label": "IFR, robot density (World Robotics 2024)"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You can open one office, in the US or Germany.", "prompt": "What does density suggest?", "options": ["Open in the US, where density is lower", "Open in Germany, where it is higher", "Skip both and wait"], "correctIndex": 0, "consequences": ["More factory work there is still unautomated.", "Higher density means more competition for less work.", "Waiting gives the gap to rivals."], "explanation": "Density points to the US: 295 robots per 10,000 workers against Germany’s 429."}, "proReasoning": "Founders go where there is the most work left to win. Density helps find it.", "commonMistake": "Following prestige instead of headroom.", "mentalModel": "Go where work is left."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks the US must be among the most automated countries.", "prompt": "What's a fair reply?", "options": ["The US has almost no robots", "It trails Korea, Germany and Japan", "Yes, it leads the world on robot density"], "correctIndex": 1, "consequences": ["It runs plenty, just fewer per worker.", "295 per 10,000 against 1,012, 429 and 419.", "Korea led at 1,012 in 2023."], "explanation": "By density, the US sits well behind several countries. That surprises many people."}, "proReasoning": "One comparison resets an assumption. Density makes the gap clear.", "commonMistake": "Assuming a big economy is the most automated.", "mentalModel": "Big is not dense."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:da35beb78469$ml$]::text[]),
($ml$457bce40-1508-5a41-9f5e-e6af5dedc9ca$ml$::uuid, $ml$robotics$ml$, 5, 1, $ml${"id": "robotics-d5-c1", "title": "A robot in the living room", "lessonTitle": "The safety rules robots must follow", "slot": 1, "type": "apply", "brief": {"headline": "In October 2025, 1X opened orders for NEO, a home humanoid at $20,000 or $499 a month. It weighs 66 pounds and can lift 154 pounds.", "kicker": "Apply the safety rule: what comes first when a robot lives with people?", "fullText": "1X says NEO is built for chores in the home, with first orders shipping to US homes in 2026. It weighs 66 pounds, can lift 154 pounds, carries 55 pounds and runs at 22 decibels, quieter than a refrigerator, the company says.\n\nOwners can schedule a 1X expert to guide it through unknown tasks.\n\nDay 5 set out how factories keep people safe: guards around classic robots, and force limits for cobots that touch people. A home has no guards, and the people nearby include children and guests.", "sources": [{"url": "https://www.businesswire.com/news/home/20251027434628/en/1X-Launches-NEO-The-Robot-Redefining-Life-at-Home", "label": "1X via Business Wire, 1X launches NEO, Oct 2025"}, {"url": "https://www.automate.org/tech-papers/iso-ts-15066-explained", "label": "A3, ISO/TS 15066 explained"}]}, "evidence": {"kind": "multipleChoice", "prompt": "NEO shares space with people in a home. Which day 5 idea matters most?", "options": ["Cages around every robot", "Faster motion for more chores", "Safety limits before speed"], "correctIndex": 2, "explanation": "When robots share space with people, safety limits come before speed. Homes cannot use cages."}, "numbers": {"kind": "numberSense", "prompt": "NEO can lift 154 pounds and weighs 66. How many times its own weight can it lift?", "min": 0, "max": 5, "value": 2.3, "unit": "x", "explanation": "About 2.3 times its weight. Strength like that needs safety limits around people."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a home robot company. You're asked what to design first.", "prompt": "Which answer fits day 5?", "options": ["Limits on force near people", "The fastest chore speed", "A bigger battery"], "correctIndex": 0, "consequences": ["A strong robot near people needs limits before anything else.", "Speed comes after safety around people.", "Battery life matters, but safety comes first."], "explanation": "NEO can lift 154 pounds. Around people, limits on force come before speed or runtime."}, "proReasoning": "Candidates who lead with safety show they understand robots that share space with people.", "commonMistake": "Leading with speed for a robot that lives with people.", "mentalModel": "Safety before speed."}, "invest": {"call": {"kind": "theCall", "situation": "A friend wants to invest in home humanoids after the NEO launch.", "prompt": "What question should come early?", "options": ["Whether it can lift a car", "How it stays safe around people at home", "How many colors and finishes it comes in"], "correctIndex": 1, "consequences": ["Strength beyond chores adds risk, not value.", "Homes have no guards, so safety design is central.", "Colors do not decide whether homes accept it."], "explanation": "A home robot lives beside children and guests. Its safety design shapes whether it can sell at all."}, "proReasoning": "Investors ask what could stop a product, not only what it can do. Safety near people tops the list.", "commonMistake": "Judging a home robot by its feature list alone.", "mentalModel": "Safety decides adoption."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're building a home helper robot. A cofounder wants maximum lifting strength.", "prompt": "What should guide that choice?", "options": ["As much strength as the motors can give", "Strength does not matter", "Strength only as high as chores need"], "correctIndex": 2, "consequences": ["Extra force raises the stakes of any contact.", "Strength matters a lot for safety.", "More strength near people means more risk to manage."], "explanation": "Factory cobots have force limits because contact can hurt. A home robot needs the same thinking."}, "proReasoning": "Founders size strength to the task, not the spec sheet. Unneeded force is unneeded risk.", "commonMistake": "Chasing a bigger spec that makes safety harder.", "mentalModel": "Enough force, no more."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders why factories cage robots but a home robot has no cage.", "prompt": "What's the best answer?", "options": ["Home robots must limit themselves instead", "Home robots are always too weak to hurt anyone", "Cages are only for show"], "correctIndex": 0, "consequences": ["Without a cage, the robot’s own limits keep people safe.", "NEO can lift 154 pounds.", "Guards keep factory workers away from classic arms."], "explanation": "A cage keeps people away from the robot. Without one, the robot itself must keep contact safe."}, "proReasoning": "Explain safety by what replaces the cage. Limits built into the robot do that job.", "commonMistake": "Assuming a robot without a cage needs no safety design.", "mentalModel": "No cage, more limits."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8396ecd38dd7$ml$]::text[]),
($ml$09abadb6-fdd8-5fb2-a3f6-b751fc846917$ml$::uuid, $ml$robotics$ml$, 5, 2, $ml${"id": "robotics-d5-c2", "title": "Cobots in China’s factories", "lessonTitle": "The safety rules robots must follow", "slot": 2, "type": "connect", "brief": {"headline": "Cobots can work beside people without cages, if contact stays under force limits for 29 body areas. China installed 295,000 industrial robots in 2024.", "kicker": "Connect day 5 and day 1: safety rules and robot types.", "fullText": "Day 1 sorted robots into industrial arms, service robots and cobots. Cobots are built to work right next to people, often without safety cages.\n\nDay 5 showed what makes that possible. ISO 10218 covers industrial robot safety, and ISO/TS 15066 adds rules for collaborative robots, including force limits for 29 body areas set from a study of when contact starts to hurt.\n\nA robot only counts as safe to share space with if its contact stays under those limits.", "sources": [{"url": "https://www.automate.org/tech-papers/iso-ts-15066-explained", "label": "A3, ISO/TS 15066 explained"}, {"url": "https://ifr.org/news/how-robots-work-alongside-humans/", "label": "IFR, how robots work alongside humans"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the steps to run a cobot beside people in order.", "steps": ["Pick a robot built for collaboration", "Study the task and who stands near it", "Check contact forces against the limits", "Set speeds and stops to stay under them", "Run the cell beside people"], "explanation": "A cobot is only collaborative once its contact forces are checked against the limits."}, "numbers": {"kind": "numberSense", "prompt": "ISO/TS 15066 sets force limits for how many body areas?", "min": 0, "max": 50, "value": 29, "unit": "", "explanation": "Twenty-nine areas, each with its own limit, set from a study of when contact starts to hurt."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview what makes a cobot safe to work beside.", "prompt": "Which answer is most precise?", "options": ["It never moves near people", "Contact forces under ISO/TS 15066 limits", "It is small, light and painted bright orange"], "correctIndex": 1, "consequences": ["Cobots are designed to work near people.", "The limits cover 29 body areas.", "Size and color do not make a robot safe."], "explanation": "Collaborative safety means contact forces stay under the limits for each body area."}, "proReasoning": "Naming the standard and its limits shows real safety knowledge.", "commonMistake": "Calling any small robot a cobot.", "mentalModel": "Under the limits, beside people."}, "invest": {"call": {"kind": "theCall", "situation": "A startup says its cheap arm is a cobot.", "prompt": "What should you ask first?", "options": ["How cheap can it get next year?", "How many units did it sell last year?", "Does contact stay under the force limits?"], "correctIndex": 2, "consequences": ["Price does not make a robot collaborative.", "Sales do not prove safety.", "Without that, it is not safe to run beside people."], "explanation": "A cobot claim rests on meeting collaborative safety rules. Ask for that before the price."}, "proReasoning": "Investors test the claim that defines the product. For cobots, that is safe contact.", "commonMistake": "Accepting the cobot label without proof.", "mentalModel": "Test the label.", "sources": [{"url": "https://www.automate.org/tech-papers/iso-ts-15066-explained", "label": "A3, ISO/TS 15066 explained"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells arms to Chinese factories. Buyers want them beside workers.", "prompt": "What must you prove?", "options": ["Contact forces meet the collaborative limits", "The arm is the cheapest one on the market", "The arm is the fastest"], "correctIndex": 0, "consequences": ["That is what lets the arm work beside people.", "Price does not make it safe.", "Speed often has to drop to stay under limits."], "explanation": "Working beside people requires meeting the collaborative rules. Build to them from the start."}, "proReasoning": "Founders treat safety standards as the entry ticket, not an afterthought.", "commonMistake": "Selling arms as cobots without meeting the rules.", "mentalModel": "Prove safe contact."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a robot can be safe without any cage.", "prompt": "What's the best answer?", "options": ["Cages are optional for all robots", "Its contact force stays under set limits", "It is far too weak to hurt anyone nearby"], "correctIndex": 1, "consequences": ["Classic arms still need guards.", "Limits cover 29 body areas, set from a pain study.", "Cobots can still be strong; limits keep contact safe."], "explanation": "Cobots keep contact under limits set for 29 body areas. That replaces the cage."}, "proReasoning": "Explain safety with the rule that replaces the fence. Force limits do that job.", "commonMistake": "Thinking cobots are safe just because they are small.", "mentalModel": "Limits replace the cage."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0a6906d07125$ml$]::text[]),
($ml$8510c837-515d-5471-99f7-5d5860e3c420$ml$::uuid, $ml$robotics$ml$, 5, 3, $ml${"id": "robotics-d5-c3", "title": "Faster cycle or safer cell", "lessonTitle": "The safety rules robots must follow", "slot": 3, "type": "decide", "brief": {"headline": "You run a line where a cobot works beside a packer. Running it faster would raise output, but contact forces could pass the limits.", "kicker": "Decide: speed or safety limits?", "fullText": "Day 5 opened with the first person killed by a robot: Robert Williams, at a Ford plant in Michigan in 1979, struck by a one-ton production robot.\n\nToday, classic industrial robots are kept apart from people with gates, laser scanners and mats. Cobots share space with people, and ISO/TS 15066 caps their contact forces across 29 body areas.\n\nYour plant manager wants 15% more output from the cobot cell this quarter.", "sources": [{"url": "https://www.guinnessworldrecords.com/world-records/first-human-to-be-killed-by-a-robot", "label": "Guinness World Records, first robot fatality"}, {"url": "https://www.automate.org/tech-papers/iso-ts-15066-explained", "label": "A3, ISO/TS 15066 explained"}, {"url": "https://ifr.org/news/how-robots-work-alongside-humans/", "label": "IFR, how robots work alongside humans"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Cobots must keep contact under force limits.", "Cobots may hit people at full force.", "Classic robots are kept apart from people."], "fakeIndex": 1, "explanation": "Cobots must stay under force limits. Full-force contact is exactly what the limits forbid."}, "numbers": {"kind": "numberSense", "prompt": "How many years passed between the first robot death in 1979 and 2025?", "min": 0, "max": 100, "value": 46, "unit": "", "explanation": "About 46 years. The safety rules since then come from lessons like that one."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As the cell's safety engineer, the manager asks you to speed it up.", "prompt": "What do you check first?", "options": ["How much faster the arm can possibly go", "Whether the packer minds", "Contact forces stay under the limits"], "correctIndex": 2, "consequences": ["Speed comes after the limits are confirmed.", "Comfort matters, but limits come first.", "Above the limits, the cell is no longer safe to share."], "explanation": "When robots share space with people, safety limits come before speed."}, "proReasoning": "Safety engineers confirm the limits before any speed change. Output never outranks them.", "commonMistake": "Raising speed and checking safety later.", "mentalModel": "Limits before speed."}, "invest": {"call": {"kind": "theCall", "situation": "The plant pitches a faster cobot cell to its owners.", "prompt": "What risk should owners weigh?", "options": ["Passing force limits could injure workers", "The line producing far too much output", "The robot getting bored"], "correctIndex": 0, "consequences": ["An injury can halt the line and bring lawsuits.", "More output is the goal, not the risk.", "Robots do not get bored."], "explanation": "Gains from speed vanish if the cell stops being safe for the person beside it."}, "proReasoning": "Investors weigh the downside of a shortcut. Safety failures can cost more than any gain.", "commonMistake": "Counting the extra output and not the risk.", "mentalModel": "Price in the downside.", "sources": [{"url": "https://www.automate.org/tech-papers/iso-ts-15066-explained", "label": "A3, ISO/TS 15066 explained"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells cobot software. Customers ask for more speed.", "prompt": "What should your product do?", "options": ["Remove all speed caps", "Raise speed only within the force limits", "Let users bypass the limits when they need to"], "correctIndex": 1, "consequences": ["Caps keep contact under the limits.", "Customers get speed without losing safety.", "A bypass invites injuries and liability."], "explanation": "Speed is welcome as long as contact stays under the limits. Software can enforce that."}, "proReasoning": "Founders build safety into the product so customers cannot trade it away by accident.", "commonMistake": "Shipping a speed boost that ignores the limits.", "mentalModel": "Speed inside the rules."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a factory would not just run its robots as fast as possible.", "prompt": "What's the best answer?", "options": ["Robots break down if they ever go fast", "Faster robots cost less", "Near people, safety limits come first"], "correctIndex": 2, "consequences": ["Speed is limited for people’s safety, not only wear.", "Speed and cost are separate questions.", "Contact above the limits can hurt the person nearby."], "explanation": "When a robot shares space with a person, speed is capped so contact stays safe."}, "proReasoning": "Explain a limit by who it protects. Here, the worker beside the robot.", "commonMistake": "Thinking speed is the only goal.", "mentalModel": "Safety caps speed."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b80666a99634$ml$]::text[]),
($ml$94690b87-d132-56b1-9809-2ec788521a23$ml$::uuid, $ml$robotics$ml$, 6, 1, $ml${"id": "robotics-d6-c1", "title": "Apptronik's $5 billion round", "lessonTitle": "A $39 billion bet on humanoids", "slot": 1, "type": "apply", "brief": {"headline": "In February 2026, Apptronik raised $520 million at about a $5 billion valuation to build its Apollo humanoid. Google and Mercedes-Benz are among its backers.", "kicker": "Apply the valuation rule: what has Apptronik proven, and what is still a bet?", "fullText": "Apptronik called the round a Series A extension. B Capital and the Qatar Investment Authority also joined.\n\nThe company has commercial agreements with Mercedes-Benz and with GXO Logistics, and co-develops Gemini-based robot AI models with Google DeepMind. It plans to scale manufacturing, grow beyond 300 employees and build a training and data facility in Texas.\n\nIt gave no production volumes. It expects expanded deployments in factories and warehouses over the next year, and aims later at care and home uses.", "sources": [{"url": "https://www.unite.ai/apptronik-raises-520-million-series-a-extension-at-5-billion-valuation-with-backing-from-google-and-mercedes-benz/", "label": "Unite.AI, Apptronik raises $520 million at a $5 billion valuation, Feb 2026"}, {"url": "https://www.therobotreport.com/figure-ai-raises-1b-in-series-c-funding-toward-humanoid-robot-development/", "label": "The Robot Report, Figure AI raises $1B in Series C funding"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each item already in place, or still to be proven?", "buckets": ["In place", "Still to prove"], "items": [{"text": "A commercial deal with Mercedes-Benz", "bucket": 0}, {"text": "A commercial deal with GXO Logistics", "bucket": 0}, {"text": "$520 million raised in this round", "bucket": 0}, {"text": "Robots built at scale", "bucket": 1}, {"text": "Robots working in homes", "bucket": 1}], "explanation": "Deals and cash are in place. Production volumes and home use are plans, so they still have to be proven."}, "numbers": {"kind": "numberSense", "prompt": "Figure's $39 billion valuation is about how many times Apptronik's $5 billion?", "min": 0, "max": 12, "value": 7.8, "unit": "x", "explanation": "About 7.8 times. Neither number counts robots delivered; both price in future production."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Apptronik plans to grow beyond 300 employees. You interview for a role there.", "prompt": "Which question shows you know where a humanoid maker is stuck?", "options": ["Which logo goes on the robot?", "How will you scale manufacturing?", "How big will the next round be?"], "correctIndex": 1, "consequences": ["Branding is not what holds a humanoid maker back.", "Apptronik gave no production volumes, so scaling is the open question.", "The money is raised; the question is turning it into robots."], "explanation": "The round pays to scale manufacturing, but no volumes were given. Building robots at scale is the real test."}, "proReasoning": "Strong candidates ask about the hardest unproven step. For humanoids, that is production.", "commonMistake": "Asking about funding instead of delivery.", "mentalModel": "Ask about the factory."}, "invest": {"call": {"kind": "theCall", "situation": "A friend wants in at the next round, citing the $5 billion valuation as proof.", "prompt": "What should you track instead?", "options": ["The size of each new round", "How famous the investors are", "Robots deployed doing paid work"], "correctIndex": 2, "consequences": ["Bigger rounds show investor hope, not output.", "Famous backers do not build robots.", "Deployments show the robot works for customers."], "explanation": "A valuation is a promise. Robots working at Mercedes-Benz and GXO are the evidence to watch."}, "proReasoning": "Investors judge humanoid makers by robots delivered, not by the last price paid for shares.", "commonMistake": "Treating a high valuation as proof of a working business.", "mentalModel": "Count robots, not rounds.", "sources": [{"url": "https://www.therobotreport.com/figure-ai-raises-1b-in-series-c-funding-toward-humanoid-robot-development/", "label": "The Robot Report, Figure AI raises $1B in Series C funding"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You build humanoid software. Apptronik and other makers might buy it.", "prompt": "Where should you look for your first real test?", "options": ["A site with a signed commercial deal", "A robot shown only in polished demo videos", "A future home market"], "correctIndex": 0, "consequences": ["Mercedes-Benz and GXO sites are where robots meet real work.", "Videos do not show your software on paid tasks.", "Apptronik puts homes later, so there is no market yet."], "explanation": "Signed customers like Mercedes-Benz and GXO are where humanoids face real work first."}, "proReasoning": "Founders test where robots meet paying customers. That is where needs are concrete.", "commonMistake": "Building for a market the robot maker itself places years out.", "mentalModel": "Test where the work is."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says a $5 billion humanoid company must already sell thousands of robots.", "prompt": "What's a fair reply?", "options": ["Humanoids are already in most homes", "The value prices future robots", "Yes, valuation equals sales"], "correctIndex": 1, "consequences": ["Apptronik places homes later in its plans.", "Apptronik gave no production volumes.", "A valuation reflects expectations, not robots sold."], "explanation": "Valuations price in what investors expect. Apptronik reported deals and plans, not production numbers."}, "proReasoning": "Explain a big number by what it measures. A valuation measures hope as well as results.", "commonMistake": "Reading a valuation as a sales figure.", "mentalModel": "Value is a forecast."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:98faf07d344a$ml$]::text[]),
($ml$f72af620-001b-5140-9e87-9265dc92cb85$ml$::uuid, $ml$robotics$ml$, 6, 2, $ml${"id": "robotics-d6-c2", "title": "A valuation without a sales record", "lessonTitle": "A $39 billion bet on humanoids", "slot": 2, "type": "connect", "brief": {"headline": "Figure was valued at $39 billion in September 2025 and plans 100,000 humanoids over four years. Intuitive earned $10.06 billion in 2025 from robots already working.", "kicker": "Connect day 6 and day 2: a promise of robots, and money from robots in use.", "fullText": "Day 2 showed how Intuitive earns: robots placed in hospitals, then instruments and services with every procedure. Its 2025 revenue was about $10.06 billion, and it placed 1,721 new systems.\n\nDay 6 showed a different kind of value. Figure raised over $1 billion at a $39 billion valuation and plans to ship 100,000 humanoids over four years through BotQ.\n\nOne company is valued on robots at work today. The other is valued on robots it plans to build.", "sources": [{"url": "https://www.therobotreport.com/figure-ai-raises-1b-in-series-c-funding-toward-humanoid-robot-development/", "label": "The Robot Report, Figure AI raises $1B in Series C funding"}, {"url": "https://investor.intuitivesurgical.com/news-releases/news-release-details/intuitive-announces-preliminary-fourth-quarter-and-full-year-5", "label": "Intuitive, preliminary 2025 results"}]}, "evidence": {"kind": "faceOff", "prompt": "Which company is backed by robots already earning money?", "left": {"name": "Intuitive", "note": "About $10.06 billion of 2025 revenue"}, "right": {"name": "Figure AI", "note": "$39 billion valuation, robots planned"}, "correctIndex": 0, "explanation": "Intuitive earns from robots in use. Figure is valued on the robots it plans to deliver."}, "numbers": {"kind": "numberSense", "prompt": "Figure plans 100,000 humanoids over four years. How many thousand a year is that, on average?", "min": 0, "max": 60, "value": 25, "unit": "K", "explanation": "About 25,000 a year. Intuitive placed 1,721 systems in all of 2025."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You weigh offers from Intuitive and Figure. A mentor asks how they differ.", "prompt": "Which answer shows you understand both?", "options": ["Both earn mostly from selling new robots", "Both are early-stage startups", "One earns from robots in use, one from plans"], "correctIndex": 2, "consequences": ["Intuitive earns mostly after the sale; Figure has no reported sales.", "Intuitive has an installed base of thousands of robots.", "Intuitive has revenue; Figure has a valuation and a production goal."], "explanation": "Intuitive's value rests on robots at work. Figure's rests on robots it plans to build."}, "proReasoning": "Candidates who compare business models, not just products, show judgment.", "commonMistake": "Treating every robot company as the same kind of bet.", "mentalModel": "Earned value versus promised value."}, "invest": {"call": {"kind": "theCall", "situation": "You compare Figure's valuation to Intuitive's revenue.", "prompt": "What should you remember?", "options": ["Planned robots are not delivered robots", "Figure earns more than Intuitive", "Revenue does not matter in robots"], "correctIndex": 0, "consequences": ["100,000 humanoids is a production goal, not a record of sales.", "Figure reported no revenue in these sources.", "Intuitive's revenue is why its value is grounded."], "explanation": "Figure plans 100,000 robots over four years. Until they ship, the valuation is a promise."}, "proReasoning": "Investors separate value earned from value promised. Both can be high; only one is proven.", "commonMistake": "Comparing a valuation with revenue as if they meant the same thing.", "mentalModel": "Promised is not proven.", "sources": [{"url": "https://www.therobotreport.com/figure-ai-raises-1b-in-series-c-funding-toward-humanoid-robot-development/", "label": "The Robot Report, Figure AI raises $1B in Series C funding"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your humanoid startup has a big valuation and no sales yet.", "prompt": "What should your plan prove first?", "options": ["More demo videos", "Robots doing paid work for a customer", "A higher valuation in the next round"], "correctIndex": 1, "consequences": ["Demos show ability, not customers.", "Paid work turns a promise into revenue.", "A higher price does not change what you have proven."], "explanation": "Intuitive is valued on robots earning money. A startup closes the gap by getting robots into paid work."}, "proReasoning": "Founders turn promise into proof with paying customers, not bigger rounds.", "commonMistake": "Chasing valuation before revenue.", "mentalModel": "Prove paid work."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a humanoid company with no sales can be valued at $39 billion.", "prompt": "What's the best answer?", "options": ["It secretly sells millions of robots", "Valuations equal yearly revenue", "Investors price in robots it plans to make"], "correctIndex": 2, "consequences": ["No sales figures appear in the source.", "Intuitive earns $10.06 billion; that is revenue, not a valuation.", "Figure plans 100,000 humanoids over four years."], "explanation": "A valuation is what investors pay for expected future robots, not today’s sales."}, "proReasoning": "Use two companies to explain value: one valued on revenue, one on plans.", "commonMistake": "Thinking a valuation must match current sales.", "mentalModel": "Value can run ahead of sales."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:930730e5160c$ml$]::text[]),
($ml$f79a027e-2862-5de0-a079-af83146f14fd$ml$::uuid, $ml$robotics$ml$, 6, 3, $ml${"id": "robotics-d6-c3", "title": "Milestones before the next round", "lessonTitle": "A $39 billion bet on humanoids", "slot": 3, "type": "decide", "brief": {"headline": "You run a humanoid startup. Investors offer a big valuation if you show progress; your board must pick the next milestone.", "kicker": "Decide: which milestone counts most?", "fullText": "Day 6 showed Figure's model. It raised over $1 billion at a $39 billion valuation and pairs a robot, its own AI model called Helix, and a factory called BotQ.\n\nFigure plans to ship 100,000 humanoids over four years. That is a production goal, not a record of sales.\n\nYour board can chase a flashy demo, a bigger raise, or the first robots delivered to a paying customer.", "sources": [{"url": "https://www.therobotreport.com/figure-ai-raises-1b-in-series-c-funding-toward-humanoid-robot-development/", "label": "The Robot Report, Figure AI raises $1B in Series C funding"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a humanoid maker's path from plan to proof in order.", "steps": ["Build a working robot", "Train the AI that runs it", "Set up a factory to make it", "Deliver robots to customers", "Robots do paid work every day"], "explanation": "Each step needs its own proof. The valuation is only earned once robots do paid work."}, "numbers": {"kind": "numberSense", "prompt": "About how many billion dollars was Figure valued at after its September 2025 round?", "min": 0, "max": 60, "value": 39, "unit": "B", "explanation": "$39 billion post-money. That price assumes the factory and the deliveries work."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As the startup's head of operations, you present the milestone plan.", "prompt": "Which milestone do you push for?", "options": ["First robots delivered to a paying customer", "A new demo video for social media feeds", "A record valuation"], "correctIndex": 0, "consequences": ["Delivery proves the robot, the AI and the factory together.", "Demos impress but prove little about production.", "A higher price is not progress on the product."], "explanation": "A valuation is a promise. Delivered robots are the proof investors and customers trust."}, "proReasoning": "Operations leaders anchor plans on delivery. Every other milestone feeds it.", "commonMistake": "Picking the milestone that looks best instead of the one that proves most.", "mentalModel": "Delivery is the milestone."}, "invest": {"call": {"kind": "theCall", "situation": "You are an investor deciding on the next round.", "prompt": "Which milestone would make you raise your price?", "options": ["A celebrity endorsement", "Robots working daily at a customer site", "A faster robot in a lab demo video"], "correctIndex": 1, "consequences": ["Fame does not build robots.", "Daily paid work shows the plan is becoming real.", "Lab speed says little about deliveries."], "explanation": "Investors pay more as the promise turns into delivered robots doing paid work."}, "proReasoning": "Good investors price evidence, not excitement.", "commonMistake": "Paying more for a better demo.", "mentalModel": "Pay for proof.", "sources": [{"url": "https://www.therobotreport.com/figure-ai-raises-1b-in-series-c-funding-toward-humanoid-robot-development/", "label": "The Robot Report, Figure AI raises $1B in Series C funding"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your cofounder wants to spend the round on a bigger marketing launch.", "prompt": "What's the better use of the money?", "options": ["A bigger launch event with more press", "A higher next valuation", "The factory steps that get robots delivered"], "correctIndex": 2, "consequences": ["A launch without robots raises expectations you cannot meet.", "A valuation is a result, not a use of money.", "Production is what turns plans into robots."], "explanation": "Figure pairs a robot, an AI model and a factory. Money should go to the weakest of the three."}, "proReasoning": "Founders fund the hardest step first. In humanoids, that is making robots at scale.", "commonMistake": "Spending on attention before production.", "mentalModel": "Fund the bottleneck."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how to tell whether a humanoid startup is really succeeding.", "prompt": "What's the best test?", "options": ["Count robots doing paid work", "Count its funding rounds", "Count its videos online"], "correctIndex": 0, "consequences": ["Paid work shows customers rely on the robot.", "Rounds show investor belief, not results.", "Videos show ability, not customers."], "explanation": "Count the robots delivered and working, not the robots planned."}, "proReasoning": "A simple test cuts through hype: are customers paying for robot work?", "commonMistake": "Mistaking funding for success.", "mentalModel": "Delivered, not planned."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:681b9e2aa15f$ml$]::text[]),
($ml$29ded4eb-439b-52ac-9f01-4aa4994aacd2$ml$::uuid, $ml$robotics$ml$, 7, 1, $ml${"id": "robotics-d7-c1", "title": "The gear maker humanoids need", "lessonTitle": "Why Atlas traded fluid for motors", "slot": 1, "type": "apply", "brief": {"headline": "Leaderdrive, China's largest maker of harmonic reducers, grew 2025 revenue 47% to 570.7 million yuan. Humanoid robot shipments rose nearly 480% that year, Omdia says.", "kicker": "Apply the actuator idea: why does a gear maker gain when humanoids grow?", "fullText": "An electric actuator needs more than a motor. Precision gears called harmonic reducers turn fast motor spin into the slow, strong, exact motion a joint needs.\n\nJ.P. Morgan says Leaderdrive holds 30% to 40% of China's harmonic reducer market. Its customers include humanoid makers Agibot and UBTech Robotics, and its 2025 net profit more than doubled to 124.4 million yuan.\n\nOmdia counted 13,318 humanoid robots shipped worldwide in 2025 and projects 2.6 million by 2035. Every humanoid joint needs gearing.", "sources": [{"url": "https://humanoid.guide/leaderdrive-harmonic-reducers-surge-as-humanoid-demand-lifts-shares/", "label": "Humanoid Guide, Leaderdrive harmonic reducers surge as humanoid demand lifts shares, Apr 2026"}, {"url": "https://www.fox5vegas.com/2024/04/18/boston-dynamics-retires-original-atlas-humanoid-robot-after-more-than-10-years/", "label": "FOX5 Las Vegas, Boston Dynamics retires original Atlas humanoid robot"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Where does a harmonic reducer do its job in a robot?", "options": ["In the joints, with the motor", "In the camera and vision system", "In the battery charger"], "correctIndex": 0, "explanation": "Reducers sit in the joints, turning motor spin into strong, precise motion. They are part of the actuator."}, "numbers": {"kind": "numberSense", "prompt": "Omdia counted how many thousand humanoid robots shipped worldwide in 2025?", "min": 0, "max": 30, "value": 13.3, "unit": "K", "explanation": "About 13,300. Small numbers today, but each robot has many geared joints."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a humanoid maker. You're asked what limits joint design.", "prompt": "Which answer shows you know the actuator?", "options": ["Only the paint and casing", "Only the software", "Motor and reducer together"], "correctIndex": 2, "consequences": ["Casings do not move joints.", "Software commands the joint, but hardware sets its limits.", "The reducer turns motor spin into strong, precise joint motion."], "explanation": "An electric actuator pairs a motor with a reducer. Together they decide what a joint can do."}, "proReasoning": "Strong candidates name the parts inside the actuator, not just the word.", "commonMistake": "Treating the actuator as just a motor.", "mentalModel": "Motor plus reducer."}, "invest": {"call": {"kind": "theCall", "situation": "Leaderdrive's shares rose about 40% over a year as humanoid hopes grew.", "prompt": "What should temper the excitement?", "options": ["Humanoid volumes are still small", "Reducers are not used in robots", "Leaderdrive lost money in 2025"], "correctIndex": 0, "consequences": ["13,318 humanoids shipped worldwide in 2025.", "Every robot joint needs reducers.", "Its 2025 net profit more than doubled."], "explanation": "Leaderdrive is profitable, but humanoid shipments were about 13,300 in 2025. The growth story is still early."}, "proReasoning": "Investors separate a real business from the hope priced on top of it.", "commonMistake": "Pricing in 2035 humanoid volumes as if they had arrived.", "mentalModel": "Early demand, real business.", "sources": [{"url": "https://humanoid.guide/leaderdrive-harmonic-reducers-surge-as-humanoid-demand-lifts-shares/", "label": "Humanoid Guide, Leaderdrive harmonic reducers surge as humanoid demand lifts shares, Apr 2026"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You design a low-cost humanoid. Reducers are a big share of each joint’s cost.", "prompt": "What should you do early?", "options": ["Design joints with no gearing", "Pick and qualify your reducer suppliers", "Leave the reducer choice to the very end"], "correctIndex": 1, "consequences": ["Joints need gearing to be strong and precise.", "A few makers supply most reducers, so securing them matters.", "Late choices risk shortages and redesigns."], "explanation": "Reducers come from a few makers. Choose and secure them while the design is still flexible."}, "proReasoning": "Founders lock in the parts that define cost and supply early.", "commonMistake": "Treating reducers as a commodity you can buy later.", "mentalModel": "Choose your gears early."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a gear company got rich from humanoid robots.", "prompt": "What's the best answer?", "options": ["Humanoids are made almost entirely of gears", "Gears replaced robot motors", "Every humanoid joint needs precision gears"], "correctIndex": 2, "consequences": ["Humanoids also need motors, sensors and computers.", "Reducers work with motors, not instead of them.", "Harmonic reducers sit in the actuators of each joint."], "explanation": "Humanoids have many joints, and each needs a reducer beside its motor. Gear makers sell into every one."}, "proReasoning": "Follow the part every product needs. That is often where the steady money is.", "commonMistake": "Thinking only robot makers profit from robots.", "mentalModel": "Sell the part in every joint."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:df0f8c6f9b8a$ml$]::text[]),
($ml$f38b70cf-6d72-5006-87d6-df10c5920c5a$ml$::uuid, $ml$robotics$ml$, 7, 2, $ml${"id": "robotics-d7-c2", "title": "Electric joints, scarce gears", "lessonTitle": "Why Atlas traded fluid for motors", "slot": 2, "type": "connect", "brief": {"headline": "In April 2024, Boston Dynamics replaced its hydraulic Atlas with an all-electric version. Electric joints run on motors and precision reducers, made by a few specialists.", "kicker": "Connect day 7 and day 3: the actuator switch, and who holds the parts.", "fullText": "Day 7 showed the switch. The original Atlas ran on hydraulics, pushing pressurized fluid through pistons. The new Atlas is all electric, stronger and with a broader range of motion.\n\nDay 3 showed where power sits. Robot joints need precision reducers made by a few specialists, and robot growth has caused shortages.\n\nWhen the industry moves to electric joints, demand moves to motors and reducers too.", "sources": [{"url": "https://www.fox5vegas.com/2024/04/18/boston-dynamics-retires-original-atlas-humanoid-robot-after-more-than-10-years/", "label": "FOX5 Las Vegas, Boston Dynamics retires original Atlas humanoid robot"}, {"url": "https://www.therobotreport.com/global-robot-growth-causing-shortages-critical-components/", "label": "The Robot Report, component shortages"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The original Atlas ran on hydraulics.", "Electric joints need no gears at all.", "A few specialists make precision reducers."], "fakeIndex": 1, "explanation": "Electric joints use motors with precision reducers to get strong, exact motion."}, "numbers": {"kind": "numberSense", "prompt": "The hydraulic Atlas debuted in 2013 and retired in 2024. How many years did it serve?", "min": 0, "max": 20, "value": 11, "unit": "", "explanation": "About 11 years. Its replacement runs on electric motors and gears."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A supplier asks you, as a new hire, what the Atlas switch means for them.", "prompt": "Which answer connects the lessons?", "options": ["More demand for motors and reducers", "More demand for hydraulic pumps", "No change for parts makers"], "correctIndex": 0, "consequences": ["Electric joints need motors and precision gears.", "Atlas dropped hydraulics.", "A design shift moves demand between suppliers."], "explanation": "Leaders switching to electric joints pull demand toward motors and reducers."}, "proReasoning": "Candidates who link design choices to suppliers show systems thinking.", "commonMistake": "Seeing the actuator switch as only an engineering detail.", "mentalModel": "Design shifts move suppliers."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a hydraulic parts maker and a reducer maker.", "prompt": "Which benefits more if humanoids go electric?", "options": ["Neither one", "The reducer maker", "The hydraulic parts maker"], "correctIndex": 1, "consequences": ["One of them sells into the new design.", "Electric joints need precision reducers.", "Atlas dropped hydraulics for motors."], "explanation": "Electric joints need reducers, made by a few specialists. Hydraulic parts lose a famous user."}, "proReasoning": "Investors follow design shifts to the suppliers they favor.", "commonMistake": "Missing how a product change moves supplier demand.", "mentalModel": "Follow the design.", "sources": [{"url": "https://www.therobotreport.com/global-robot-growth-causing-shortages-critical-components/", "label": "The Robot Report, component shortages"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You switch your robot from hydraulic to electric joints, like Atlas.", "prompt": "What new risk must you manage?", "options": ["Hydraulic fluid leaks", "It has too many reducer suppliers to manage", "Reducer supply from a few makers"], "correctIndex": 2, "consequences": ["Electric joints remove the fluid system.", "The issue is too few, not too many.", "Shortages of precision reducers can stall output."], "explanation": "Going electric removes hoses and pumps, but adds dependence on precision reducers."}, "proReasoning": "Founders trade one set of risks for another when they change designs. Name the new one.", "commonMistake": "Assuming a better design has no supply risk.", "mentalModel": "New design, new risk."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Boston Dynamics dropped hydraulics if they worked for a decade.", "prompt": "What's the best answer?", "options": ["Electric joints gave more strength and range", "Hydraulics were banned in robots that year", "Electric motors are always weaker"], "correctIndex": 0, "consequences": ["Boston Dynamics said the new Atlas is stronger with more range.", "No ban; it was a design choice.", "The electric Atlas is stronger, the company says."], "explanation": "The electric Atlas is stronger with a broader range of motion. The actuator decides what the body can do."}, "proReasoning": "Explain a redesign by what the new part allows. Here, more strength and range.", "commonMistake": "Thinking old designs are dropped only when they fail.", "mentalModel": "Better actuators, better body."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7a7752c3cbe6$ml$]::text[]),
($ml$1aed5e29-4d52-506c-b168-e7b29b09fcfb$ml$::uuid, $ml$robotics$ml$, 7, 3, $ml${"id": "robotics-d7-c3", "title": "Hydraulic or electric for a warehouse robot", "lessonTitle": "Why Atlas traded fluid for motors", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup building a humanoid for warehouses. Your engineers must pick hydraulic or electric joints before the next prototype.", "kicker": "Decide: which actuator fits a robot that works beside people all day?", "fullText": "Day 7 compared two ways to move a joint. Hydraulic actuators push pressurized fluid through pistons for force. Electric actuators use motors.\n\nThe original Atlas weighed about 330 pounds and at first was tethered to a power supply. Boston Dynamics replaced it with an all-electric Atlas, which it says is stronger with a broader range of motion, and planned tests with Hyundai.\n\nYour robot must run indoors, quietly, on battery, near warehouse staff.", "sources": [{"url": "https://www.fox5vegas.com/2024/04/18/boston-dynamics-retires-original-atlas-humanoid-robot-after-more-than-10-years/", "label": "FOX5 Las Vegas, Boston Dynamics retires original Atlas humanoid robot"}]}, "evidence": {"kind": "faceOff", "prompt": "Which drive did Boston Dynamics choose for its new Atlas?", "left": {"name": "All-electric motors", "note": "Motors drive the joints"}, "right": {"name": "Hydraulics", "note": "Fluid drives the joints"}, "correctIndex": 0, "explanation": "It retired the hydraulic Atlas and unveiled an all-electric one in April 2024."}, "numbers": {"kind": "numberSense", "prompt": "About how many pounds did the original hydraulic Atlas weigh?", "min": 0, "max": 600, "value": 330, "unit": "lb", "explanation": "About 330 pounds, and at first it was tethered to a power supply."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a robotics engineer asked for your recommendation.", "prompt": "Which drive do you propose?", "options": ["Whichever looks better on video", "Electric, as Atlas moved to", "Hydraulic, as the old Atlas used"], "correctIndex": 1, "consequences": ["Looks do not decide the drive.", "Electric suits indoor, battery-powered work near people.", "Boston Dynamics moved away from hydraulics."], "explanation": "Boston Dynamics rebuilt Atlas around electric drives. That fits a battery robot working indoors."}, "proReasoning": "Engineers who cite a leading example and the task make strong recommendations.", "commonMistake": "Choosing the drive without tying it to the job.", "mentalModel": "Fit the drive to the job."}, "invest": {"call": {"kind": "theCall", "situation": "Two humanoid startups pitch you, one hydraulic and one electric.", "prompt": "Which choice matches the industry leader?", "options": ["The hydraulic one", "Both are equally current", "The electric one"], "correctIndex": 2, "consequences": ["The hydraulic Atlas retired in 2024.", "The leader made a clear choice.", "Boston Dynamics switched Atlas to electric in 2024."], "explanation": "The leader moved to electric joints. A hydraulic newcomer bets against that shift."}, "proReasoning": "Investors notice when a startup bets against the direction leaders took.", "commonMistake": "Ignoring which way the leaders moved.", "mentalModel": "Read the leaders.", "sources": [{"url": "https://www.fox5vegas.com/2024/04/18/boston-dynamics-retires-original-atlas-humanoid-robot-after-more-than-10-years/", "label": "FOX5 Las Vegas, Boston Dynamics retires original Atlas humanoid robot"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your hydraulic prototype is strong but needs a pump and hoses.", "prompt": "What should you do for a warehouse product?", "options": ["Move to electric before scaling", "Keep hydraulics and add more hoses", "Wait for buyers to complain"], "correctIndex": 0, "consequences": ["Changing now is cheaper than after production starts.", "More hoses add weight and maintenance.", "Late changes cost far more."], "explanation": "Actuator choice shapes cost, weight and power. Boston Dynamics rebuilt Atlas to change it."}, "proReasoning": "Founders fix core design choices before scaling. Changing later costs much more.", "commonMistake": "Scaling a design you already doubt.", "mentalModel": "Decide before you scale."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what an actuator is and why it matters for a robot.", "prompt": "What's the best answer?", "options": ["It stores the robot’s map", "It moves joints, setting what the body can do", "It measures the distance to nearby objects"], "correctIndex": 1, "consequences": ["Memory and maps belong to the computer.", "Actuators turn energy into motion.", "Sensors measure the world."], "explanation": "An actuator turns energy into motion. Its strength and range decide what a robot body can do."}, "proReasoning": "Explain a part by what it lets the robot do. Actuators set strength and reach.", "commonMistake": "Mixing up actuators with sensors.", "mentalModel": "Actuators make motion."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0b17fec0eb16$ml$]::text[]),
($ml$4984a7d4-d766-5446-848b-2be597f78f4e$ml$::uuid, $ml$robotics$ml$, 8, 1, $ml${"id": "robotics-d8-c1", "title": "Hesai's 1.6 million lidars", "lessonTitle": "The lidar that fell under $200", "slot": 1, "type": "apply", "brief": {"headline": "Hesai shipped 1,620,406 lidar sensors in 2025, and expects 3 to 3.5 million in 2026. Robotics took 239,273 of them; cars took the rest.", "kicker": "Apply the volume rule: who really sets the price of a robot sensor?", "fullText": "Hesai's 2025 revenue was about 3.03 billion yuan, and its net income 436 million yuan. Driver-assistance systems in cars took 1,381,133 of its lidars.\n\nIn November 2024, Hesai had said its ATX lidar would sell for under $200 in 2025. A revamped ATX powered by its new chip was due to start production in April 2026.\n\nRobot makers buy the same kind of sensor that carmakers buy by the million. Car volume pays for the factories and chips that push prices down.", "sources": [{"url": "https://investor.hesaitech.com/news-releases/news-release-details/hesai-group-reports-fourth-quarter-and-full-year-2025-unaudited", "label": "Hesai Group, fourth quarter and full year 2025 results, Mar 2026"}, {"url": "https://www.thestar.com.my/business/business-news/2024/11/28/chinas-hesai-to-halve-lidar-prices-next-year-sees-wide-adoption-of-electric-cars", "label": "The Star (Reuters), China's Hesai to halve lidar prices next year"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which buyers took most of Hesai's lidars in 2025?", "options": ["Carmakers, for driver assistance", "Phone makers, for face scanning", "Robot makers, for robot vision"], "correctIndex": 0, "explanation": "Driver-assistance systems took about 1.38 million of 1.62 million. Cars drive the volume."}, "numbers": {"kind": "numberSense", "prompt": "Robotics took 239,273 of Hesai's 1,620,406 lidars. About what percent is that?", "min": 0, "max": 60, "value": 15, "unit": "%", "explanation": "About 15%. Robots ride on a supply chain that cars pay for."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a hardware role at a robot maker.", "prompt": "Which answer shows you understand sensor costs?", "options": ["Car volumes push lidar prices down", "Robot makers set lidar prices", "Lidar prices only rise"], "correctIndex": 0, "consequences": ["Cars took about 85% of Hesai’s lidars in 2025.", "Robotics was about 15% of Hesai’s shipments.", "Hesai cut prices as volume grew."], "explanation": "Carmakers buy lidar by the million. Robot makers benefit from the scale cars create."}, "proReasoning": "Hardware candidates who know where parts come from stand out.", "commonMistake": "Assuming robot demand sets sensor prices.", "mentalModel": "Sensors follow cars."}, "invest": {"call": {"kind": "theCall", "situation": "You look at a lidar maker that sells only to robot makers.", "prompt": "What disadvantage does it face against Hesai?", "options": ["No need for chips", "Far less volume to cut costs", "Too many car customers"], "correctIndex": 1, "consequences": ["Custom chips are how Hesai cut costs.", "Hesai shipped 1.6 million units, mostly to cars.", "It has the opposite problem: no car customers."], "explanation": "Volume pays for chips and factories. A robot-only maker lacks the car volume that lowers costs."}, "proReasoning": "Investors ask who has the scale. In sensors, carmakers supply it.", "commonMistake": "Ignoring scale when comparing hardware makers.", "mentalModel": "Scale sets cost.", "sources": [{"url": "https://www.thestar.com.my/business/business-news/2024/11/28/chinas-hesai-to-halve-lidar-prices-next-year-sees-wide-adoption-of-electric-cars", "label": "The Star (Reuters), China's Hesai to halve lidar prices next year"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your robot needs 3D sensing. You could design a custom sensor or buy a car lidar.", "prompt": "Which choice fits a startup budget?", "options": ["Design a custom lidar", "Skip 3D sensing entirely", "Buy a car-volume lidar"], "correctIndex": 2, "consequences": ["Custom sensors cost far more at low volume.", "Your robot needs it to work safely.", "Car volume keeps the price low and supply steady."], "explanation": "Hesai shipped 1.6 million lidars, mostly for cars. Building on that scale is cheaper than custom."}, "proReasoning": "Founders borrow scale from bigger industries wherever they can.", "commonMistake": "Designing custom parts that another industry already makes cheaply.", "mentalModel": "Borrow the scale."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why robot sensors got so much cheaper so fast.", "prompt": "What's the best answer?", "options": ["Cars buy the same sensors by the million", "Robots stopped needing sensors to move around", "Governments cap sensor prices"], "correctIndex": 0, "consequences": ["Hesai shipped 1.38 million lidars for cars in 2025.", "Robots still need 3D sensing.", "Volume and custom chips cut costs."], "explanation": "Car demand pays for the factories and chips that push lidar prices down for everyone."}, "proReasoning": "Explain a price drop by who buys in volume. Here, carmakers.", "commonMistake": "Thinking robot makers drove the price drop themselves.", "mentalModel": "Cars pay for the scale."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:97539e65cecb$ml$]::text[]),
($ml$1836e6cf-a823-5eb9-a343-46dd81b37091$ml$::uuid, $ml$robotics$ml$, 8, 2, $ml${"id": "robotics-d8-c2", "title": "Mass-made or scarce", "lessonTitle": "The lidar that fell under $200", "slot": 2, "type": "connect", "brief": {"headline": "Hesai said its Hangzhou plant would reach 1.5 million lidars a year in 2025. Precision reducers, by contrast, come from a few specialists and run short in booms.", "kicker": "Connect day 8 and day 3: which parts are cheap, and which hold power.", "fullText": "Day 3 showed that power in robotics sits with whoever makes the parts nobody can skip, like precision reducers from a few specialists.\n\nDay 8 showed the opposite case. Lidar became cheap because carmakers buy it by the million. Hesai planned to more than double its Hangzhou output to 1.5 million units a year and cut its ATX price below $200.\n\nSome robot parts ride on huge outside demand. Others are scarce and made by few hands.", "sources": [{"url": "https://www.thestar.com.my/business/business-news/2024/11/28/chinas-hesai-to-halve-lidar-prices-next-year-sees-wide-adoption-of-electric-cars", "label": "The Star (Reuters), China's Hesai to halve lidar prices next year"}, {"url": "https://www.therobotreport.com/global-robot-growth-causing-shortages-critical-components/", "label": "The Robot Report, component shortages"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each robot part mass-made or scarce?", "buckets": ["Mass-made", "Scarce"], "items": [{"text": "Car lidar from a 1.5 million unit plant", "bucket": 0}, {"text": "A sensor carmakers buy by the million", "bucket": 0}, {"text": "Precision reducers from a few specialists", "bucket": 1}, {"text": "A joint gear that runs short in booms", "bucket": 1}], "explanation": "Parts shared with cars are made in huge volumes. Precision reducers come from few makers."}, "numbers": {"kind": "numberSense", "prompt": "Hesai's Hangzhou plant was set to reach how many million lidars a year in 2025?", "min": 0, "max": 4, "value": 1.5, "unit": "M", "explanation": "About 1.5 million a year, more than double its previous output."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A robot maker asks you to rank supply risks in its bill of materials.", "prompt": "Which part do you flag first?", "options": ["Standard cables", "Precision reducers", "Car-volume lidar"], "correctIndex": 1, "consequences": ["Many suppliers sell them.", "Few makers, frequent shortages.", "Made by the million, prices falling."], "explanation": "Mass-made parts are cheap and steady. Scarce parts from few makers are where supply breaks."}, "proReasoning": "Candidates who rank risks by scarcity, not cost, show supply chain sense.", "commonMistake": "Ranking risk by price alone.", "mentalModel": "Scarcity sets risk."}, "invest": {"call": {"kind": "theCall", "situation": "You compare two suppliers: a lidar maker and a reducer specialist.", "prompt": "Which likely has more pricing power?", "options": ["The lidar maker", "Both have the same", "The reducer specialist"], "correctIndex": 2, "consequences": ["Lidar prices fell as car volume grew.", "Scarcity differs sharply between the two.", "Few makers and every joint needs one."], "explanation": "Lidar got cheaper with volume. Reducers stay scarce, so their makers hold more power."}, "proReasoning": "Investors look for suppliers whose parts nobody can skip and few can make.", "commonMistake": "Assuming every component maker has the same pricing power.", "mentalModel": "Scarce parts command price.", "sources": [{"url": "https://www.therobotreport.com/global-robot-growth-causing-shortages-critical-components/", "label": "The Robot Report, component shortages"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You must cut your robot’s cost. You can redesign around sensors or around joints.", "prompt": "Where are savings easiest?", "options": ["Use car-volume sensors", "Squeeze the reducer makers", "Drop the joint gears"], "correctIndex": 0, "consequences": ["Car scale already pushed lidar under $200.", "Scarce suppliers rarely cut prices for small buyers.", "Joints need gears to work."], "explanation": "Mass-made sensors are already cheap. Scarce reducers resist price cuts."}, "proReasoning": "Founders cut cost where the market is already deep. Fighting scarce suppliers rarely works.", "commonMistake": "Trying to cut cost where you have the least power.", "mentalModel": "Save where volume lives."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend wonders why some robot parts get cheaper and others stay pricey.", "prompt": "What's the best answer?", "options": ["Robot makers choose the prices", "Mass demand versus few makers", "Random luck each year"], "correctIndex": 1, "consequences": ["Suppliers with power set prices.", "Car lidar is mass-made; reducers come from few specialists.", "Volume and scarcity explain it."], "explanation": "Parts made in huge volumes for other industries get cheap. Parts only few can make stay costly."}, "proReasoning": "One idea explains both trends: volume pushes prices down, scarcity holds them up.", "commonMistake": "Expecting every part to follow the same price path.", "mentalModel": "Volume or scarcity."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1acb6ab5de99$ml$]::text[]),
($ml$bfacb10c-58d0-54ac-a14a-992497a60ca7$ml$::uuid, $ml$robotics$ml$, 8, 3, $ml${"id": "robotics-d8-c3", "title": "Custom sensor or car lidar", "lessonTitle": "The lidar that fell under $200", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup building a delivery robot. Your team built a custom 3D sensor, but a car lidar now sells for under $200.", "kicker": "Decide: keep the custom sensor, or redesign around the cheaper part?", "fullText": "Day 8 showed how car volumes crushed lidar prices. In November 2024, Hesai said its ATX sensor would sell for under $200 in 2025, half the price of its AT128.\n\nHesai credited its own chips and fuller factories. Its quarterly lidar sales had more than tripled to nearly 130,000 units, supplying a dozen Chinese carmakers including BYD and Li Auto.\n\nYour custom sensor costs several times more and comes from one small supplier.", "sources": [{"url": "https://www.thestar.com.my/business/business-news/2024/11/28/chinas-hesai-to-halve-lidar-prices-next-year-sees-wide-adoption-of-electric-cars", "label": "The Star (Reuters), China's Hesai to halve lidar prices next year"}]}, "evidence": {"kind": "faceOff", "prompt": "Which sensor should a cost-focused robot use?", "left": {"name": "Car-volume lidar", "note": "Under $200, made at huge scale"}, "right": {"name": "Custom sensor", "note": "Higher cost, one small supplier"}, "correctIndex": 0, "explanation": "The car lidar rides on huge volume, so it is cheaper and easier to source."}, "numbers": {"kind": "numberSense", "prompt": "If the ATX at under $200 is half the price of the AT128, about what did the AT128 cost, in dollars?", "min": 0, "max": 1000, "value": 400, "unit": "$", "explanation": "About $400. One generation halved the price of the sensor."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As a hardware engineer, you’re asked to recommend the sensor.", "prompt": "What do you propose?", "options": ["Keep the custom sensor at any cost", "Remove 3D sensing", "Redesign around the cheaper car lidar"], "correctIndex": 2, "consequences": ["The custom part costs more and has one supplier.", "The robot needs 3D sensing to navigate.", "Car volume brings lower price and steady supply."], "explanation": "In robotics, the cheapest parts are the ones another industry buys by the million."}, "proReasoning": "Engineers who weigh cost and supply, not just specs, make better calls.", "commonMistake": "Holding on to a custom design out of pride.", "mentalModel": "Ride the volume."}, "invest": {"call": {"kind": "theCall", "situation": "A robot startup tells you it uses a custom sensor costing several times a car lidar.", "prompt": "What concern do you raise?", "options": ["Higher cost and single-supplier risk", "It has too many sensor suppliers to manage", "Sensors that are too cheap"], "correctIndex": 0, "consequences": ["Both hurt margins and reliability of supply.", "The issue is one supplier, not many.", "Cheap volume parts are the advantage."], "explanation": "A custom part costs more and depends on one supplier, while car lidar is under $200."}, "proReasoning": "Investors question parts that cost more than the market alternative.", "commonMistake": "Accepting a costly custom part without asking why.", "mentalModel": "Question custom parts.", "sources": [{"url": "https://www.thestar.com.my/business/business-news/2024/11/28/chinas-hesai-to-halve-lidar-prices-next-year-sees-wide-adoption-of-electric-cars", "label": "The Star (Reuters), China's Hesai to halve lidar prices next year"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Switching sensors means three months of redesign.", "prompt": "Is it worth it?", "options": ["Only if a rival does it first", "Yes, if unit cost and supply improve a lot", "No, never change a design once it works"], "correctIndex": 1, "consequences": ["Waiting lets rivals lead on cost.", "Halving the sensor cost helps every robot you sell.", "Refusing all change keeps costs high."], "explanation": "A one-time redesign that cuts every unit’s cost and supply risk usually pays back."}, "proReasoning": "Founders weigh a one-time cost against savings on every unit.", "commonMistake": "Avoiding a redesign that would pay back on every robot.", "mentalModel": "Pay once, save every unit."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a robot startup could save money on sensors.", "prompt": "What's the best answer?", "options": ["Build every sensor in-house from scratch", "Use no sensors at all", "Buy sensors that carmakers buy in bulk"], "correctIndex": 2, "consequences": ["In-house sensors cost more at small volume.", "Robots need sensors to move safely.", "Car volume pushed lidar under $200."], "explanation": "Buying the same parts carmakers buy by the million keeps a robot cheap."}, "proReasoning": "Explain savings by borrowing scale from a bigger industry.", "commonMistake": "Thinking custom is always better.", "mentalModel": "Buy what cars buy."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:14c932ae3ad0$ml$]::text[]),
($ml$5a649dae-ed69-57fa-8e9c-6bcc5ed14dd2$ml$::uuid, $ml$robotics$ml$, 9, 1, $ml${"id": "robotics-d9-c1", "title": "Dysprosium from Malaysia", "lessonTitle": "China's grip on robot magnets", "slot": 1, "type": "apply", "brief": {"headline": "In May 2025, Lynas produced dysprosium oxide at its plant in Malaysia, the first such output outside China. It calls itself the only commercial producer of separated heavy rare earths outside China.", "kicker": "Apply the magnet rule: what does a second source change for robot makers?", "fullText": "Dysprosium helps rare earth magnets keep their strength in hot motors, like the compact motors in robot joints.\n\nLynas began commissioning its heavy rare earth separation circuit in Malaysia in the March quarter of 2025 and produced its first dysprosium oxide in May. It expected first terbium oxide in June.\n\nChina makes about 92% of the world’s rare earth magnets, according to a 2023 Aspen Institute figure cited by Fortune.", "sources": [{"url": "https://www.miningweekly.com/article/lynas-begins-first-heavy-rare-earth-output-outside-china-2025-05-16", "label": "Mining Weekly, Lynas begins first heavy rare earth output outside China, May 2025"}, {"url": "https://www.fortune.com/article/elon-musk-tesla-optimus-robots-china-rare-earths", "label": "Fortune, Musk says China's rare earth curbs hit Optimus"}]}, "evidence": {"kind": "faceOff", "prompt": "In 2025, which supplier offered heavy rare earths separated outside China?", "left": {"name": "Lynas, in Malaysia", "note": "First dysprosium oxide in May 2025"}, "right": {"name": "No one outside China", "note": "All heavy rare earths still separated in China"}, "correctIndex": 0, "explanation": "Lynas produced the first dysprosium oxide outside China in May 2025."}, "numbers": {"kind": "numberSense", "prompt": "China makes about what percent of the world’s rare earth magnets?", "min": 0, "max": 100, "value": 92, "unit": "%", "explanation": "About 92%, per the 2023 Aspen Institute figure. One new producer is a start, not a cure."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing for a sourcing role at a robot maker.", "prompt": "Which development should you mention?", "options": ["China lifting all magnet rules", "Lynas separating heavy rare earths in Malaysia", "Robots no longer needing magnets in motors"], "correctIndex": 1, "consequences": ["China still requires licenses for these elements.", "It offers a first non-Chinese source of dysprosium.", "Robot joint motors still use these magnets."], "explanation": "Lynas is the only commercial producer of separated heavy rare earths outside China. Sourcing teams track it."}, "proReasoning": "Sourcing candidates who know the alternatives to the dominant supplier stand out.", "commonMistake": "Talking about magnet risk without knowing any alternatives.", "mentalModel": "Know the second source."}, "invest": {"call": {"kind": "theCall", "situation": "A friend says Lynas solves robot makers' magnet problem.", "prompt": "How do you respond?", "options": ["Yes, the problem is gone for good now", "Lynas makes no rare earths", "It helps, but China still dominates"], "correctIndex": 2, "consequences": ["One plant cannot replace a 92% share.", "Lynas produced dysprosium oxide in 2025.", "China still makes about 92% of magnets."], "explanation": "A second source lowers risk a little. China still makes most of the magnets robots use."}, "proReasoning": "Investors treat a first alternative as progress, not as a solved risk.", "commonMistake": "Treating one new supplier as the end of concentration risk.", "mentalModel": "Progress, not a fix.", "sources": [{"url": "https://www.fortune.com/article/elon-musk-tesla-optimus-robots-china-rare-earths", "label": "Fortune, Musk says China's rare earth curbs hit Optimus"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your robot uses motors with dysprosium-rich magnets.", "prompt": "What does the Lynas news let you do?", "options": ["Explore a second, non-Chinese source", "Drop all magnet planning from now on", "Switch to hydraulic joints"], "correctIndex": 0, "consequences": ["A second source lowers the risk of one licensed supply.", "China still dominates supply.", "Electric joints are the industry direction."], "explanation": "Lynas offers a first source outside China. Founders can start qualifying it."}, "proReasoning": "Founders use new suppliers to diversify, not to stop managing risk.", "commonMistake": "Ignoring a new alternative because the old supply still works.", "mentalModel": "Start diversifying."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a mine company matters to humanoid robots.", "prompt": "What's the best answer?", "options": ["It writes robot software", "Its metals go into robot motor magnets", "It builds the humanoid robots themselves"], "correctIndex": 1, "consequences": ["It produces materials, not code.", "Dysprosium keeps magnets strong in hot motors.", "Lynas separates rare earths; others build robots."], "explanation": "Robot joint motors use rare earth magnets. Dysprosium helps them work when hot."}, "proReasoning": "Follow a product back to its raw materials to see who holds power.", "commonMistake": "Thinking robots are only about software and steel.", "mentalModel": "Robots start in the mine."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ee939e5c08c4$ml$]::text[]),
($ml$f60900c0-ad90-5070-9a07-44fd31f4f6c3$ml$::uuid, $ml$robotics$ml$, 9, 2, $ml${"id": "robotics-d9-c2", "title": "One magnet, one million robots", "lessonTitle": "China's grip on robot magnets", "slot": 2, "type": "connect", "brief": {"headline": "Elon Musk targeted 1 million Optimus robots by the end of the decade. In April 2025, he said China's new magnet export licenses affected Optimus.", "kicker": "Connect day 9 and day 6: a huge production goal, and the part that can stop it.", "fullText": "Day 6 showed humanoid makers promising huge volumes: Figure plans 100,000 robots over four years.\n\nDay 9 showed what can hold those plans back. China makes about 92% of the world’s rare earth magnets, and in April 2025 it required export licenses for them. Musk said the magnets are used in Optimus's motors.\n\nThe bigger the production goal, the more motors, and the more magnets it needs.", "sources": [{"url": "https://www.fortune.com/article/elon-musk-tesla-optimus-robots-china-rare-earths", "label": "Fortune, Musk says China's rare earth curbs hit Optimus"}, {"url": "https://www.therobotreport.com/figure-ai-raises-1b-in-series-c-funding-toward-humanoid-robot-development/", "label": "The Robot Report, Figure AI raises $1B in Series C funding"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the link from magnet rules to robot output in order.", "steps": ["China requires export licenses for magnets", "Magnet shipments slow or stop", "Motor makers run short", "Robot joints cannot be built", "Robot production targets slip"], "explanation": "A license on one part runs down the chain to every robot that needs it."}, "numbers": {"kind": "numberSense", "prompt": "Musk targeted how many million Optimus robots by the end of the decade?", "min": 0, "max": 5, "value": 1, "unit": "M", "explanation": "One million. Each one needs magnets in its joint motors."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A humanoid maker interviews you for a planning role.", "prompt": "Which risk do you raise about a big volume target?", "options": ["Too few marketing staff to sell them", "Robots being too light", "Magnet supply under export licenses"], "correctIndex": 2, "consequences": ["Marketing does not build motors.", "Weight is not the volume risk.", "China makes about 92% of magnets and now licenses exports."], "explanation": "Big targets need many motors. Magnets under Chinese licenses can cap the output."}, "proReasoning": "Planners who connect targets to supply constraints show judgment.", "commonMistake": "Planning volume without checking the parts behind it.", "mentalModel": "Targets need parts."}, "invest": {"call": {"kind": "theCall", "situation": "A humanoid maker promises 1 million robots by 2030.", "prompt": "What should you price in?", "options": ["A single licensed part can stall it", "Guaranteed delivery of every robot", "No dependence on China"], "correctIndex": 0, "consequences": ["Magnets come mostly from China under licenses.", "Targets have slipped before.", "Optimus uses magnets from China, Musk said."], "explanation": "A plan aiming at 1 million units can stall on one licensed part."}, "proReasoning": "Investors discount targets that rest on one concentrated supply.", "commonMistake": "Taking a production target at face value.", "mentalModel": "Discount the target.", "sources": [{"url": "https://www.fortune.com/article/elon-musk-tesla-optimus-robots-china-rare-earths", "label": "Fortune, Musk says China's rare earth curbs hit Optimus"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans 10,000 humanoids next year.", "prompt": "What should you secure before announcing it?", "options": ["A bigger logo", "Magnet supply and a second source", "A launch party venue for the big reveal"], "correctIndex": 1, "consequences": ["Branding does not build joints.", "Without magnets, the motors cannot be built.", "Events do not secure parts."], "explanation": "Every humanoid needs magnets in its motors. Secure them before you promise volume."}, "proReasoning": "Founders back targets with supply, not just ambition.", "commonMistake": "Announcing volume you cannot source.", "mentalModel": "Secure, then promise."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a tiny magnet could slow a giant robot plan.", "prompt": "What's the best answer?", "options": ["Magnets make the robots far too heavy to walk", "Robots use magnets only for decoration", "Every joint motor needs one, mostly from China"], "correctIndex": 2, "consequences": ["Weight is not the issue.", "Magnets sit inside the motors that move joints.", "China makes about 92% and licenses exports."], "explanation": "Each joint needs a motor with rare earth magnets. If those stall, the robots stall."}, "proReasoning": "Show how a small part controls a big plan. That is concentration risk.", "commonMistake": "Thinking only big parts matter.", "mentalModel": "Small part, big plan."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ec6fce357191$ml$]::text[]),
($ml$28ffb053-8379-5b8e-bc1c-5db06154befa$ml$::uuid, $ml$robotics$ml$, 9, 3, $ml${"id": "robotics-d9-c3", "title": "Licenses, not a ban", "lessonTitle": "China's grip on robot magnets", "slot": 3, "type": "decide", "brief": {"headline": "You run a robot maker whose joint motors use Chinese rare earth magnets. China now requires export licenses for them.", "kicker": "Decide: how do you protect next year’s production?", "fullText": "Day 9 showed China's grip on robot magnets. China makes about 92% of the world’s rare earth magnets, and in April 2025 it began requiring export licenses rather than banning sales.\n\nLicenses let China slow or speed supply. Musk said the new licenses affected Tesla's Optimus, whose motors use these magnets.\n\nYour motor supplier says shipments are now uncertain month to month.", "sources": [{"url": "https://www.fortune.com/article/elon-musk-tesla-optimus-robots-china-rare-earths", "label": "Fortune, Musk says China's rare earth curbs hit Optimus"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["China makes about 92% of rare earth magnets.", "China banned all magnet exports outright.", "Licenses let China slow or speed supply."], "fakeIndex": 1, "explanation": "China required licenses, not a ban. That lets it adjust supply over time."}, "numbers": {"kind": "numberSense", "prompt": "China makes about what percent of the world’s rare earth magnets, per the Aspen figure?", "min": 0, "max": 100, "value": 92, "unit": "%", "explanation": "About 92%. Few other suppliers exist at scale."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As the maker's supply chain lead, you brief the board.", "prompt": "What do you recommend?", "options": ["Build stock and qualify a second source", "Wait quietly for licenses to clear", "Redesign without motors"], "correctIndex": 0, "consequences": ["Both protect output if licenses slow.", "Waiting leaves production to chance.", "Robot joints need motors."], "explanation": "Licenses can slow supply at any time. Stock and a second source buy you time."}, "proReasoning": "Supply chain leads act before a shortage, not after.", "commonMistake": "Hoping licenses will always be granted.", "mentalModel": "Prepare before the squeeze."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a robot maker relying on licensed magnets.", "prompt": "What question do you ask management?", "options": ["How many ads ran this quarter?", "How much magnet stock and backup do you have?", "What color will the new model come in next year?"], "correctIndex": 1, "consequences": ["Ads do not secure magnets.", "It shows whether output survives a license slowdown.", "Design looks do not affect supply."], "explanation": "Whoever controls the motor magnets holds a veto over production. Ask how the company hedges it."}, "proReasoning": "Investors ask how a company survives its biggest single-source risk.", "commonMistake": "Ignoring concentrated supply in a growth story.", "mentalModel": "Ask about the veto.", "sources": [{"url": "https://www.fortune.com/article/elon-musk-tesla-optimus-robots-china-rare-earths", "label": "Fortune, Musk says China's rare earth curbs hit Optimus"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "A supplier offers magnets with less dysprosium but slightly lower performance.", "prompt": "What should you consider?", "options": ["Reject anything below top performance spec", "Ignore it until a shortage", "Test it as a hedge against licensed supply"], "correctIndex": 2, "consequences": ["Top spec is useless if you cannot get it.", "Testing takes time you may not have later.", "A workable alternative lowers your dependence."], "explanation": "A slightly weaker part you can get beats a perfect part you cannot."}, "proReasoning": "Founders trade a little performance for a lot of supply security.", "commonMistake": "Insisting on the best part from the riskiest source.", "mentalModel": "Available beats perfect."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why China chose licenses instead of a ban.", "prompt": "What's the best answer?", "options": ["Licenses let it slow or speed supply", "Licenses mean no control at all", "Bans are always illegal"], "correctIndex": 0, "consequences": ["It can adjust supply as it chooses.", "Licenses give China a lot of control.", "Countries do impose export bans."], "explanation": "A license system lets China decide, shipment by shipment, how much leaves."}, "proReasoning": "Explain a policy by the control it gives. Licenses keep a hand on the tap.", "commonMistake": "Thinking a license is weaker than a ban.", "mentalModel": "A hand on the tap."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ec7b2f33218c$ml$]::text[]),
($ml$868c9f43-f7ff-55ec-8568-4895789f8ea7$ml$::uuid, $ml$robotics$ml$, 10, 1, $ml${"id": "robotics-d10-c1", "title": "A second brain supplier for Figure", "lessonTitle": "A robot brain for $3,499", "slot": 1, "type": "apply", "brief": {"headline": "At CES in January 2026, Qualcomm launched the Dragonwing IQ10, a processor for industrial robots and full-size humanoids. It said it is working with Figure on next-generation compute.", "kicker": "Apply the onboard compute idea: why would a humanoid maker look beyond Nvidia?", "fullText": "Qualcomm presented a full robotics stack: chips, software, tools for collecting data and training skills, and teleoperation.\n\nFigure's CEO called the platform a valuable building block. Qualcomm said it is in discussions with KUKA, and that its processors power humanoids from Booster and VinMotion.\n\nDay 10 showed Nvidia’s Jetson Thor at $3,499. A robot brain must fit the battery, so chip choice shapes what the robot can do.", "sources": [{"url": "https://www.edge-ai-vision.com/2026/01/qualcomm-introduces-a-full-suite-of-robotics-technologies-powering-physical-ai-from-household-robots-up-to-full-size-humanoids/", "label": "Qualcomm via Edge AI and Vision Alliance, robotics technologies at CES 2026, Jan 2026"}, {"url": "https://www.theregister.com/2025/08/25/nvidia_touts_jetson_thor_kit/", "label": "The Register, Nvidia touts Jetson Thor kit"}]}, "evidence": {"kind": "faceOff", "prompt": "Which claim does Qualcomm's announcement support?", "left": {"name": "Figure works with Qualcomm on compute", "note": "Collaboration on next-generation compute"}, "right": {"name": "KUKA has adopted the IQ10", "note": "Robot arms already running the chip"}, "correctIndex": 0, "explanation": "Qualcomm said it is collaborating with Figure. With KUKA, it said only that talks are under way."}, "numbers": {"kind": "numberSense", "prompt": "Nvidia's Thor module costs $2,999 in 1,000-unit orders. How many dollars below the $3,499 kit is that?", "min": 0, "max": 2000, "value": 500, "unit": "$", "explanation": "$500 less in volume. Compute is a real line in a robot’s cost."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Qualcomm's robotics group.", "prompt": "Which point shows you know the market?", "options": ["Robots should run everything in the cloud instead", "Chips do not matter for robots", "Robots need onboard compute that fits the battery"], "correctIndex": 2, "consequences": ["Onboard compute avoids waiting for the cloud.", "Compute sets how smart a robot can be.", "Robots react on board within a power budget."], "explanation": "Robots run AI on board and pay for it in watts. Chip makers compete on that budget."}, "proReasoning": "Candidates who frame compute as a power budget show real robotics sense.", "commonMistake": "Talking about chips without mentioning power.", "mentalModel": "Compute costs watts."}, "invest": {"call": {"kind": "theCall", "situation": "Qualcomm enters robot chips against Nvidia.", "prompt": "What would show Qualcomm is winning?", "options": ["Humanoid makers shipping robots on its chips", "More press releases about early-stage talks", "Higher chip specs alone"], "correctIndex": 0, "consequences": ["Shipped robots show real design wins.", "Talks, like those with KUKA, are not adoption.", "Specs matter only if robot makers choose them."], "explanation": "Qualcomm named a collaboration with Figure and talks with KUKA. Shipped robots would be the proof."}, "proReasoning": "Investors separate design wins from discussions.", "commonMistake": "Counting talks as wins.", "mentalModel": "Count design wins.", "sources": [{"url": "https://www.edge-ai-vision.com/2026/01/qualcomm-introduces-a-full-suite-of-robotics-technologies-powering-physical-ai-from-household-robots-up-to-full-size-humanoids/", "label": "Qualcomm via Edge AI and Vision Alliance, robotics technologies at CES 2026, Jan 2026"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your humanoid startup must pick a compute platform.", "prompt": "What should you weigh most?", "options": ["The most expensive option", "Compute per watt for your battery", "The chip maker with the most ads"], "correctIndex": 1, "consequences": ["Price alone does not fit the budget.", "Every watt for compute comes out of the battery.", "Ads do not change power draw."], "explanation": "Thor draws up to 130 watts. Rival platforms compete on how much they do per watt."}, "proReasoning": "Founders pick compute by what fits their power budget, not by brand.", "commonMistake": "Choosing a chip without checking power draw.", "mentalModel": "Budget the watts."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a phone chip company wants to build robot brains.", "prompt": "What's the best answer?", "options": ["Robots run on ordinary smartphones", "Robots need no computers", "Robots need efficient chips on board"], "correctIndex": 2, "consequences": ["Robots use dedicated processors.", "Robots run AI on board.", "Like phones, robots run on batteries."], "explanation": "Robots run AI on battery power, like phones. Efficient chips are what Qualcomm sells."}, "proReasoning": "Explain a move into a new market by the skill it reuses.", "commonMistake": "Thinking robot chips and phone chips have nothing in common.", "mentalModel": "Battery chips fit robots."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6cd6410eee51$ml$]::text[]),
($ml$d619a5ae-7cef-5735-876a-cbd27fad02c6$ml$::uuid, $ml$robotics$ml$, 10, 2, $ml${"id": "robotics-d10-c2", "title": "Brains and muscles share a battery", "lessonTitle": "A robot brain for $3,499", "slot": 2, "type": "connect", "brief": {"headline": "Nvidia's Jetson Thor draws up to 130 watts. Every watt it uses comes out of the same battery that powers the robot's joints.", "kicker": "Connect day 10 and day 7: the onboard brain and the actuators.", "fullText": "Day 7 showed that actuators decide what a robot body can do. Boston Dynamics rebuilt Atlas around electric motors.\n\nDay 10 showed the brain. Nvidia says Jetson Thor delivers 7.5 times the AI compute of the older Orin, peaking at 2,070 FP4 teraflops, while drawing up to 130 watts.\n\nAn electric robot runs both from one battery. More compute means less energy left for motion, unless the battery grows.", "sources": [{"url": "https://www.theregister.com/2025/08/25/nvidia_touts_jetson_thor_kit/", "label": "The Register, Nvidia touts Jetson Thor kit"}, {"url": "https://www.fox5vegas.com/2024/04/18/boston-dynamics-retires-original-atlas-humanoid-robot-after-more-than-10-years/", "label": "FOX5 Las Vegas, Boston Dynamics retires original Atlas humanoid robot"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Thor draws up to 130 watts.", "Robot compute uses no battery power.", "Electric joints run on motors."], "fakeIndex": 1, "explanation": "Onboard compute draws from the battery, the same one the electric joints use."}, "numbers": {"kind": "numberSense", "prompt": "Jetson Thor draws up to how many watts?", "min": 0, "max": 400, "value": 130, "unit": "W", "explanation": "Up to 130 watts, power the motors cannot use."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A humanoid team asks you how to balance AI and runtime.", "prompt": "Which answer connects the lessons?", "options": ["Compute and motors share one battery budget", "Compute has its own free power supply", "Motors need no power"], "correctIndex": 0, "consequences": ["Every watt for AI is a watt not moving the joints.", "Compute draws from the same battery.", "Electric joints run on motors."], "explanation": "An electric robot pays for brains and muscles from one battery."}, "proReasoning": "Candidates who see the whole power budget understand robot design.", "commonMistake": "Treating compute and motion as separate problems.", "mentalModel": "One battery, two jobs."}, "invest": {"call": {"kind": "theCall", "situation": "A humanoid maker brags about its huge onboard AI.", "prompt": "What do you ask?", "options": ["Which color is the chip?", "How long does the battery last?", "How many teraflops in total?"], "correctIndex": 1, "consequences": ["Color is irrelevant.", "Big compute can cut runtime.", "Raw compute hides the power cost."], "explanation": "Thor peaks at 2,070 teraflops but draws up to 130 watts. Runtime shows the trade-off."}, "proReasoning": "Investors test claims against the constraint they hide. For compute, that is battery life.", "commonMistake": "Judging robot AI by specs alone.", "mentalModel": "Ask about runtime.", "sources": [{"url": "https://www.theregister.com/2025/08/25/nvidia_touts_jetson_thor_kit/", "label": "The Register, Nvidia touts Jetson Thor kit"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your humanoid runs four hours. Adding a bigger chip would cut that.", "prompt": "What do you do?", "options": ["Add the biggest chip anyway", "Remove the motors", "Fit AI to the battery budget"], "correctIndex": 2, "consequences": ["A smarter robot that stops early helps no one.", "The robot needs motors to move.", "Balancing both keeps the robot useful all shift."], "explanation": "At 130 watts, the brain competes with the motors. Design for both together."}, "proReasoning": "Founders design compute and motion together. A robot must last a shift.", "commonMistake": "Maximizing one spec at the cost of runtime.", "mentalModel": "Design for the shift."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why robots can’t just carry the biggest AI computer possible.", "prompt": "What's the best answer?", "options": ["It drains the battery the motors need", "Big computers are illegal in robots", "Robots need no AI"], "correctIndex": 0, "consequences": ["Thor alone draws up to 130 watts.", "There is no such rule.", "Robots run AI on board."], "explanation": "A robot’s computer and motors share one battery. A bigger brain leaves less for moving."}, "proReasoning": "Explain a limit with one shared resource. Here, the battery.", "commonMistake": "Forgetting that compute uses power.", "mentalModel": "Brains cost battery."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b9a41271bb3b$ml$]::text[]),
($ml$7e81e77b-bc8d-57a8-86b1-7c47cc54ed8d$ml$::uuid, $ml$robotics$ml$, 10, 3, $ml${"id": "robotics-d10-c3", "title": "Thor or Orin", "lessonTitle": "A robot brain for $3,499", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup building a cleaning robot. Nvidia's Thor offers 7.5 times the AI compute of the older Orin, but draws up to 130 watts.", "kicker": "Decide: how much brain does your robot need?", "fullText": "Day 10 showed Nvidia's Jetson AGX Thor, launched in August 2025 as a $3,499 developer kit. Nvidia says it delivers 7.5 times Orin's AI compute, peaking at 2,070 FP4 teraflops.\n\nThe production module costs $2,999 in 1,000-unit orders. Agility and Boston Dynamics were named among its users.\n\nYour robot follows set routes and avoids obstacles. It must run a full night on one charge.", "sources": [{"url": "https://www.theregister.com/2025/08/25/nvidia_touts_jetson_thor_kit/", "label": "The Register, Nvidia touts Jetson Thor kit"}]}, "evidence": {"kind": "faceOff", "prompt": "Which compute fits a simple route-following robot on a tight battery?", "left": {"name": "Just enough compute for the task", "note": "Lower power, longer runtime"}, "right": {"name": "The most compute available", "note": "Up to 130 watts of draw"}, "correctIndex": 0, "explanation": "A simple task does not need peak compute. Saving watts lengthens runtime."}, "numbers": {"kind": "numberSense", "prompt": "Nvidia claims Thor delivers how many times the AI compute of Jetson Orin?", "min": 0, "max": 20, "value": 7.5, "unit": "x", "explanation": "7.5 times. Whether a robot needs that depends on its task."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As the lead engineer, you must recommend a compute module.", "prompt": "What do you weigh most?", "options": ["What competitors announce", "Task needs against battery runtime", "Peak teraflops and nothing else"], "correctIndex": 1, "consequences": ["Rivals may have different tasks.", "The right chip finishes the task and the shift.", "Peak compute can cost hours of runtime."], "explanation": "Onboard compute sets how smart a robot can be within its battery."}, "proReasoning": "Engineers match compute to the task and power budget, not to headlines.", "commonMistake": "Buying peak compute for a simple job.", "mentalModel": "Fit the task."}, "invest": {"call": {"kind": "theCall", "situation": "A cleaning robot startup asks for funding to use Thor.", "prompt": "What do you want to see?", "options": ["A bigger budget for the launch event", "More colors for the robot", "Why the task needs that much compute"], "correctIndex": 2, "consequences": ["Launch spend does not justify hardware.", "Looks do not affect compute needs.", "Extra compute costs money and battery."], "explanation": "Thor costs $2,999 per module and draws up to 130 watts. The task should justify both."}, "proReasoning": "Investors ask whether costly parts earn their place.", "commonMistake": "Funding specs the product does not need.", "mentalModel": "Justify the part.", "sources": [{"url": "https://www.theregister.com/2025/08/25/nvidia_touts_jetson_thor_kit/", "label": "The Register, Nvidia touts Jetson Thor kit"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You expect to add smarter features in two years.", "prompt": "How do you plan compute?", "options": ["Pick for today, leave a path to upgrade", "Buy the biggest chip available now", "Never plan for upgrades"], "correctIndex": 0, "consequences": ["You save power now and can grow later.", "Unused compute drains the battery today.", "Future features need a path."], "explanation": "A path to upgrade avoids paying in watts today for features you do not ship yet."}, "proReasoning": "Founders design for today’s task with room to grow.", "commonMistake": "Paying today for compute you may never use.", "mentalModel": "Room to grow."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks whether every robot should have the most powerful chip.", "prompt": "What's the best answer?", "options": ["No robot needs a chip", "Only as much as the task needs", "Yes, always the most powerful"], "correctIndex": 1, "consequences": ["Robots run AI on board.", "Extra compute costs battery and money.", "Peak power drains runtime."], "explanation": "A simple robot wastes battery on a huge chip. The task should set the brain size."}, "proReasoning": "Explain hardware choices by the job, not by the biggest number.", "commonMistake": "Assuming more power is always better.", "mentalModel": "Right-size the brain."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a5864876f3f9$ml$]::text[]),
($ml$3d93f864-b214-5921-b6f5-4a0c73c966e7$ml$::uuid, $ml$robotics$ml$, 11, 1, $ml${"id": "robotics-d11-c1", "title": "A price floor for magnet metal", "lessonTitle": "The magnet rule with a deadline", "slot": 1, "type": "apply", "brief": {"headline": "In July 2025, the US Defense Department agreed to a 10-year floor of $110 a kilogram for rare earth oxides from MP Materials. It also bought $400 million of new MP stock.", "kicker": "Apply the deadline lesson: what does a guaranteed price change for magnet buyers?", "fullText": "The floor covers NdPr, the neodymium and praseodymium oxide used in rare earth magnets. The Pentagon also agreed that 100% of the magnets from a new MP plant, called 10X, would be bought for ten years.\n\nMP expects total US magnet capacity to reach about 10,000 metric tons once 10X is complete, with commissioning expected in 2028. JPMorgan and Goldman Sachs committed $1 billion of financing.\n\nDay 11 showed why: China processes up to 90% of the world’s rare earths, and its export rules can change faster than any product plan.", "sources": [{"url": "https://investors.mpmaterials.com/investor-news/news-details/2025/MP-Materials-Announces-Transformational-Public-Private-Partnership-with-the-Department-of-Defense-to-Accelerate-U-S--Rare-Earth-Magnet-Independence/default.aspx", "label": "MP Materials, public-private partnership with the Department of Defense, Jul 2025"}, {"url": "https://www.mining-technology.com/news/china-rare-earth-export-pause-nears-expiry-amid-persistent-supply-concentration/", "label": "Mining Technology, China rare earth export pause nears expiry"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What does a price floor do for MP Materials?", "options": ["It guarantees a minimum price for its oxide", "It bans imports of Chinese magnets", "It caps the price that magnet buyers pay"], "correctIndex": 0, "explanation": "A floor guarantees MP at least $110 a kilogram, so a price drop cannot sink the project."}, "numbers": {"kind": "numberSense", "prompt": "What is the NdPr price floor, in dollars per kilogram?", "min": 0, "max": 300, "value": 110, "unit": "$", "explanation": "$110 a kilogram for ten years, backed by the Defense Department."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a US robot maker. You're asked about magnet supply.", "prompt": "Which development should you cite?", "options": ["A US-backed magnet plant with a price floor", "Magnets becoming unnecessary in motors", "China dropping all export rules"], "correctIndex": 0, "consequences": ["MP’s 10X plant is due to start commissioning in 2028.", "Robot joint motors still need magnets.", "China’s April 2025 licenses remain in force."], "explanation": "The Pentagon is backing a US magnet supply with a price floor and guaranteed buyers."}, "proReasoning": "Candidates who know the non-Chinese supply projects show they follow the risk.", "commonMistake": "Talking about magnet risk without knowing any response to it.", "mentalModel": "Know the alternatives."}, "invest": {"call": {"kind": "theCall", "situation": "A friend says the MP deal ends US magnet dependence on China.", "prompt": "How do you answer?", "options": ["No, MP makes no magnets", "It helps, but 10X starts only in 2028", "Yes, starting from today onward"], "correctIndex": 1, "consequences": ["MP plans magnet output at 10X.", "Commissioning of 10X is expected in 2028.", "New plants take years to reach output."], "explanation": "The floor and offtake de-risk the project, but the plant comes years later. China still processes up to 90% today."}, "proReasoning": "Investors separate a funded plan from supply in hand.", "commonMistake": "Treating an announced plant as present capacity.", "mentalModel": "Funded is not flowing.", "sources": [{"url": "https://www.mining-technology.com/news/china-rare-earth-export-pause-nears-expiry-amid-persistent-supply-concentration/", "label": "Mining Technology, China rare earth export pause nears expiry"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You build robot motors in the US.", "prompt": "How should the MP deal shape your plan?", "options": ["Stop managing magnet risk", "Buy only Chinese magnets forever", "Plan a US source for later, hedge now"], "correctIndex": 2, "consequences": ["The plant is not producing at full scale yet.", "Relying on one source keeps the risk.", "US supply arrives later; today’s risk still needs a hedge."], "explanation": "A US source is coming. Until then, stock and second sources still protect production."}, "proReasoning": "Founders plan for future supply without dropping today’s hedge.", "commonMistake": "Assuming a future plant solves today’s shortage.", "mentalModel": "Hedge until it arrives."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a defense agency would set a price for magnet metal.", "prompt": "What's the best answer?", "options": ["To keep a US supplier alive if prices drop", "To make magnets more expensive for buyers", "To stop robots being built"], "correctIndex": 0, "consequences": ["A floor protects the project from price swings.", "The floor is a minimum, not a markup.", "The goal is supply, not fewer robots."], "explanation": "If prices fall, a non-Chinese supplier could fail. A floor keeps it going."}, "proReasoning": "Explain a policy by the risk it removes.", "commonMistake": "Thinking governments only regulate, never buy.", "mentalModel": "A floor keeps supply alive."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a2a1a7b52d32$ml$]::text[]),
($ml$3e052fcc-0af3-564c-b279-1a75c97c6c50$ml$::uuid, $ml$robotics$ml$, 11, 2, $ml${"id": "robotics-d11-c2", "title": "Two prices for the same metal", "lessonTitle": "The magnet rule with a deadline", "slot": 2, "type": "connect", "brief": {"headline": "In August 2026, dysprosium oxide cost about $270 to $330 a kilo in China, but $1,250 to $1,675 in Rotterdam. China requires licenses for it.", "kicker": "Connect day 11 and day 9: the licensed metals, and what they cost outside China.", "fullText": "Day 9 showed that China makes about 92% of the world’s rare earth magnets and began requiring export licenses in April 2025.\n\nDay 11 showed the cost of that control. Dysprosium and terbium, added to magnets that work in hot motors, are on the licensed list. Outside China, dysprosium oxide cost several times the Chinese price.\n\nChina paused its wider October 2025 controls until November 10, 2026. The April 2025 licenses on seven elements stayed in force regardless.", "sources": [{"url": "https://thehumanoidgroup.com/news/article/china-rare-earth-export-pause-nears-expiry", "label": "The Humanoid Group, China's rare earth export pause nears expiry"}, {"url": "https://www.fortune.com/article/elon-musk-tesla-optimus-robots-china-rare-earths", "label": "Fortune, Musk says China's rare earth curbs hit Optimus"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each rule still in force, or paused until November 10, 2026?", "buckets": ["Still in force", "Paused"], "items": [{"text": "April 2025 licenses on seven rare earths", "bucket": 0}, {"text": "Licenses on dysprosium and terbium", "bucket": 0}, {"text": "The wider October 2025 controls", "bucket": 1}, {"text": "Licenses on foreign products with Chinese rare earths", "bucket": 1}], "explanation": "The April 2025 licenses stayed. The October 2025 expansion, including rules on foreign products, was paused."}, "numbers": {"kind": "numberSense", "prompt": "Rotterdam dysprosium oxide cost roughly how many times the Chinese price?", "min": 0, "max": 12, "value": 5, "unit": "x", "explanation": "About $1,460 against $300 at the midpoints, roughly five times."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A robot maker asks you to explain magnet costs to the finance team.", "prompt": "Which point matters most?", "options": ["Licenses lower prices abroad", "Outside China, the metal costs several times more", "Prices are the same everywhere in the world"], "correctIndex": 1, "consequences": ["Licenses tighten supply outside China.", "$1,250 to $1,675 in Rotterdam against $270 to $330 in China.", "The gap is several times."], "explanation": "Licensed supply split the market. Buyers outside China paid several times more for the same oxide."}, "proReasoning": "Candidates who explain a cost gap with its cause show business sense.", "commonMistake": "Assuming one world price for every metal.", "mentalModel": "Same metal, two prices."}, "invest": {"call": {"kind": "theCall", "situation": "A robot maker sources magnets outside China at Rotterdam prices.", "prompt": "What should you check?", "options": ["Whether its Rotterdam office is well located", "How many magnets look alike", "How its costs compare with Chinese rivals"], "correctIndex": 2, "consequences": ["Location charm is irrelevant.", "The cost gap is the issue.", "Rivals buying in China may pay a fraction for the metal."], "explanation": "Chinese rivals may pay a fraction of the price for dysprosium. That gap can show up in margins."}, "proReasoning": "Investors compare input costs across rivals, not just within one company.", "commonMistake": "Ignoring input cost gaps between competitors.", "mentalModel": "Compare input costs.", "sources": [{"url": "https://thehumanoidgroup.com/news/article/china-rare-earth-export-pause-nears-expiry", "label": "The Humanoid Group, China's rare earth export pause nears expiry"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan next year’s motor costs.", "prompt": "How should you budget for dysprosium?", "options": ["Model both the China and Rotterdam prices", "Use the cheapest price you have seen", "Ignore magnet metal costs"], "correctIndex": 0, "consequences": ["Two scenarios cover a license squeeze.", "The cheapest price may not be available to you.", "They differ by several times."], "explanation": "Dysprosium cost several times more outside China. Price both scenarios."}, "proReasoning": "Founders budget for the price they might really pay, not the best case.", "commonMistake": "Budgeting on a price you may not get.", "mentalModel": "Price two scenarios."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how the same metal can cost five times more in one place.", "prompt": "What's the best answer?", "options": ["Shipping costs explain it all", "Export licenses limit what leaves China", "Rotterdam metal is a different element"], "correctIndex": 1, "consequences": ["The gap is far larger than shipping.", "Tight supply abroad pushes prices up.", "It is the same oxide."], "explanation": "China licenses exports, so less reaches buyers abroad and they pay more."}, "proReasoning": "Explain a price gap by who controls supply.", "commonMistake": "Assuming markets always even out prices.", "mentalModel": "Control splits prices."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d884888f3d2a$ml$]::text[]),
($ml$1d5c1b4e-e745-5931-b1d4-556f10243cee$ml$::uuid, $ml$robotics$ml$, 11, 3, $ml${"id": "robotics-d11-c3", "title": "November 10 is on the calendar", "lessonTitle": "The magnet rule with a deadline", "slot": 3, "type": "decide", "brief": {"headline": "You run a robot maker that needs magnets. China's pause on its wider export controls ends November 10, 2026, and no extension has been confirmed.", "kicker": "Decide: how do you prepare for the deadline?", "fullText": "Day 11 showed the deadline. China paused its expanded October 2025 controls for one year, until November 10, 2026. If the pause lapses, one rule could require licenses for foreign-made products containing Chinese rare earths.\n\nChina processes up to 90% of the world’s rare earths, according to GlobalData. As of October 2026, no extension had been confirmed.\n\nYour next production run starts in January.", "sources": [{"url": "https://thehumanoidgroup.com/news/article/china-rare-earth-export-pause-nears-expiry", "label": "The Humanoid Group, China's rare earth export pause nears expiry"}, {"url": "https://www.mining-technology.com/news/china-rare-earth-export-pause-nears-expiry-amid-persistent-supply-concentration/", "label": "Mining Technology, China rare earth export pause nears expiry"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan protects a January production run?", "left": {"name": "Secure stock and a second source now", "note": "Ready for either outcome"}, "right": {"name": "Wait and see what China decides", "note": "Act only after the date passes"}, "correctIndex": 0, "explanation": "Rules can move faster than product plans. Stock and a second source protect the run either way."}, "numbers": {"kind": "numberSense", "prompt": "China processes up to what percent of the world’s rare earths, per GlobalData?", "min": 0, "max": 100, "value": 90, "unit": "%", "explanation": "Up to 90%. Few alternatives can fill a gap quickly."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As the maker's supply planner, you present options.", "prompt": "What do you recommend?", "options": ["Do nothing at all until November 11", "Cancel the January run", "Build stock and qualify a second source"], "correctIndex": 2, "consequences": ["By then it may be too late to act.", "Cancelling gives up revenue you can protect.", "It covers a lapse without stopping the plan."], "explanation": "Export rules on magnets can move faster than any product plan. Prepare before the date."}, "proReasoning": "Planners act before a known deadline, not after it.", "commonMistake": "Treating a dated risk as a surprise.", "mentalModel": "Act before the date."}, "invest": {"call": {"kind": "theCall", "situation": "A robot maker's guidance ignores the November 10 date.", "prompt": "What concern do you raise?", "options": ["Magnet costs could jump if the pause lapses", "The date has no link to robots at all", "Magnets will get cheaper"], "correctIndex": 0, "consequences": ["A lapse could extend licenses to foreign products.", "Robot motors use these magnets.", "Tighter rules usually raise costs."], "explanation": "November 10, 2026 can change magnet costs for every robot maker. Guidance should say how it is hedged."}, "proReasoning": "Investors ask how a company handles a known, dated risk.", "commonMistake": "Ignoring a deadline because it might pass quietly.", "mentalModel": "Ask about the deadline.", "sources": [{"url": "https://thehumanoidgroup.com/news/article/china-rare-earth-export-pause-nears-expiry", "label": "The Humanoid Group, China's rare earth export pause nears expiry"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your cash is tight. Stocking magnets ties up money.", "prompt": "What's a sensible middle path?", "options": ["Stock five years of magnets", "Stock enough to cover the next run", "Stock nothing at all and wait"], "correctIndex": 1, "consequences": ["Far more cash than the risk needs.", "It protects the January run without draining cash.", "You face the deadline unprotected."], "explanation": "You do not need years of stock, just enough to keep the next run alive if rules tighten."}, "proReasoning": "Founders size a hedge to the risk window, not to their fears.", "commonMistake": "Choosing between no hedge and an extreme one.", "mentalModel": "Hedge the window."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a date in November matters to robot makers.", "prompt": "What's the best answer?", "options": ["It is a robot industry holiday each year", "Robots stop working that day", "Magnet export rules could tighten then"], "correctIndex": 2, "consequences": ["There is no such holiday.", "Existing robots keep running.", "The pause on wider controls ends November 10, 2026."], "explanation": "The pause on China’s wider magnet rules ends that day. If it lapses, getting magnets gets harder."}, "proReasoning": "Explain a date by the rule that changes on it.", "commonMistake": "Thinking policy dates do not touch products.", "mentalModel": "Dates move supply."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a4bdde255960$ml$]::text[]),
($ml$d8b06223-f23b-5341-bf75-3088131c4735$ml$::uuid, $ml$robotics$ml$, 12, 1, $ml${"id": "robotics-d12-c1", "title": "Unitree's books, opened", "lessonTitle": "A humanoid for under $6,000", "slot": 1, "type": "apply", "brief": {"headline": "In March 2026, Unitree filed to raise 4.2 billion yuan in a Shanghai IPO. Humanoids made 51.5% of its revenue in the first nine months of 2025, with a 62.9% gross margin.", "kicker": "Apply the cheap humanoid lesson: can low prices still make money?", "fullText": "Unitree sells humanoids for far less than rivals. Its R1 launched at about $5,900, and its G1 at $16,000.\n\nIts filing showed revenue of 1.2 billion yuan and net income of 105 million yuan in the first nine months of 2025. Its overall gross margin rose to 59.5%, from 44.2% in 2022. Humanoids were 1.9% of revenue in 2023.\n\nLow prices did not mean low margins. The open question is what buyers do with the robots.", "sources": [{"url": "https://www.caixinglobal.com/2026-03-21/unitree-robotics-files-for-608-million-star-market-ipo-102425491.html", "label": "Caixin Global, Unitree Robotics files for $608 million STAR Market IPO, Mar 2026"}, {"url": "https://www.thestar.com.my/business/business-news/2025/07/28/unitree-offers-a-humanoid-robot-for-under-us6000", "label": "The Star, Unitree offers a humanoid robot for under US$6,000"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Humanoids made about half of Unitree’s revenue.", "Unitree lost money on its cheap humanoids.", "Unitree filed for a Shanghai IPO."], "fakeIndex": 1, "explanation": "Its humanoids carried a 62.9% gross margin. Cheap prices still left room for profit."}, "numbers": {"kind": "numberSense", "prompt": "What was Unitree's gross margin on humanoid robots in the first nine months of 2025?", "min": 0, "max": 100, "value": 62.9, "unit": "%", "explanation": "62.9%, higher than the company average of 59.5%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a Western humanoid startup. You're asked about Unitree.", "prompt": "Which point shows you read its filing?", "options": ["Unitree sells only robot dogs", "Cheap humanoids at a high gross margin", "Unitree loses money on every robot"], "correctIndex": 1, "consequences": ["Humanoids made 51.5% of revenue.", "62.9% gross margin on humanoids, at low prices.", "It earned 105 million yuan in nine months."], "explanation": "Unitree sells low-priced humanoids and still earns high margins. That is the rival to beat."}, "proReasoning": "Candidates who know a rival’s numbers sound like insiders.", "commonMistake": "Assuming cheap rivals cannot be profitable.", "mentalModel": "Cheap and profitable."}, "invest": {"call": {"kind": "theCall", "situation": "Unitree priced its IPO with humanoids now half its revenue.", "prompt": "What should you still question?", "options": ["Whether it sells any humanoids at all", "Whether margins exist", "What useful work buyers get from them"], "correctIndex": 2, "consequences": ["Humanoids made 51.5% of revenue.", "Humanoid gross margin was 62.9%.", "Usefulness, not price, is now the bottleneck."], "explanation": "Unitree proves cheap humanoids can be profitable. Whether they do lasting work decides demand."}, "proReasoning": "Investors look past margins to the demand that sustains them.", "commonMistake": "Mistaking strong margins for proven usefulness.", "mentalModel": "Margins need demand.", "sources": [{"url": "https://www.thestar.com.my/business/business-news/2025/07/28/unitree-offers-a-humanoid-robot-for-under-us6000", "label": "The Star, Unitree offers a humanoid robot for under US$6,000"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan a humanoid priced at $30,000. Unitree sells for far less.", "prompt": "How can you compete?", "options": ["Offer useful work Unitree robots cannot do", "Match Unitree on price alone, unit for unit", "Ignore Unitree entirely"], "correctIndex": 0, "consequences": ["Usefulness justifies a higher price.", "Unitree already earns 62.9% margins at its prices.", "Its humanoid sales are now half its revenue."], "explanation": "Unitree wins on price and still profits. A pricier robot must win on what it can do."}, "proReasoning": "Founders facing a low-cost leader compete on value, not price.", "commonMistake": "Starting a price war with a profitable low-cost rival.", "mentalModel": "Win on work, not price."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks a $5,900 humanoid must be sold at a loss.", "prompt": "What's a fair reply?", "options": ["Humanoids are given away free", "Unitree earns high margins on humanoids", "Yes, every unit sold loses them money"], "correctIndex": 1, "consequences": ["They are sold, at low prices.", "Its humanoid gross margin was 62.9%.", "Unitree was profitable in 2024 and 2025."], "explanation": "Unitree’s filing shows a 62.9% gross margin on humanoids. Low price and profit can go together."}, "proReasoning": "One filed number can overturn a guess.", "commonMistake": "Equating low price with losses.", "mentalModel": "Cheap can still pay."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5ddbe642f60f$ml$]::text[]),
($ml$d31ed3a0-08b7-5e64-8643-af33b3a1ff65$ml$::uuid, $ml$robotics$ml$, 12, 2, $ml${"id": "robotics-d12-c2", "title": "From $90,000 to $5,900", "lessonTitle": "A humanoid for under $6,000", "slot": 2, "type": "connect", "brief": {"headline": "Unitree priced its H1 humanoid above $90,000 and its R1 at about $5,900 in July 2025. Figure was valued at $39 billion two months later.", "kicker": "Connect day 12 and day 6: falling humanoid prices, and rising humanoid valuations.", "fullText": "Day 6 showed Figure raising over $1 billion at a $39 billion valuation, with plans for 100,000 humanoids in four years.\n\nDay 12 showed prices falling fast. Unitree’s H1 sold for over $90,000, its G1 for $16,000, and its R1 for about $5,900, with 26 joints and a weight of about 25 kilograms. Morgan Stanley put the most sophisticated humanoids at about $200,000 in 2024.\n\nHigh valuations assume robots that do useful work. Low prices show that the body itself is getting cheap.", "sources": [{"url": "https://www.thestar.com.my/business/business-news/2025/07/28/unitree-offers-a-humanoid-robot-for-under-us6000", "label": "The Star, Unitree offers a humanoid robot for under US$6,000"}, {"url": "https://www.therobotreport.com/figure-ai-raises-1b-in-series-c-funding-toward-humanoid-robot-development/", "label": "The Robot Report, Figure AI raises $1B in Series C funding"}]}, "evidence": {"kind": "faceOff", "prompt": "Which is now the harder problem for humanoids?", "left": {"name": "Making the robot cheap", "note": "Prices fell from $90,000 to $5,900"}, "right": {"name": "Making the robot useful", "note": "Software, strength and reliability"}, "correctIndex": 1, "explanation": "Prices are falling fast. Useful, reliable work is now the bottleneck."}, "numbers": {"kind": "numberSense", "prompt": "Unitree's H1 cost over $90,000 and its R1 about $5,900. Roughly how many times cheaper is the R1?", "min": 0, "max": 40, "value": 15, "unit": "x", "explanation": "About 15 times cheaper in a few years. The body is no longer the hard part."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A humanoid maker asks what skills will matter most as prices fall.", "prompt": "Which answer connects the lessons?", "options": ["Making robots look more and more human", "Raising bigger rounds", "Making robots do reliable, useful work"], "correctIndex": 2, "consequences": ["Looks do not create value for buyers.", "Funding does not make robots useful.", "Usefulness is now the bottleneck, not price."], "explanation": "Cheap bodies are arriving. The value moves to software, strength and reliability."}, "proReasoning": "Candidates who see where the bottleneck moved show judgment.", "commonMistake": "Focusing on the problem the market has already solved.", "mentalModel": "Follow the bottleneck."}, "invest": {"call": {"kind": "theCall", "situation": "A humanoid maker's pitch leans on its low price.", "prompt": "What should you ask?", "options": ["What paid work can it do reliably?", "Can it get even cheaper?", "How many joints does it have?"], "correctIndex": 0, "consequences": ["Usefulness is what sustains demand.", "Rivals already sell below $6,000.", "Joints alone do not make a robot useful."], "explanation": "Prices are falling for everyone. A valuation needs robots that do useful work."}, "proReasoning": "Investors look for the scarce thing. In humanoids, it is usefulness.", "commonMistake": "Valuing a humanoid maker on price alone.", "mentalModel": "Price is not the moat.", "sources": [{"url": "https://www.therobotreport.com/figure-ai-raises-1b-in-series-c-funding-toward-humanoid-robot-development/", "label": "The Robot Report, Figure AI raises $1B in Series C funding"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your humanoid startup can cut its price or improve one useful skill.", "prompt": "Which should come first?", "options": ["Add more joints for show", "Improve the useful skill", "Cut the price further"], "correctIndex": 1, "consequences": ["Joints without useful tasks add cost.", "Usefulness is the bottleneck buyers face.", "Rivals already sell under $6,000."], "explanation": "Price wars are coming from cheap makers. A robot that reliably does one useful job stands apart."}, "proReasoning": "Founders invest in what buyers cannot get cheaply elsewhere.", "commonMistake": "Competing on price against the cheapest makers.", "mentalModel": "Be useful, not cheapest."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why humanoid valuations are so high if robots are getting cheap.", "prompt": "What's the best answer?", "options": ["Cheap robots raise valuations automatically", "Valuations track the robot price", "Investors bet on useful work, not the body"], "correctIndex": 2, "consequences": ["Low prices alone do not create value.", "Valuations follow expected earnings, not unit price.", "Figure’s value assumes robots doing real jobs."], "explanation": "The body is getting cheap. Investors pay for the hope of robots that do useful work."}, "proReasoning": "Explain two trends together: cheaper bodies and bets on usefulness.", "commonMistake": "Thinking cheaper robots should mean lower valuations.", "mentalModel": "Bet on usefulness."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5ad0d78f27a2$ml$]::text[]),
($ml$aee4964c-56fd-5241-a35d-c578615d9278$ml$::uuid, $ml$robotics$ml$, 12, 3, $ml${"id": "robotics-d12-c3", "title": "Buy humanoids for the lab", "lessonTitle": "A humanoid for under $6,000", "slot": 3, "type": "decide", "brief": {"headline": "You run a university lab with a $50,000 budget. You could buy one high-end humanoid or several Unitree robots priced from about $5,900.", "kicker": "Decide: what do you buy?", "fullText": "Day 12 showed Unitree's R1 at 39,900 yuan, about $5,900, with 26 joints and a weight of about 25 kilograms. Its G1 sold for $16,000 and its H1 for over $90,000.\n\nMorgan Stanley put the most sophisticated humanoids at about $200,000 in 2024.\n\nYour students research walking and grasping. They need robots to practice on and will break some along the way.", "sources": [{"url": "https://www.thestar.com.my/business/business-news/2025/07/28/unitree-offers-a-humanoid-robot-for-under-us6000", "label": "The Star, Unitree offers a humanoid robot for under US$6,000"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did Morgan Stanley put the most advanced humanoids at in 2024?", "options": ["About $20,000", "About $200,000", "About $2 million"], "correctIndex": 1, "explanation": "About $200,000. A lab budget buys far more cheap robots than top-end ones."}, "numbers": {"kind": "numberSense", "prompt": "How many R1 humanoids at about $5,900 could a $50,000 budget buy, roughly?", "min": 0, "max": 15, "value": 8, "unit": "", "explanation": "About eight, before shipping and taxes. Enough for several teams at once."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As the lab's research engineer, you advise the professor.", "prompt": "What do you recommend?", "options": ["Several cheap robots students can share", "One top robot that nobody may touch", "No robots, only simulation"], "correctIndex": 0, "consequences": ["More robots mean more hands-on research.", "One costly robot limits practice and risks big losses.", "Walking research needs real robots too."], "explanation": "A sub-$6,000 robot opens research and hobby buyers. Several units let more students experiment."}, "proReasoning": "Engineers match the tool to how it will be used. Students need robots to break and learn on.", "commonMistake": "Buying prestige over usable research time.", "mentalModel": "Many robots, more learning."}, "invest": {"call": {"kind": "theCall", "situation": "A friend asks whether research labs are a real market for humanoids.", "prompt": "How do you answer?", "options": ["Only factories buy humanoids", "Cheap robots make labs an early market", "Labs never buy robots for research"], "correctIndex": 1, "consequences": ["Research and hobby buyers are early buyers.", "A sub-$6,000 price fits research budgets.", "Labs buy robots to study them."], "explanation": "Low prices open research and hobby buyers. They can be an early market before factories commit."}, "proReasoning": "Investors look for the first buyers who will pay today.", "commonMistake": "Ignoring early buyers who are not the final market.", "mentalModel": "Labs buy first.", "sources": [{"url": "https://www.thestar.com.my/business/business-news/2025/07/28/unitree-offers-a-humanoid-robot-for-under-us6000", "label": "The Star, Unitree offers a humanoid robot for under US$6,000"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You build humanoid software and want first users.", "prompt": "Who should you target?", "options": ["Only large car factories with big budgets", "People with no robots", "Labs and tinkerers buying cheap robots"], "correctIndex": 2, "consequences": ["Factories move slowly and want proven tools.", "Without a robot, they cannot use your software.", "They own robots now and need software."], "explanation": "Cheap robots put humanoids in many labs. Those owners need software today."}, "proReasoning": "Founders sell to people who already own the hardware.", "commonMistake": "Targeting buyers who have not bought robots yet.", "mentalModel": "Sell to owners."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a humanoid can cost less than many used cars.", "prompt": "What's the best answer?", "options": ["Makers cut costs, and prices fell fast", "It has no real motors or joints inside", "It is only a toy statue"], "correctIndex": 0, "consequences": ["Unitree went from over $90,000 to about $5,900.", "The R1 has 26 joints that move.", "It walks and moves."], "explanation": "Design for cost drove prices down quickly. Usefulness, not price, is now the limit."}, "proReasoning": "Use a familiar comparison to explain a fast price drop.", "commonMistake": "Assuming a cheap robot must be fake.", "mentalModel": "Cheap but real."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:db1d5fba8dbb$ml$]::text[]),
($ml$87a1317f-472d-58a0-9843-5e4126930d2b$ml$::uuid, $ml$robotics$ml$, 13, 1, $ml${"id": "robotics-d13-c1", "title": "Kilted Kaiju and its end date", "lessonTitle": "The free software robots share", "slot": 1, "type": "apply", "brief": {"headline": "In May 2025, Open Robotics released ROS 2 Kilted Kaiju, the eleventh ROS 2 release. It is a standard release, supported only until November 2026.", "kicker": "Apply the shared layer idea: what does a release date mean for teams building on it?", "fullText": "Kilted runs mainly on Ubuntu 24.04 and Windows. It is the first ROS release to support the Eclipse Zenoh middleware at the top tier, and public beta testing ran nearly 550 test cases.\n\nA standard release gets roughly 18 months of support. Teams that build products on it must move to a newer release when support ends.\n\nDay 13 showed why this matters: ROS 2 made up 91.2% of ROS downloads in 2025. Most teams now build on this shared layer.", "sources": [{"url": "https://www.openrobotics.org/blog/2025/5/23/ros-2-kilted-kaiju-released", "label": "Open Robotics, ROS 2 Kilted Kaiju released, May 2025"}, {"url": "https://discourse.openrobotics.org/t/2025-ros-metrics-report/52575", "label": "Open Robotics Discourse, 2025 ROS metrics report"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Until when is ROS 2 Kilted Kaiju supported?", "options": ["May 2025", "November 2026", "Forever, at no cost"], "correctIndex": 1, "explanation": "Kilted is a standard release, supported until November 2026."}, "numbers": {"kind": "numberSense", "prompt": "Kilted came out in May 2025 with support to November 2026. About how many months is that?", "min": 0, "max": 60, "value": 18, "unit": "", "explanation": "About 18 months. Products often run far longer than that."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a robot startup that runs ROS 2.", "prompt": "Which question shows you think ahead?", "options": ["Is ROS an operating system like Linux?", "Do you use any free software?", "Which ROS 2 release do you ship on, and why?"], "correctIndex": 2, "consequences": ["ROS is a set of tools, not an operating system.", "Almost every team does.", "Releases have end dates that shape upgrades."], "explanation": "Each ROS 2 release has an end of support. Knowing which one a team ships on shows foresight."}, "proReasoning": "Candidates who ask about support windows understand real product work.", "commonMistake": "Treating the shared software layer as timeless.", "mentalModel": "Every release has an end."}, "invest": {"call": {"kind": "theCall", "situation": "A robot maker ships its product on Kilted Kaiju.", "prompt": "What cost should you expect?", "options": ["An upgrade when support ends in 2026", "No software costs of any kind, ever", "Paying to license ROS"], "correctIndex": 0, "consequences": ["Support ends in November 2026.", "Free code still needs upgrading work.", "ROS is free and open source."], "explanation": "Free software has no license fee, but upgrades cost engineering time when support ends."}, "proReasoning": "Investors look for the hidden costs of free tools.", "commonMistake": "Assuming free software has no costs.", "mentalModel": "Free has upkeep.", "sources": [{"url": "https://www.openrobotics.org/blog/2025/5/23/ros-2-kilted-kaiju-released", "label": "Open Robotics, ROS 2 Kilted Kaiju released, May 2025"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You start a new robot product today.", "prompt": "How do you pick a ROS 2 release?", "options": ["Skip ROS and write everything", "Choose one with support past your launch", "Pick the oldest release you can find"], "correctIndex": 1, "consequences": ["ROS 2 is the shared layer most teams use.", "You avoid an upgrade right after shipping.", "Old releases may lose support soon."], "explanation": "Kilted ends in November 2026. Match the release to how long your product must be supported."}, "proReasoning": "Founders pick shared software with their product’s lifetime in mind.", "commonMistake": "Choosing a release without checking its end date.", "mentalModel": "Match support to lifetime."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why free robot software would ever stop being supported.", "prompt": "What's the best answer?", "options": ["Free software becomes illegal after a year", "It never stops", "Maintainers support each release for a set time"], "correctIndex": 2, "consequences": ["There is no such law.", "Standard releases have end dates.", "Kilted is supported until November 2026."], "explanation": "Volunteers and maintainers support each release for a window, then move to newer ones."}, "proReasoning": "Explain software support as a time window, not a permanent promise.", "commonMistake": "Thinking free means forever.", "mentalModel": "Support has a window."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:eee836683a60$ml$]::text[]),
($ml$0e1050b3-0e45-5fd7-b90d-dba28c478865$ml$::uuid, $ml$robotics$ml$, 13, 2, $ml${"id": "robotics-d13-c2", "title": "Free code, paid products", "lessonTitle": "The free software robots share", "slot": 2, "type": "connect", "brief": {"headline": "ROS 2 made up 91.2% of ROS downloads in 2025, and ROS costs nothing. Intuitive earned about 75% of its 2025 revenue after the robot was sold.", "kicker": "Connect day 13 and day 2: free shared software, and where robot money comes from.", "fullText": "Day 2 showed that robot companies often earn after the sale, from parts, software and service. Intuitive made about 75% of its 2025 revenue that way.\n\nDay 13 showed the shared layer underneath many robots. ROS is free, open-source software, and ROS 2 now makes up 91.2% of downloads. Teams reuse its packages instead of starting from zero.\n\nIf the base layer is free for everyone, companies must earn on what they build on top of it.", "sources": [{"url": "https://discourse.openrobotics.org/t/2025-ros-metrics-report/52575", "label": "Open Robotics Discourse, 2025 ROS metrics report"}, {"url": "https://www.nasdaq.com/press-release/intuitive-announces-fourth-quarter-earnings-2026-01-22", "label": "Intuitive, Q4 2025 earnings"}]}, "evidence": {"kind": "faceOff", "prompt": "Where can a robot company earn money when ROS is free?", "left": {"name": "Products and service built on top", "note": "Hardware, apps, support, upkeep"}, "right": {"name": "Selling ROS licenses", "note": "Charging for the free code"}, "correctIndex": 0, "explanation": "ROS is free. Money comes from the products, services and support built around it."}, "numbers": {"kind": "numberSense", "prompt": "What share of ROS downloads went to ROS 2 in 2025?", "min": 0, "max": 100, "value": 91.2, "unit": "%", "explanation": "91.2%. The newer generation has taken over."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A robot software company asks how it should make money.", "prompt": "Which answer connects the lessons?", "options": ["Sell what runs on top of ROS", "Sell ROS licenses", "Give everything away forever"], "correctIndex": 0, "consequences": ["Products and services can earn after the sale.", "ROS itself is free to use.", "A company still needs revenue."], "explanation": "The shared layer is free. Like Intuitive’s instruments, the earnings come from what follows."}, "proReasoning": "Candidates who link open source to a business model show commercial sense.", "commonMistake": "Thinking open source and business cannot mix.", "mentalModel": "Earn on top."}, "invest": {"call": {"kind": "theCall", "situation": "A startup says its edge is that it uses ROS 2.", "prompt": "Why is that weak on its own?", "options": ["ROS 2 costs too much", "Rivals use the same free code", "ROS 2 is too new to use"], "correctIndex": 1, "consequences": ["ROS 2 is free.", "91.2% of downloads were ROS 2; everyone can use it.", "ROS 2 is the mainstream now."], "explanation": "Free shared code lowers entry for everyone. The edge must be built on top of it."}, "proReasoning": "Investors look for what a company owns that others cannot copy.", "commonMistake": "Counting a free, shared tool as an advantage.", "mentalModel": "Shared is not an edge.", "sources": [{"url": "https://discourse.openrobotics.org/t/2025-ros-metrics-report/52575", "label": "Open Robotics Discourse, 2025 ROS metrics report"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You build a robot product on ROS 2.", "prompt": "Where should your revenue come from?", "options": ["Charging customers for ROS itself", "Hoping users donate", "Features, support and service you add"], "correctIndex": 2, "consequences": ["ROS is free; customers will not pay for it.", "Donations rarely fund a company.", "That is what customers cannot get for free."], "explanation": "Build on the free layer and earn on what you add, as robot makers earn after the sale."}, "proReasoning": "Founders use free code to move fast, then charge for their own work.", "commonMistake": "Planning to sell what is already free.", "mentalModel": "Charge for what you add."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how companies make money if robot software is free.", "prompt": "What's the best answer?", "options": ["They sell products and service on top", "They secretly charge users for the code", "They cannot make money"], "correctIndex": 0, "consequences": ["Revenue comes from what is built around the code.", "ROS is free and open source.", "Many robot companies earn after the sale."], "explanation": "The base software is free. Companies earn on robots, apps and support built on it."}, "proReasoning": "Explain open source by where the money flows instead.", "commonMistake": "Thinking free code means no business.", "mentalModel": "The money is on top."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0d9339bb5728$ml$]::text[]),
($ml$469acebd-8103-5e86-bdbb-d7173d454d11$ml$::uuid, $ml$robotics$ml$, 13, 3, $ml${"id": "robotics-d13-c3", "title": "ROS 1 or ROS 2 for a new robot", "lessonTitle": "The free software robots share", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup about to write software for a new warehouse robot. One engineer knows the original ROS well; the rest of the field moved to ROS 2.", "kicker": "Decide: which version do you build on?", "fullText": "Day 13 showed ROS, the Robot Operating System. Despite the name, it is a set of free robot software tools, organized in packages that each handle one job, such as mapping or motion.\n\nROS grew out of the lab Willow Garage. The Open Source Robotics Foundation formed in 2012 to steward it. ROS 2 made up 91.2% of package downloads in 2025, and the original ROS is fading out.\n\nYour senior engineer would be faster on ROS 1 for the first few months.", "sources": [{"url": "https://discourse.openrobotics.org/t/2025-ros-metrics-report/52575", "label": "Open Robotics Discourse, 2025 ROS metrics report"}, {"url": "https://techcrunch.com/2022/12/15/alphabets-intrinsic-acquires-darpa-backed-firm-behind-open-source-robotics-software/", "label": "TechCrunch, Alphabet's Intrinsic acquires firm behind open source robotics software"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["ROS 2 made up most ROS downloads in 2025.", "ROS is a full operating system like Linux.", "ROS code comes in reusable packages."], "fakeIndex": 1, "explanation": "ROS is not an operating system. It is a set of free robot software tools."}, "numbers": {"kind": "numberSense", "prompt": "The Open Source Robotics Foundation formed in 2012. How many years before 2025 was that?", "min": 0, "max": 30, "value": 13, "unit": "", "explanation": "Thirteen years. ROS has had a long life, and its newer generation now leads."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As the startup's software lead, you decide the stack.", "prompt": "What do you choose?", "options": ["No ROS, write all from scratch", "ROS 2, where the field moved", "ROS 1, for a faster start"], "correctIndex": 1, "consequences": ["Rewriting free tools wastes years.", "New products should build where support and users are.", "A quick start now means a costly move later."], "explanation": "With ROS 2 at 91.2% of downloads, new products should not start on the old version."}, "proReasoning": "Leads choose the platform the product will live on for years, not the fastest first month.", "commonMistake": "Optimizing for the first sprint over the product’s lifetime.", "mentalModel": "Start where the field is."}, "invest": {"call": {"kind": "theCall", "situation": "A startup pitches a new robot built on the original ROS.", "prompt": "What concern do you raise?", "options": ["It uses too much free code", "ROS 1 costs too much", "It starts on a fading version"], "correctIndex": 2, "consequences": ["Reusing free code is normal.", "ROS is free in every version.", "The field moved to ROS 2; migration will be needed."], "explanation": "Building new on the old version locks in a migration cost later."}, "proReasoning": "Investors spot technical debt baked in from day one.", "commonMistake": "Ignoring which version a product is built on.", "mentalModel": "Check the foundation.", "sources": [{"url": "https://discourse.openrobotics.org/t/2025-ros-metrics-report/52575", "label": "Open Robotics Discourse, 2025 ROS metrics report"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your senior engineer prefers ROS 1.", "prompt": "How do you handle it?", "options": ["Build on ROS 2 and help him adapt", "Let him choose ROS 1 anyway", "Split the code across both"], "correctIndex": 0, "consequences": ["It avoids a forced migration later.", "One person’s comfort sets the whole product’s future.", "Two stacks double the upkeep."], "explanation": "The original ROS is fading. A short learning curve now beats a migration later."}, "proReasoning": "Founders weigh one person’s speed against the product’s future.", "commonMistake": "Letting habit pick the platform.", "mentalModel": "Learn now, not later."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why robot builders all moved to a newer version of free software.", "prompt": "What's the best answer?", "options": ["Nobody uses either", "Support and users moved to the newer one", "The old version was banned by law last year"], "correctIndex": 1, "consequences": ["Hundreds of thousands use ROS.", "ROS 2 made up 91.2% of downloads.", "No ban; the community moved on."], "explanation": "Shared software moves as a group. Once most users switch, support follows them."}, "proReasoning": "Explain a shift by where the users went.", "commonMistake": "Thinking the old version stays equal forever.", "mentalModel": "Users pull support."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8e69f908f6d5$ml$]::text[]),
($ml$e6004ce4-71af-5980-baba-d55a2238d77e$ml$::uuid, $ml$robotics$ml$, 14, 1, $ml${"id": "robotics-d14-c1", "title": "Intrinsic moves into Foxconn plants", "lessonTitle": "Alphabet buys the ROS team", "slot": 1, "type": "apply", "brief": {"headline": "In November 2025, Alphabet's Intrinsic and Foxconn formed a joint venture to deploy robots in Foxconn's US factories. Intrinsic's CEO said it is not a pilot.", "kicker": "Apply the money flow lesson: where does a robot software company earn?", "fullText": "Intrinsic graduated from Alphabet’s moonshot program and became a separate company in 2021. It works on flexible manufacturing: automated systems that respond to new data and adapt.\n\nThe companies had been in talks for a year or two. Neither said how much it is contributing. In late October, Foxconn had announced robots at its new Houston plant, which builds Nvidia server racks.\n\nIn 2022, Intrinsic bought the company behind ROS, the free robot software. Now it is putting its own software to work in a giant’s factories.", "sources": [{"url": "https://fortune.com/2025/11/20/alphabet-intrinsic-foxconn-intelligent-robots-ai-joint-venture/", "label": "Fortune, Alphabet's Intrinsic and Foxconn form a robotics joint venture, Nov 2025"}, {"url": "https://techcrunch.com/2022/12/15/alphabets-intrinsic-acquires-darpa-backed-firm-behind-open-source-robotics-software/", "label": "TechCrunch, Alphabet's Intrinsic acquires firm behind open source robotics software"}]}, "evidence": {"kind": "buildChain", "prompt": "Put Intrinsic's path in order.", "steps": ["Starts inside Alphabet’s moonshot program", "Becomes a separate company in 2021", "Buys the for-profit side of Open Robotics in 2022", "Forms a joint venture with Foxconn in 2025", "Deploys robots in Foxconn’s US factories"], "explanation": "Intrinsic moved from research to owning ROS talent to running robots in real factories."}, "numbers": {"kind": "numberSense", "prompt": "The ROS foundation began in 2012, and Intrinsic bought its for-profit arm in 2022. How many years apart is that?", "min": 0, "max": 16, "value": 10, "unit": "", "explanation": "Ten years. Free code grew a community that a giant later paid to hire."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Intrinsic after the Foxconn deal.", "prompt": "Which point shows you understand the move?", "options": ["Software meets real factory work", "Intrinsic now sells ROS licenses", "Foxconn bought Intrinsic outright"], "correctIndex": 0, "consequences": ["The venture deploys robots in Foxconn’s US plants.", "ROS stays free and open source.", "It is a joint venture, not a purchase."], "explanation": "Intrinsic earns by putting its software to work in factories, not by selling the free code."}, "proReasoning": "Candidates who describe a deal accurately stand out.", "commonMistake": "Misreading a joint venture as an acquisition.", "mentalModel": "Read the deal right."}, "invest": {"call": {"kind": "theCall", "situation": "A friend asks what Alphabet gets from the Foxconn venture.", "prompt": "Which answer is supported by the reporting?", "options": ["Control of Foxconn", "Real factories for its robot software", "A fixed, disclosed revenue figure"], "correctIndex": 1, "consequences": ["It is a joint venture between two companies.", "Robots will deploy in Foxconn’s US plants.", "Neither side disclosed the money involved."], "explanation": "The venture gives Intrinsic’s software real production work. The terms were not disclosed."}, "proReasoning": "Investors note what a deal discloses and what it leaves out.", "commonMistake": "Inventing numbers a deal never gave.", "mentalModel": "Mind the missing terms.", "sources": [{"url": "https://fortune.com/2025/11/20/alphabet-intrinsic-foxconn-intelligent-robots-ai-joint-venture/", "label": "Fortune, Alphabet's Intrinsic and Foxconn form a robotics joint venture, Nov 2025"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You build robot software for factories.", "prompt": "What does the Intrinsic deal suggest?", "options": ["Sell only to hobbyists and students online", "Charge for free code", "Partner with a manufacturer to deploy at scale"], "correctIndex": 2, "consequences": ["Factories are where Intrinsic is going.", "Free code cannot be sold.", "A big partner brings real factories to deploy in."], "explanation": "Intrinsic earns by deploying with Foxconn. Factory partners give software a place to prove itself."}, "proReasoning": "Founders find a partner whose factories can run their product at scale.", "commonMistake": "Building factory software without a factory to test in.", "mentalModel": "Find the factory partner."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Google’s parent company cares about factory robots.", "prompt": "What's the best answer?", "options": ["It wants its robot software in real plants", "It plans to build iPhones itself in the US", "It wants to sell ROS"], "correctIndex": 0, "consequences": ["Intrinsic will deploy robots in Foxconn plants.", "Foxconn runs the factories in this venture.", "ROS remains free."], "explanation": "Alphabet’s Intrinsic builds robot software and now has Foxconn’s factories to run it in."}, "proReasoning": "Explain a tech giant’s move by what it brings and what it gets.", "commonMistake": "Thinking big tech stays out of factories.", "mentalModel": "Software goes to the factory."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:08f716306ce5$ml$]::text[]),
($ml$1c425f49-281c-5a68-b9ec-85481d3aa34d$ml$::uuid, $ml$robotics$ml$, 14, 2, $ml${"id": "robotics-d14-c2", "title": "Who governs the code", "lessonTitle": "Alphabet buys the ROS team", "slot": 2, "type": "connect", "brief": {"headline": "Intrinsic bought the company behind ROS in 2022, but the nonprofit foundation kept control of the code. ROS 2 made up 91.2% of downloads in 2025.", "kicker": "Connect day 14 and day 13: who owns the team, and who governs the shared code.", "fullText": "Day 13 showed ROS as the shared free layer many robots run on, with ROS 2 at 91.2% of downloads.\n\nDay 14 showed how the money side was split off. Intrinsic, an Alphabet company, bought the Open Source Robotics Corporation and its Singapore unit in December 2022. The nonprofit Open Source Robotics Foundation kept control of ROS, the Gazebo simulator and Open-RMF.\n\nA big company can buy the people. The foundation still decides the rules of the code.", "sources": [{"url": "https://techcrunch.com/2022/12/15/alphabets-intrinsic-acquires-darpa-backed-firm-behind-open-source-robotics-software/", "label": "TechCrunch, Alphabet's Intrinsic acquires firm behind open source robotics software"}, {"url": "https://discourse.openrobotics.org/t/2025-ros-metrics-report/52575", "label": "Open Robotics Discourse, 2025 ROS metrics report"}]}, "evidence": {"kind": "sortSignal", "prompt": "After the 2022 deal, who holds each piece?", "buckets": ["Nonprofit foundation", "Intrinsic"], "items": [{"text": "Control of ROS", "bucket": 0}, {"text": "The Gazebo robot simulator", "bucket": 0}, {"text": "Open-RMF for robot fleets", "bucket": 0}, {"text": "The Open Source Robotics Corporation", "bucket": 1}, {"text": "Its Singapore unit", "bucket": 1}], "explanation": "Intrinsic bought the for-profit company. The foundation kept governance of the code and projects."}, "numbers": {"kind": "numberSense", "prompt": "ROS 2 made up what share of ROS downloads in 2025?", "min": 0, "max": 100, "value": 91.2, "unit": "%", "explanation": "91.2%. The foundation governs the version most teams now use."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A robot company asks if ROS is safe to build on after the Alphabet deal.", "prompt": "Which answer is most accurate?", "options": ["ROS was shut down", "The foundation still governs the code", "Alphabet now owns the ROS code outright"], "correctIndex": 1, "consequences": ["ROS 2 reached 91.2% of downloads in 2025.", "The nonprofit kept control of ROS.", "Intrinsic bought the company, not the code’s governance."], "explanation": "The foundation kept control of ROS. Governance, not ownership of the team, protects users."}, "proReasoning": "Candidates who separate ownership from governance show depth.", "commonMistake": "Assuming whoever buys the team owns the code.", "mentalModel": "Governance protects users."}, "invest": {"call": {"kind": "theCall", "situation": "Alphabet gained ROS talent but not the code's governance.", "prompt": "What did Alphabet gain?", "options": ["Exclusive rights to ROS", "A paid license from every user", "Influence without owning the code"], "correctIndex": 2, "consequences": ["ROS remains open for everyone.", "ROS is free to use.", "It hired the builders of the most used robot software."], "explanation": "Owning the team behind shared software gives a giant influence without owning the code."}, "proReasoning": "Investors notice influence that does not show up as ownership.", "commonMistake": "Looking only at legal ownership.", "mentalModel": "Influence beats ownership.", "sources": [{"url": "https://techcrunch.com/2022/12/15/alphabets-intrinsic-acquires-darpa-backed-firm-behind-open-source-robotics-software/", "label": "TechCrunch, Alphabet's Intrinsic acquires firm behind open source robotics software"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your product depends heavily on ROS.", "prompt": "What should you watch?", "options": ["Who governs the code and how", "Who owns the most robot companies", "Which robots look best"], "correctIndex": 0, "consequences": ["Governance decides how the code you rely on changes.", "Ownership of companies is a different question.", "Looks do not affect your dependency."], "explanation": "A foundation is steadier than one firm. Check who governs the code you depend on."}, "proReasoning": "Founders track the governance of their key dependencies.", "commonMistake": "Ignoring who controls the code under your product.", "mentalModel": "Watch governance."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks Google owns the robot software ROS.", "prompt": "What's a fair correction?", "options": ["No one governs ROS", "A nonprofit foundation still governs it", "Yes, Google owns all of it now, code included"], "correctIndex": 1, "consequences": ["The foundation governs ROS.", "Intrinsic bought the company; the foundation kept control.", "Ownership of the team is not control of the code."], "explanation": "Alphabet bought the paid side. The nonprofit foundation still controls ROS."}, "proReasoning": "Correct a common belief with one clear fact.", "commonMistake": "Confusing a company purchase with control of free code.", "mentalModel": "Team bought, code governed."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ee309799e151$ml$]::text[]),
($ml$cedfc39b-40be-5c1c-98c5-8e93b2fe6f8c$ml$::uuid, $ml$robotics$ml$, 14, 3, $ml${"id": "robotics-d14-c3", "title": "Building on code a giant touches", "lessonTitle": "Alphabet buys the ROS team", "slot": 3, "type": "decide", "brief": {"headline": "You run a robot startup that relies on Gazebo, the open-source simulator. A rival tells you Alphabet controls it now.", "kicker": "Decide: do you keep building on it?", "fullText": "Day 14 showed the 2022 deal. Intrinsic bought the Open Source Robotics Corporation, the for-profit arm, but the nonprofit Open Source Robotics Foundation kept control of ROS, Gazebo and Open-RMF.\n\nThe foundation began in 2012, and DARPA awarded its first contract. Open-source code is free to use, so the money flows to people who build and support it.\n\nYour whole test pipeline runs on Gazebo.", "sources": [{"url": "https://techcrunch.com/2022/12/15/alphabets-intrinsic-acquires-darpa-backed-firm-behind-open-source-robotics-software/", "label": "TechCrunch, Alphabet's Intrinsic acquires firm behind open source robotics software"}]}, "evidence": {"kind": "faceOff", "prompt": "Who kept control of Gazebo after the 2022 deal?", "left": {"name": "The nonprofit foundation", "note": "Open Source Robotics Foundation"}, "right": {"name": "Alphabet’s Intrinsic", "note": "Bought the for-profit company"}, "correctIndex": 0, "explanation": "The foundation kept control of ROS, Gazebo and Open-RMF."}, "numbers": {"kind": "numberSense", "prompt": "After the deal, the foundation kept control of how many named projects: ROS, Gazebo and Open-RMF?", "min": 0, "max": 10, "value": 3, "unit": "", "explanation": "Three projects, all still governed by the nonprofit foundation."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As the startup's lead engineer, you answer the rival's claim.", "prompt": "What do you check?", "options": ["Who is the richest company", "Which simulator looks nicest", "Who governs Gazebo today"], "correctIndex": 2, "consequences": ["Wealth is not governance.", "Looks do not decide the dependency risk.", "The foundation kept control after the deal."], "explanation": "Check governance before reacting. The foundation still controls Gazebo."}, "proReasoning": "Engineers verify claims about dependencies before rewriting anything.", "commonMistake": "Switching tools because of a rumor.", "mentalModel": "Verify before switching."}, "invest": {"call": {"kind": "theCall", "situation": "A startup worries Alphabet could close Gazebo.", "prompt": "How do you weigh the risk?", "options": ["Low, the foundation governs it", "High, Alphabet owns it outright", "Certain, it closes next year"], "correctIndex": 0, "consequences": ["Governance stayed with the nonprofit.", "Intrinsic bought the company, not the project.", "Nothing points to a closure."], "explanation": "A foundation is steadier than one firm. Gazebo’s governance stayed independent."}, "proReasoning": "Investors judge dependency risk by governance, not headlines.", "commonMistake": "Overreacting to who bought what.", "mentalModel": "Judge by governance.", "sources": [{"url": "https://techcrunch.com/2022/12/15/alphabets-intrinsic-acquires-darpa-backed-firm-behind-open-source-robotics-software/", "label": "TechCrunch, Alphabet's Intrinsic acquires firm behind open source robotics software"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "You can keep Gazebo or pay for a closed simulator.", "prompt": "What makes the most sense?", "options": ["Fork Gazebo yourself today", "Keep Gazebo and watch its governance", "Switch to a paid tool right now"], "correctIndex": 1, "consequences": ["Forking adds upkeep you may not need.", "It stays free, governed by the foundation.", "Switching costs time for no proven reason."], "explanation": "The code you rely on is governed by a foundation. Keep using it and keep watching."}, "proReasoning": "Founders avoid costly moves based on misread news.", "commonMistake": "Rewriting your pipeline on a rumor.", "mentalModel": "Stay and watch."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a company can buy the ROS team but not ROS.", "prompt": "What's the best answer?", "options": ["The code was destroyed after the deal", "ROS was sold twice", "The nonprofit kept control of the code"], "correctIndex": 2, "consequences": ["ROS continues and grew.", "One company was bought; the code stayed governed.", "Intrinsic bought the company; the foundation kept ROS."], "explanation": "Open-source code can be governed by a nonprofit while its builders work for a company."}, "proReasoning": "Explain open source by separating people from governance.", "commonMistake": "Thinking code always belongs to whoever pays its builders.", "mentalModel": "People and code can split."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bd10c291bfc2$ml$]::text[]),
($ml$ad0ec0f2-4baa-5ff3-94e6-89a812e4ed8f$ml$::uuid, $ml$robotics$ml$, 15, 1, $ml${"id": "robotics-d15-c1", "title": "Google's robot brain in two parts", "lessonTitle": "Nvidia's open robot brain", "slot": 1, "type": "apply", "brief": {"headline": "In September 2025, Google DeepMind released Gemini Robotics 1.5 and Gemini Robotics-ER 1.5. One plans the task; the other turns plans into motor commands.", "kicker": "Apply the slow and fast brain idea: how does one model control different robots?", "fullText": "Gemini Robotics-ER 1.5 reasons about the physical world, can call tools such as Google Search, and builds multi-step plans. It then gives natural-language instructions to Gemini Robotics 1.5, a vision-language-action model that turns what it sees into motor commands.\n\nDeepMind says the model transfers motions between robots. Tasks shown only to the ALOHA 2 robot in training also worked on Apptronik's Apollo humanoid and a two-armed Franka robot.\n\nDevelopers can use the ER model through the Gemini API. The action model went only to select partners.", "sources": [{"url": "https://deepmind.google/blog/gemini-robotics-15-brings-ai-agents-into-the-physical-world/", "label": "Google DeepMind, Gemini Robotics 1.5, Sep 2025"}, {"url": "https://www.maginative.com/article/nvidia-unveils-isaac-gr00t-n1-an-open-foundation-model-for-humanoid-robots/", "label": "Maginative, Nvidia unveils Isaac GR00T N1"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which Gemini model does each job?", "buckets": ["Robotics-ER 1.5", "Robotics 1.5"], "items": [{"text": "Builds a multi-step plan", "bucket": 0}, {"text": "Calls tools like Google Search", "bucket": 0}, {"text": "Turns what it sees into motor commands", "bucket": 1}, {"text": "Moves the robot step by step", "bucket": 1}], "explanation": "The ER model plans and orchestrates. The action model turns each step into motion."}, "numbers": {"kind": "numberSense", "prompt": "Tasks learned on one robot worked on how many robot types in total, as DeepMind named them?", "min": 0, "max": 10, "value": 3, "unit": "", "explanation": "Three: ALOHA 2, Apptronik’s Apollo and a bi-arm Franka robot."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at a robot AI lab.", "prompt": "Which point shows you understand Gemini Robotics 1.5?", "options": ["It works on a single robot type", "A planner model directs an action model", "One model that only answers text questions"], "correctIndex": 1, "consequences": ["DeepMind showed transfer across three robots.", "ER plans; the action model moves.", "It also controls motion."], "explanation": "DeepMind split planning from acting, like GR00T N1’s slow and fast systems."}, "proReasoning": "Candidates who explain the architecture, not just the name, stand out.", "commonMistake": "Describing a robot model as a chatbot.", "mentalModel": "Plan slow, act fast."}, "invest": {"call": {"kind": "theCall", "situation": "A friend says DeepMind now sells a robot brain to everyone.", "prompt": "What is accurate?", "options": ["Both models are open to all developers", "Neither model is usable", "Only the planner is open via the API"], "correctIndex": 2, "consequences": ["Gemini Robotics 1.5 was limited to partners.", "ER 1.5 is available through the Gemini API.", "The action model went to select partners only."], "explanation": "The planning model is broadly available. The model that moves robots stayed with select partners."}, "proReasoning": "Investors read access terms closely; they shape who can build on a platform.", "commonMistake": "Assuming every announced model is widely available.", "mentalModel": "Read the access terms.", "sources": [{"url": "https://deepmind.google/blog/gemini-robotics-15-brings-ai-agents-into-the-physical-world/", "label": "Google DeepMind, Gemini Robotics 1.5, Sep 2025"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds robots for small shops.", "prompt": "How could you use these models?", "options": ["Start from the planner via the API", "Train a full model from zero", "Wait for one model per robot"], "correctIndex": 0, "consequences": ["ER 1.5 is open to developers now.", "Training from scratch takes years and data.", "Transfer across robots is the point."], "explanation": "An open planning model saves years. Your edge is your task data and your customers."}, "proReasoning": "Founders build on available models and compete on data and deployment.", "commonMistake": "Rebuilding what a lab already offers.", "mentalModel": "Build on the model."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how one AI could control robots with different bodies.", "prompt": "What's the best answer?", "options": ["It controls only one robot", "It transfers learned motions between robots", "Each of the robots has exactly the same body"], "correctIndex": 1, "consequences": ["Transfer across bodies was the claim.", "DeepMind showed tasks moving from ALOHA 2 to Apollo and Franka.", "The three robots have different bodies."], "explanation": "Gemini Robotics 1.5 learned on one robot and worked on others. Skills moved between bodies."}, "proReasoning": "Explain transfer with a concrete example of different bodies.", "commonMistake": "Thinking robot AI must be trained separately for every robot.", "mentalModel": "Skills can move bodies."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c84a89473b18$ml$]::text[]),
($ml$cda835da-4cdb-5a45-8112-8bd42f8af52c$ml$::uuid, $ml$robotics$ml$, 15, 2, $ml${"id": "robotics-d15-c2", "title": "The model meets the chip", "lessonTitle": "Nvidia's open robot brain", "slot": 2, "type": "connect", "brief": {"headline": "Nvidia's GR00T N1 splits a slow planner from a fast mover. Its Jetson Thor chip delivers 7.5 times the AI compute of the older Orin.", "kicker": "Connect day 15 and day 10: the shared robot model, and the brain it runs on.", "fullText": "Day 10 showed Nvidia’s Jetson Thor, at $3,499 for a developer kit, with 7.5 times Orin’s AI compute and up to 130 watts of draw.\n\nDay 15 showed Nvidia’s GR00T N1, an open foundation model for humanoids. A slower system reasons about the scene and instructions; a fast system turns plans into precise movements. Early adopters included Boston Dynamics, Agility Robotics, 1X, Mentee Robotics and NEURA Robotics.\n\nNvidia now offers both the model and the computer that runs it on the robot.", "sources": [{"url": "https://www.maginative.com/article/nvidia-unveils-isaac-gr00t-n1-an-open-foundation-model-for-humanoid-robots/", "label": "Maginative, Nvidia unveils Isaac GR00T N1"}, {"url": "https://www.theregister.com/2025/08/25/nvidia_touts_jetson_thor_kit/", "label": "The Register, Nvidia touts Jetson Thor kit"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a GR00T N1 task on a robot in order.", "steps": ["A person gives an instruction", "The slow system reasons about the scene", "It plans the steps", "The fast system turns them into motions", "The onboard chip runs it all on battery"], "explanation": "Planning and acting both run on the robot’s onboard computer, within its power budget."}, "numbers": {"kind": "numberSense", "prompt": "Nvidia claims Thor delivers how many times the AI compute of Jetson Orin?", "min": 0, "max": 20, "value": 7.5, "unit": "x", "explanation": "7.5 times, so bigger models can run on board."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A humanoid maker asks why Nvidia matters to its roadmap.", "prompt": "Which answer connects the lessons?", "options": ["It builds and sells humanoid bodies", "It only makes gaming cards", "It supplies both the model and the chip"], "correctIndex": 2, "consequences": ["Nvidia sells brains, not bodies.", "It sells robot chips and models too.", "GR00T N1 runs on Thor-class onboard compute."], "explanation": "Nvidia sells robot chips and now offers the model too. Rivals build on both."}, "proReasoning": "Candidates who see the platform behind products show strategic sense.", "commonMistake": "Seeing chips and models as separate bets.", "mentalModel": "Model plus chip."}, "invest": {"call": {"kind": "theCall", "situation": "Boston Dynamics, Agility and 1X all adopted GR00T N1.", "prompt": "What does that suggest about Nvidia?", "options": ["Its hold deepens whoever wins", "It must pick one winner", "It competes with them on robots"], "correctIndex": 0, "consequences": ["Rivals building on it all feed Nvidia’s platform.", "Nvidia supplies several rivals at once.", "Nvidia does not sell humanoid bodies here."], "explanation": "When rivals share one model and chip supplier, that supplier wins across the field."}, "proReasoning": "Investors look for suppliers that win no matter which robot maker wins.", "commonMistake": "Betting only on the robot makers.", "mentalModel": "Sell to every rival.", "sources": [{"url": "https://www.maginative.com/article/nvidia-unveils-isaac-gr00t-n1-an-open-foundation-model-for-humanoid-robots/", "label": "Maginative, Nvidia unveils Isaac GR00T N1"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Your humanoid startup weighs Nvidia’s stack against building your own.", "prompt": "What is the trade-off?", "options": ["Building your own is always faster", "Speed now versus dependence later", "No trade-off at all"], "correctIndex": 1, "consequences": ["Training your own model takes years.", "The stack saves years but ties you to one supplier.", "Every platform choice has costs."], "explanation": "An open model and ready chip save years. The cost is relying on one platform."}, "proReasoning": "Founders accept dependence knowingly, with a plan to manage it.", "commonMistake": "Ignoring the lock-in that comes with a fast start.", "mentalModel": "Speed has a price."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a chip company releases a free robot model.", "prompt": "What's the best answer?", "options": ["It wants to stop selling chips entirely", "Free models are required by law", "More robots on its model need its chips"], "correctIndex": 2, "consequences": ["Chips remain its business.", "There is no such law.", "Robots running GR00T N1 run on onboard compute like Thor."], "explanation": "A free model draws robot makers in. Running it on board needs Nvidia’s chips."}, "proReasoning": "Explain a free product by what it helps sell.", "commonMistake": "Thinking free means no business purpose.", "mentalModel": "Free model, paid chip."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b15e9ea18da0$ml$]::text[]),
($ml$ce7a3f40-e2e8-524b-aad2-a347e137a655$ml$::uuid, $ml$robotics$ml$, 15, 3, $ml${"id": "robotics-d15-c3", "title": "Fine-tune or train from scratch", "lessonTitle": "Nvidia's open robot brain", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup building a humanoid for kitchens. You can fine-tune an open foundation model or spend two years training your own.", "kicker": "Decide: where should your edge come from?", "fullText": "Day 15 showed Nvidia’s Isaac GR00T N1, released in March 2025 as an open foundation model for humanoid robots. A foundation model is trained broadly, then adapted to many specific tasks.\n\nGR00T N1 uses a slow system to reason and plan and a fast system to move. Boston Dynamics, Agility Robotics, 1X, Mentee Robotics and NEURA Robotics were early adopters.\n\nYour team has a rare dataset: thousands of hours of kitchen work.", "sources": [{"url": "https://www.maginative.com/article/nvidia-unveils-isaac-gr00t-n1-an-open-foundation-model-for-humanoid-robots/", "label": "Maginative, Nvidia unveils Isaac GR00T N1"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan gets a kitchen robot working sooner?", "left": {"name": "Fine-tune the open model", "note": "Adapt it with your kitchen data"}, "right": {"name": "Train your own from scratch", "note": "Two years before first results"}, "correctIndex": 0, "explanation": "An open foundation model saves years. Your kitchen data does the adapting."}, "numbers": {"kind": "numberSense", "prompt": "How many early GR00T N1 adopters did Nvidia name?", "min": 0, "max": 15, "value": 5, "unit": "", "explanation": "Five: Boston Dynamics, Agility Robotics, 1X, Mentee Robotics and NEURA Robotics."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "As the startup's AI lead, you recommend a plan.", "prompt": "What do you propose?", "options": ["Fine-tune the open model on our data", "Train a brand new model from zero", "Skip AI and script every move"], "correctIndex": 0, "consequences": ["It saves years and uses our real edge.", "Two years of training delays the product.", "Kitchens change too much for fixed scripts."], "explanation": "Start from an open model. Your edge is your kitchen data and the task."}, "proReasoning": "AI leads put scarce effort where the team is unique.", "commonMistake": "Spending years rebuilding a shared foundation.", "mentalModel": "Fine-tune, don’t rebuild."}, "invest": {"call": {"kind": "theCall", "situation": "A kitchen robot startup asks for funding to train its own base model.", "prompt": "What do you question?", "options": ["Why not sell in more colors?", "Why not start from an open model?", "Why not hire more designers?"], "correctIndex": 1, "consequences": ["Colors are irrelevant.", "Open models save years of training.", "Design hires do not answer the model question."], "explanation": "An open foundation model saves years. Funding should go to data and the task."}, "proReasoning": "Investors ask whether a company is building what it could borrow.", "commonMistake": "Funding work that duplicates a free platform.", "mentalModel": "Fund the unique part.", "sources": [{"url": "https://www.maginative.com/article/nvidia-unveils-isaac-gr00t-n1-an-open-foundation-model-for-humanoid-robots/", "label": "Maginative, Nvidia unveils Isaac GR00T N1"}]}, "build_startup": {"call": {"kind": "theCall", "situation": "Rivals can fine-tune the same open model.", "prompt": "What keeps your kitchen robot ahead?", "options": ["Using the same model as everyone", "Hiding which model you use", "Your rare kitchen data and deployments"], "correctIndex": 2, "consequences": ["The shared model is not an edge.", "Secrecy does not make a robot better.", "Rivals lack your thousands of hours of kitchen work."], "explanation": "If everyone starts from the same model, data and deployment decide who wins."}, "proReasoning": "Founders protect what others cannot easily copy: data and customers.", "commonMistake": "Thinking the model itself is the moat.", "mentalModel": "Data is the moat."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why startups would share one AI model instead of building their own.", "prompt": "What's the best answer?", "options": ["It saves years; they compete on data", "They are forced to share it", "Their robots are all identical"], "correctIndex": 0, "consequences": ["A foundation model is trained broadly, then adapted.", "GR00T N1 is open, not mandatory.", "Their robots and tasks differ."], "explanation": "A shared base saves years. Each startup adapts it with its own data and tasks."}, "proReasoning": "Explain a shared model like a shared engine: same base, different cars.", "commonMistake": "Thinking every company must build everything itself.", "mentalModel": "Shared base, own data."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a0f7b267ebf9$ml$]::text[])
